insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-72', 'Meenakshi: ''I can''t decide without him'' (dependent personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-72-1","text":"Cannot make daily decisions without her husband''s advice","bucket":"presenting"},{"id":"form-72-2","text":"Kind and conscientious; good with children","bucket":"protective"},{"id":"form-72-3","text":"Overprotective parents who decided everything","bucket":"predisposing"},{"id":"form-72-4","text":"Married young straight from her parents'' home","bucket":"predisposing"},{"id":"form-72-5","text":"Avoids tasks alone, so never builds confidence","bucket":"perpetuating"},{"id":"form-72-6","text":"Calls him many times a day for every decision","bucket":"perpetuating"},{"id":"form-72-7","text":"Husband transferred to another state for a year","bucket":"precipitating"},{"id":"form-72-8","text":"Supportive older sister","bucket":"protective"},{"id":"form-72-9","text":"Relatives step in and take over","bucket":"perpetuating"},{"id":"form-72-10","text":"Panic and low mood since he was posted away","bucket":"presenting"},{"id":"form-72-11","text":"Their flat has a balcony garden","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Meenakshi, 36, presents with dependent personality disorder: a long-standing need for others to make decisions, with panic and low mood since her husband moved away. Overprotective parenting and marriage straight from her parents'' home (predisposing) left her without independent experience; the transfer (precipitating) exposed the pattern. Constant calls for advice, avoidance and relatives taking over (perpetuating) keep her confidence low. A supportive sister and her conscientiousness (protective) support assertiveness and decision-making skills built step by step.","hint":"A woman frozen after her husband''s transfer","tags":{"topic":"personality","difficulty":3,"objective":"Formulate a dependent pattern exposed by separation","exams":["md-psychiatry","ugc-net","mcp-entrance"],"module":"personality","diagnosis":"Dependent personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-73', 'Rohit: the founder who cannot hear criticism (narcissistic personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-73-1","text":"Lifelong grandiosity, need for admiration and rage at criticism","bucket":"presenting"},{"id":"form-73-2","text":"Drinks to numb the shame","bucket":"perpetuating"},{"id":"form-73-3","text":"Withdraws from friends who saw him fail","bucket":"perpetuating"},{"id":"form-73-4","text":"Blames others and avoids feedback","bucket":"perpetuating"},{"id":"form-73-5","text":"Parents who praised him as special but were cold when he failed","bucket":"predisposing"},{"id":"form-73-6","text":"Low mood and shame after his start-up failed","bucket":"presenting"},{"id":"form-73-7","text":"Long-time friend who still calls","bucket":"protective"},{"id":"form-73-8","text":"His office was in a co-working space","bucket":"distractor"},{"id":"form-73-9","text":"Talent that brought early success","bucket":"predisposing"},{"id":"form-73-10","text":"Investors pulled out and co-founders quit","bucket":"precipitating"},{"id":"form-73-11","text":"Real abilities and work ethic","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rohit, 33, presents with a depressive episode against the background of narcissistic personality disorder: grandiosity and need for admiration that hide fragile self-esteem. Conditional parental warmth and early success (predisposing) built a self-image that could not tolerate failure; the start-up collapse (precipitating) shattered it. Blaming others, withdrawal from those who saw him fail and drinking (perpetuating) deepen the low mood. A loyal friend and genuine abilities (protective) allow treatment of the depression, a risk check given the shame and drinking, and longer work on self-esteem.","hint":"A start-up founder whose co-founders quit","tags":{"topic":"personality","difficulty":5,"objective":"Formulate a fragile self-esteem pattern with depression","exams":["md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Narcissistic personality disorder with a depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-74', 'Swati: the cut on her wrist after the fight (adolescent self-harm)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-74-1","text":"Hides it with long sleeves, so no one helps","bucket":"perpetuating"},{"id":"form-74-2","text":"Parents'' frequent fights and a threat of divorce","bucket":"precipitating"},{"id":"form-74-3","text":"A cousin self-harmed and posted about it online","bucket":"predisposing"},{"id":"form-74-4","text":"Cutting brings fast relief from overwhelming feelings","bucket":"perpetuating"},{"id":"form-74-5","text":"Intense temperament","bucket":"predisposing"},{"id":"form-74-6","text":"Talented at painting","bucket":"protective"},{"id":"form-74-7","text":"Cuts her forearm after arguments, about once a week for four months","bucket":"presenting"},{"id":"form-74-8","text":"Her school is co-educational","bucket":"distractor"},{"id":"form-74-9","text":"Low mood and irritability","bucket":"presenting"},{"id":"form-74-10","text":"Online groups that share self-harm images","bucket":"perpetuating"},{"id":"form-74-11","text":"Close to her grandmother","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Swati, 15, presents with repeated self-harm by cutting after arguments, with low mood and irritability. An intense temperament and exposure to a cousin''s self-harm (predisposing) raised her risk; constant parental conflict and divorce threats (precipitating) began it. Fast relief from cutting, secrecy and online self-harm communities (perpetuating) maintain it. Her grandmother and painting (protective) are strengths for a safety plan, family work on conflict and skills for coping with intense feelings, with careful assessment of suicidal intent.","hint":"A 15-year-old who cuts after arguments with her mother","tags":{"topic":"suicide-risk","difficulty":3,"objective":"Formulate self-harm as emotion regulation with risk factors","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"suicide","diagnosis":"Repeated self-harm in an adolescent with emotional dysregulation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-75', 'Mrs Fernandes: since the fall she stays home (fear of falling)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-75-1","text":"Values independence intensely","bucket":"predisposing"},{"id":"form-75-2","text":"Daughter who visits often","bucket":"protective"},{"id":"form-75-3","text":"Has stopped going to church and the market","bucket":"presenting"},{"id":"form-75-4","text":"Inactivity weakens her legs, raising real fall risk","bucket":"perpetuating"},{"id":"form-75-5","text":"Fell on market steps and bruised her hip","bucket":"precipitating"},{"id":"form-75-6","text":"Knee arthritis and cataract","bucket":"predisposing"},{"id":"form-75-7","text":"Fear that another fall means an old-age home","bucket":"perpetuating"},{"id":"form-75-8","text":"Nursing knowledge and good insight","bucket":"protective"},{"id":"form-75-9","text":"Groceries delivered, so no need to go out","bucket":"perpetuating"},{"id":"form-75-10","text":"She was born in Margao","bucket":"distractor"},{"id":"form-75-11","text":"Will not go out alone since a fall six months ago","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Fernandes, 74, presents with fear of falling with agoraphobic avoidance since a fall. Knee arthritis, cataract and a strong value on independence (predisposing) shape both real risk and fear; the market fall (precipitating) began the avoidance. Inactivity that weakens her, delivery services that remove the need to go out and fear of losing her home (perpetuating) keep it going. Her nursing knowledge and a visiting daughter (protective) support physiotherapy, cataract review and graded return to church and the market.","hint":"A 74-year-old retired nurse","tags":{"topic":"anxiety","difficulty":2,"objective":"Show physical and psychological factors together in late life","exams":["mcp-entrance","ma-semester"],"module":"anxiety","diagnosis":"Fear of falling with agoraphobic avoidance"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-76', 'Mr Rathore: the steps he takes in his sleep (REM sleep behaviour disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-76-1","text":"Hit his wife while asleep","bucket":"presenting"},{"id":"form-76-2","text":"Wife who keeps a sleep diary","bucket":"protective"},{"id":"form-76-3","text":"Male, aged 66","bucket":"predisposing"},{"id":"form-76-4","text":"Sleeps in a room with sharp furniture edges","bucket":"perpetuating"},{"id":"form-76-5","text":"Reduced sense of smell for some years","bucket":"predisposing"},{"id":"form-76-6","text":"He retired from the railways","bucket":"distractor"},{"id":"form-76-7","text":"An antidepressant started for low mood may worsen episodes","bucket":"perpetuating"},{"id":"form-76-8","text":"Episodes became frequent over the past year","bucket":"precipitating"},{"id":"form-76-9","text":"Shouts, kicks and punches during vivid dreams of being attacked","bucket":"presenting"},{"id":"form-76-10","text":"Seeks help early","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Rathore, 66, presents with REM sleep behaviour disorder: acting out violent dreams with injury to his wife. Older male sex and a reduced sense of smell (predisposing) are notable because this disorder can be an early sign of later conditions such as Parkinson''s disease or Lewy body dementia; episodes have increased over the year (precipitating). An unsafe bedroom and an antidepressant that can worsen REM behaviour (perpetuating) add risk. His wife''s diary and early help-seeking (protective) support sleep study confirmation, bedroom safety, medicine review and long-term neurological follow-up, discussed sensitively.","hint":"A 66-year-old who punched his wife in a dream","tags":{"topic":"sleep","difficulty":5,"objective":"Formulate a sleep disorder that signals future neurological risk","exams":["md-psychiatry"],"module":"neurocognitive","diagnosis":"REM sleep behaviour disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-77', 'Sana: asleep at her desk (narcolepsy)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-77-1","text":"Knees buckle when she laughs (cataplexy); vivid dreams on falling asleep","bucket":"presenting"},{"id":"form-77-2","text":"Supportive roommate","bucket":"protective"},{"id":"form-77-3","text":"Labelled lazy by teachers and family","bucket":"perpetuating"},{"id":"form-77-4","text":"Avoids laughing in public out of fear","bucket":"perpetuating"},{"id":"form-77-5","text":"No family history known","bucket":"predisposing"},{"id":"form-77-6","text":"Her favourite subject is constitutional law","bucket":"distractor"},{"id":"form-77-7","text":"Symptoms became disabling with long lecture hours at law school","bucket":"precipitating"},{"id":"form-77-8","text":"Overwhelming daytime sleepiness and sudden sleep attacks","bucket":"presenting"},{"id":"form-77-9","text":"Onset in late teens, typical age","bucket":"predisposing"},{"id":"form-77-10","text":"Drinks many energy drinks, which disturbs night sleep","bucket":"perpetuating"},{"id":"form-77-11","text":"Determined to finish her degree","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sana, 21, presents with narcolepsy with cataplexy: severe daytime sleepiness, sleep attacks, muscle weakness triggered by laughter and vivid dreams at sleep onset. Onset in late adolescence (predisposing) is typical; long lectures (precipitating) made it disabling. Being called lazy, energy drinks that worsen night sleep and avoidance of laughter (perpetuating) add to the burden. A supportive roommate and her determination (protective) support sleep studies, medicine, planned naps and academic adjustments.","hint":"A law student who falls asleep mid-sentence and drops things when she laughs","tags":{"topic":"sleep","difficulty":4,"objective":"Recognise a neurological sleep disorder mislabelled as laziness","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Narcolepsy type 1 (with cataplexy)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-78', 'Harish: the frightening dreams of the flood (nightmare disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-78-1","text":"His boat is painted blue","bucket":"distractor"},{"id":"form-78-2","text":"Works long night shifts on the river","bucket":"predisposing"},{"id":"form-78-3","text":"Wakes from vivid drowning nightmares four nights a week for six months","bucket":"presenting"},{"id":"form-78-4","text":"Afraid to go to sleep","bucket":"presenting"},{"id":"form-78-5","text":"Lost a friend in a river accident as a teen","bucket":"predisposing"},{"id":"form-78-6","text":"Drinks to fall asleep","bucket":"perpetuating"},{"id":"form-78-7","text":"Rehearses the dream on waking","bucket":"perpetuating"},{"id":"form-78-8","text":"Willing to try new techniques","bucket":"protective"},{"id":"form-78-9","text":"Rescued people during a flood last monsoon","bucket":"precipitating"},{"id":"form-78-10","text":"Delays sleep to avoid dreams, causing sleep deprivation","bucket":"perpetuating"},{"id":"form-78-11","text":"Close-knit fishing community","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Harish, 40, presents with nightmare disorder after trauma: frequent, vivid drowning nightmares with fear of sleep; he should also be screened for PTSD. An earlier traumatic loss and long night work (predisposing) increase vulnerability; flood rescue work (precipitating) began the nightmares. Sleep avoidance, drinking to sleep and rehearsing the dream (perpetuating) maintain them. His community and openness (protective) support imagery rehearsal therapy, sleep scheduling and alcohol reduction.","hint":"A boatman who dreams of drowning nightly","tags":{"topic":"trauma","difficulty":2,"objective":"Formulate nightmares with trauma and sleep factors","exams":["mcp-entrance","ma-semester"],"module":"trauma","diagnosis":"Nightmare disorder after trauma (screen for PTSD)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-79', 'Divya: the miscarriage nobody talks about (grief after pregnancy loss)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-79-1","text":"Took two years to conceive","bucket":"predisposing"},{"id":"form-79-2","text":"Family say ''try again quickly'' and do not mention the loss","bucket":"perpetuating"},{"id":"form-79-3","text":"Avoids pregnant friends and baby showers","bucket":"presenting"},{"id":"form-79-4","text":"The hospital had a new maternity wing","bucket":"distractor"},{"id":"form-79-5","text":"Blames herself for lifting a heavy bag","bucket":"perpetuating"},{"id":"form-79-6","text":"Friend who had a similar loss","bucket":"protective"},{"id":"form-79-7","text":"Miscarriage at 14 weeks","bucket":"precipitating"},{"id":"form-79-8","text":"Past anxiety","bucket":"predisposing"},{"id":"form-79-9","text":"Low mood, crying and guilt for three months after a 14-week miscarriage","bucket":"presenting"},{"id":"form-79-10","text":"Husband who grieves with her","bucket":"protective"},{"id":"form-79-11","text":"Avoids all reminders, so grief stays raw","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Divya, 31, presents with a depressive episode after a miscarriage: three months of low mood, guilt and avoidance of pregnancy reminders. Past anxiety and a long time to conceive (predisposing) raised the stakes; the loss at 14 weeks (precipitating) began it. A family that will not acknowledge the loss, self-blame about lifting a bag and avoidance (perpetuating) block grieving. A husband who shares the grief and a friend with a similar loss (protective) support validation of the loss, correction of self-blame, and treatment of the depression before planning another pregnancy.","hint":"A woman low since losing a pregnancy at 14 weeks","tags":{"topic":"perinatal","difficulty":3,"objective":"Formulate grief that the family will not acknowledge","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"depression","diagnosis":"Depressive episode after pregnancy loss"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-80', 'Mr Mehta: the dementia that came in steps (vascular dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-80-1","text":"Wife and son engaged in care","bucket":"protective"},{"id":"form-80-2","text":"Previous small strokes","bucket":"predisposing"},{"id":"form-80-3","text":"Still enjoys his morning newspaper","bucket":"protective"},{"id":"form-80-4","text":"He owned a sweet shop","bucket":"distractor"},{"id":"form-80-5","text":"Sits at home, inactive","bucket":"perpetuating"},{"id":"form-80-6","text":"Still smokes","bucket":"perpetuating"},{"id":"form-80-7","text":"Each step down followed a ''small attack'' or hospital stay","bucket":"precipitating"},{"id":"form-80-8","text":"Long-standing hypertension, diabetes and smoking","bucket":"predisposing"},{"id":"form-80-9","text":"Low mood and emotional lability","bucket":"presenting"},{"id":"form-80-10","text":"Stepwise decline in planning, slowness and memory over three years","bucket":"presenting"},{"id":"form-80-11","text":"Poorly controlled blood pressure and sugar","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Mehta, 72, presents with vascular neurocognitive disorder: stepwise decline in executive function, speed and memory with emotional lability. Hypertension, diabetes, smoking and earlier strokes (predisposing) caused the brain damage; each small stroke (precipitating) produced a step down. Poor control of risk factors, ongoing smoking and inactivity (perpetuating) risk further decline. An engaged family and his newspaper habit (protective) support tight risk-factor control, stopping smoking, activity and treatment of low mood.","hint":"A 72-year-old with stepwise decline after small strokes","tags":{"topic":"neurocognitive","difficulty":3,"objective":"Show modifiable risk factors in vascular dementia","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Vascular neurocognitive disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-81', 'Mrs Rao: the visitors only she can see (Lewy body dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-81-1","text":"Age 75","bucket":"predisposing"},{"id":"form-81-2","text":"She used to teach Kannada","bucket":"distractor"},{"id":"form-81-3","text":"Became much worse after a sedating antipsychotic was started for the hallucinations","bucket":"precipitating"},{"id":"form-81-4","text":"Falls and acting out dreams","bucket":"presenting"},{"id":"form-81-5","text":"Fluctuating confusion, vivid visual hallucinations of children and stiffness","bucket":"presenting"},{"id":"form-81-6","text":"Years of acting out dreams before memory problems","bucket":"predisposing"},{"id":"form-81-7","text":"Not distressed by the hallucinations when calmly reassured","bucket":"protective"},{"id":"form-81-8","text":"Daughter who keeps a symptom diary","bucket":"protective"},{"id":"form-81-9","text":"Antipsychotic causing severe stiffness and drowsiness","bucket":"perpetuating"},{"id":"form-81-10","text":"Poor lighting in the evening","bucket":"perpetuating"},{"id":"form-81-11","text":"Family argue that the children are not real","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Rao, 75, presents with dementia with Lewy bodies: fluctuating cognition, recurrent vivid visual hallucinations, parkinsonism and a history of acting out dreams. Age and years of dream-enactment (predisposing) fit the condition; a sedating antipsychotic (precipitating) caused marked worsening, a known dangerous sensitivity in this illness. Ongoing antipsychotic, family arguing about the hallucinations and poor evening light (perpetuating) add to distress. A careful daughter and her calm response to reassurance (protective) support stopping the antipsychotic under review, considering a cholinesterase inhibitor, better lighting and carer education.","hint":"An 75-year-old whose confusion comes and goes","tags":{"topic":"neurocognitive","difficulty":5,"objective":"Formulate Lewy body dementia and its antipsychotic danger","exams":["md-psychiatry"],"module":"neurocognitive","diagnosis":"Dementia with Lewy bodies"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-82', 'Ashok: the uncle who changed before he forgot (frontotemporal dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-82-1","text":"Memory relatively preserved","bucket":"presenting"},{"id":"form-82-2","text":"Age 58","bucket":"predisposing"},{"id":"form-82-3","text":"He drove a jeep for work","bucket":"distractor"},{"id":"form-82-4","text":"Family thought it was a midlife crisis and argued with him","bucket":"perpetuating"},{"id":"form-82-5","text":"Wife committed to his care","bucket":"protective"},{"id":"form-82-6","text":"Two years of disinhibition, loss of empathy, sweet cravings and shoplifting","bucket":"presenting"},{"id":"form-82-7","text":"Father had ''personality change'' in his fifties","bucket":"predisposing"},{"id":"form-82-8","text":"Behaviour became public when caught stealing sweets","bucket":"precipitating"},{"id":"form-82-9","text":"Brother who helps with finances","bucket":"protective"},{"id":"form-82-10","text":"Lost his job, so lacks structure","bucket":"perpetuating"},{"id":"form-82-11","text":"Easy access to sweets and money","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ashok, 58, presents with behavioural variant frontotemporal dementia: disinhibition, apathy, loss of empathy, food cravings and shoplifting with relatively preserved memory. A family history of similar change in midlife (predisposing) suggests a genetic contribution; being caught shoplifting (precipitating) brought it to attention. Misreading it as a midlife crisis, loss of structure and unrestricted access to money and sweets (perpetuating) worsen harm. A committed wife and helpful brother (protective) support neurological assessment, financial safeguards, structured routines and carer support.","hint":"A 58-year-old who started shoplifting sweets","tags":{"topic":"neurocognitive","difficulty":5,"objective":"Formulate early-onset behavioural change","exams":["md-psychiatry","ugc-net"],"module":"neurocognitive","diagnosis":"Behavioural variant frontotemporal dementia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-83', 'Imran: the thyroid behind the tiredness (hypothyroid low mood)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-83-1","text":"Constipation and dry skin","bucket":"presenting"},{"id":"form-83-2","text":"Had a viral illness with neck pain last year","bucket":"predisposing"},{"id":"form-83-3","text":"Mother has thyroid disease","bucket":"predisposing"},{"id":"form-83-4","text":"Symptoms began a few months after the neck pain","bucket":"precipitating"},{"id":"form-83-5","text":"Treated with an antidepressant without thyroid tests","bucket":"perpetuating"},{"id":"form-83-6","text":"Inactivity and weight gain lower mood further","bucket":"perpetuating"},{"id":"form-83-7","text":"Good relationship with his GP","bucket":"protective"},{"id":"form-83-8","text":"He sells mobile phones","bucket":"distractor"},{"id":"form-83-9","text":"Low mood, slowness, weight gain and feeling cold for six months","bucket":"presenting"},{"id":"form-83-10","text":"Motivated to get better","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Imran, 40, presents with depressive symptoms due to hypothyroidism: low mood, slowness, weight gain, cold intolerance, constipation and dry skin. A family history of thyroid disease and a likely viral thyroiditis (predisposing) explain the vulnerability; onset months after the neck pain (precipitating) fits. Treatment with an antidepressant without checking thyroid function and resulting inactivity (perpetuating) kept the cause hidden. A good GP relationship and his motivation (protective) support thyroid testing and replacement, then reassessing mood.","hint":"A 40-year-old ''depressed'' man who feels cold all the time","tags":{"topic":"depression","difficulty":3,"objective":"Put a medical cause in the right P","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Depressive symptoms due to hypothyroidism"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-84', 'Neeta: the HIV result and the silence (adjustment with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-84-1","text":"Few confidants","bucket":"predisposing"},{"id":"form-84-2","text":"Fear of stigma means she tells no one","bucket":"perpetuating"},{"id":"form-84-3","text":"Believes the diagnosis means early death","bucket":"perpetuating"},{"id":"form-84-4","text":"She is a tailoring teacher","bucket":"distractor"},{"id":"form-84-5","text":"HIV diagnosis at an antenatal check","bucket":"precipitating"},{"id":"form-84-6","text":"Counsellor at the ART centre","bucket":"protective"},{"id":"form-84-7","text":"Missing antiretroviral doses","bucket":"presenting"},{"id":"form-84-8","text":"Hides tablets, so misses doses","bucket":"perpetuating"},{"id":"form-84-9","text":"Low mood, insomnia and hopelessness since an HIV diagnosis three months ago","bucket":"presenting"},{"id":"form-84-10","text":"Past low spell after her father''s death","bucket":"predisposing"},{"id":"form-84-11","text":"Wants to protect her unborn child","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Neeta, 28, presents with a depressive episode after an HIV diagnosis at an antenatal check: low mood, insomnia, hopelessness and missed antiretroviral doses. A past low spell and few confidants (predisposing) increased risk; the diagnosis (precipitating) began it. Secrecy from fear of stigma, hidden tablets and the false belief that HIV means early death (perpetuating) maintain both mood and poor adherence. A trusted ART counsellor and her wish to protect her baby (protective) support accurate information about treatment and prevention of transmission, treatment of depression and a supported disclosure plan.","hint":"A 28-year-old who has told no one her diagnosis","tags":{"topic":"depression","difficulty":4,"objective":"Formulate stigma and adherence in a chronic illness","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Depressive episode after HIV diagnosis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-85', 'Arun: two years trying for a baby (infertility distress)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-85-1","text":"Loving marriage under the strain","bucket":"protective"},{"id":"form-85-2","text":"Only son expected to continue the family line","bucket":"predisposing"},{"id":"form-85-3","text":"Low mood, irritability and withdrawal since a second failed IVF","bucket":"presenting"},{"id":"form-85-4","text":"Spent savings on treatment","bucket":"perpetuating"},{"id":"form-85-5","text":"They live near a lake","bucket":"distractor"},{"id":"form-85-6","text":"Relatives ask about children at every function","bucket":"perpetuating"},{"id":"form-85-7","text":"Belief that fatherhood proves manhood","bucket":"predisposing"},{"id":"form-85-8","text":"Arguments with his wife","bucket":"presenting"},{"id":"form-85-9","text":"Second failed IVF cycle","bucket":"precipitating"},{"id":"form-85-10","text":"Doctor who offers counselling","bucket":"protective"},{"id":"form-85-11","text":"Avoids talking with his wife about feelings","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arun, 34, presents with an adjustment disorder with low mood after a second failed IVF, with marital strain. Beliefs linking fatherhood to manhood and family pressure as the only son (predisposing) raise the stakes; the second failure (precipitating) triggered it. Relatives'' questions, avoidance of emotional talk and financial strain (perpetuating) maintain it. A loving marriage and an offer of counselling (protective) support couple sessions, sharing decisions about next steps and setting limits with relatives.","hint":"A couple whose IVF failed twice","tags":{"topic":"depression","difficulty":2,"objective":"Formulate distress in a couple, not just one person","exams":["mcp-entrance","ma-semester"],"module":"depression","diagnosis":"Adjustment disorder with low mood (couple stress)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-86', 'Kavya: the counsellor who feels nothing anymore (burnout and depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-86-1","text":"Poor sleep and loss of interest in hobbies","bucket":"presenting"},{"id":"form-86-2","text":"A caller she spoke with died by suicide","bucket":"precipitating"},{"id":"form-86-3","text":"Values her work deeply","bucket":"protective"},{"id":"form-86-4","text":"The helpline uses a cloud phone system","bucket":"distractor"},{"id":"form-86-5","text":"History of a low spell in college","bucket":"predisposing"},{"id":"form-86-6","text":"Strong sense that she must save everyone","bucket":"predisposing"},{"id":"form-86-7","text":"Takes extra shifts to cover staff shortages","bucket":"perpetuating"},{"id":"form-86-8","text":"Emotional numbness at work and low mood at home for four months","bucket":"presenting"},{"id":"form-86-9","text":"No supervision or debriefing at her organisation","bucket":"perpetuating"},{"id":"form-86-10","text":"Close friend from training","bucket":"protective"},{"id":"form-86-11","text":"Stopped her own therapy for lack of time","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kavya, 29, presents with a moderate depressive episode alongside work-related burnout: numbness at work, low mood, poor sleep and anhedonia at home. The spread of symptoms beyond work points to depression, not burnout alone. A rescuer belief and a past low spell (predisposing) shaped vulnerability; a caller''s suicide (precipitating) began it. No supervision, extra shifts and stopping her own therapy (perpetuating) maintain it. A close friend and her values (protective) support treatment, supervision with debriefing, workload limits and grief work about the caller.","hint":"A helpline counsellor after a year of crisis calls","tags":{"topic":"depression","difficulty":4,"objective":"Separate burnout from a depressive episode in a formulation","exams":["mcp-entrance","ma-semester"],"module":"therapies","diagnosis":"Moderate depressive episode with work-related burnout"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-87', 'Prakash: the trembling hand at the chessboard (social anxiety with alcohol)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-87-1","text":"Avoids parent meetings, losing students","bucket":"perpetuating"},{"id":"form-87-2","text":"Shy child with a critical mother","bucket":"predisposing"},{"id":"form-87-3","text":"Lost a televised game after his hand shook visibly","bucket":"precipitating"},{"id":"form-87-4","text":"Hangovers worsen next-day anxiety","bucket":"perpetuating"},{"id":"form-87-5","text":"Brother who supports him","bucket":"protective"},{"id":"form-87-6","text":"Drinks three pegs before any public event","bucket":"presenting"},{"id":"form-87-7","text":"He prefers the Sicilian Defence","bucket":"distractor"},{"id":"form-87-8","text":"Father drank","bucket":"predisposing"},{"id":"form-87-9","text":"Severe fear of being watched at tournaments and parent meetings","bucket":"presenting"},{"id":"form-87-10","text":"Alcohol calms him short-term but stops him learning he can cope","bucket":"perpetuating"},{"id":"form-87-11","text":"Respected for his chess knowledge","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Prakash, 39, presents with social anxiety disorder with harmful alcohol use: intense fear of scrutiny and drinking before public events. Shyness, a critical mother and a drinking father (predisposing) shaped both the fear and the coping; a televised loss with a visible tremor (precipitating) intensified it. Alcohol as a safety behaviour, avoidance of meetings and hangover anxiety (perpetuating) keep it going. His respected expertise and his brother (protective) support CBT for social anxiety with a plan to reduce alcohol, and treatment that does not rely on sedatives.","hint":"A chess coach who drinks before tournaments","tags":{"topic":"anxiety","difficulty":4,"objective":"Show alcohol as a safety behaviour in social anxiety","exams":["md-psychiatry","mcp-entrance"],"module":"anxiety","diagnosis":"Social anxiety disorder with harmful alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-88', 'Fiona: the nurse in Dublin who cannot stop checking doses (OCD at work)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-88-1","text":"Mother with anxiety","bucket":"predisposing"},{"id":"form-88-2","text":"Checks medicine doses five or six times, fearing she will kill a patient","bucket":"presenting"},{"id":"form-88-3","text":"She takes the tram to work","bucket":"distractor"},{"id":"form-88-4","text":"Avoids the high-risk ward","bucket":"perpetuating"},{"id":"form-88-5","text":"Late with medication rounds; colleagues complain","bucket":"presenting"},{"id":"form-88-6","text":"Believes thinking about an error makes it more likely","bucket":"perpetuating"},{"id":"form-88-7","text":"Asks colleagues to re-check for reassurance","bucket":"perpetuating"},{"id":"form-88-8","text":"Perfectionism and an inflated sense of responsibility","bucket":"predisposing"},{"id":"form-88-9","text":"Good insight","bucket":"protective"},{"id":"form-88-10","text":"A colleague made a dosing error that harmed a patient","bucket":"precipitating"},{"id":"form-88-11","text":"Supportive ward manager","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Fiona, 30, presents with obsessive-compulsive disorder: intrusive fears of causing a patient''s death with repeated dose checking that slows her work. Perfectionism, inflated responsibility and maternal anxiety (predisposing) made her vulnerable; a colleague''s harmful error (precipitating) gave the fear its focus. Reassurance seeking, avoidance and thought-action fusion beliefs (perpetuating) maintain it. Good insight and a supportive manager (protective) support exposure and response prevention with a safe, agreed single-check routine at work.","hint":"An Indian-origin nurse whose checking slows her shifts","tags":{"topic":"ocd","difficulty":3,"objective":"Formulate OCD in a high-responsibility job","exams":["mcp-entrance","md-psychiatry"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder, checking type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-89', 'Venkat: the debt and the gun licence (risk formulation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-89-1","text":"Older male living with chronic pain","bucket":"predisposing"},{"id":"form-89-2","text":"Business collapse with loans called in","bucket":"precipitating"},{"id":"form-89-3","text":"Hopelessness, insomnia and statements that his family would be better off with his insurance","bucket":"presenting"},{"id":"form-89-4","text":"Refuses to tell his wife the extent of the debt","bucket":"perpetuating"},{"id":"form-89-5","text":"Father died by suicide","bucket":"predisposing"},{"id":"form-89-6","text":"Religious beliefs against suicide that he still partly holds","bucket":"protective"},{"id":"form-89-7","text":"Drinking more at night","bucket":"perpetuating"},{"id":"form-89-8","text":"Owns a licensed revolver at home","bucket":"perpetuating"},{"id":"form-89-9","text":"Close bond with his grandson","bucket":"protective"},{"id":"form-89-10","text":"Withdrawn and giving away possessions","bucket":"presenting"},{"id":"form-89-11","text":"His company made steel furniture","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Venkat, 61, presents with a severe depressive episode and high suicide risk: hopelessness, insomnia, insurance-related statements and giving away possessions. Being an older man in chronic pain with a father who died by suicide (predisposing) raises baseline risk; business collapse (precipitating) began the crisis. A firearm at home, increasing alcohol and secrecy about the debt (perpetuating) make risk acute. Bonds with his grandson and his faith (protective) matter, but the immediate plan is removing the firearm, urgent treatment with close supervision or admission, and involving his wife.","hint":"A businessman with a licensed revolver and mounting losses","tags":{"topic":"suicide-risk","difficulty":5,"objective":"Build a risk formulation alongside the 5 Ps","exams":["md-psychiatry","mcp-entrance"],"module":"suicide","diagnosis":"Severe depressive episode with high suicide risk"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-90', 'Sister Agnes: the novice who hears God''s punishment (psychotic depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-90-1","text":"Strict, guilt-based upbringing","bucket":"predisposing"},{"id":"form-90-2","text":"Avoids confession because she feels beyond forgiveness","bucket":"perpetuating"},{"id":"form-90-3","text":"Believes she has committed an unforgivable sin and must starve","bucket":"presenting"},{"id":"form-90-4","text":"Not eating worsens her thinking","bucket":"perpetuating"},{"id":"form-90-5","text":"Community reads her fasting as piety","bucket":"perpetuating"},{"id":"form-90-6","text":"Novice mistress who brought her","bucket":"protective"},{"id":"form-90-7","text":"Her mother died while she was in the novitiate and she could not attend the funeral","bucket":"precipitating"},{"id":"form-90-8","text":"The convent has a library of old hymnals","bucket":"distractor"},{"id":"form-90-9","text":"Hears a voice condemning her","bucket":"presenting"},{"id":"form-90-10","text":"Faith that can include accepting care","bucket":"protective"},{"id":"form-90-11","text":"Previous depressive episode at 18","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sister Agnes, 24, presents with a severe depressive episode with mood-congruent psychotic features: a delusion of unforgivable sin, a condemning voice and food refusal. A guilt-based upbringing and a past episode (predisposing) increased risk; her mother''s death and missing the funeral (precipitating) began it. Fasting misread as piety, avoidance of confession and starvation (perpetuating) maintain it. Her novice mistress and a faith that can include accepting care (protective) support urgent medical and psychiatric treatment, involving a spiritual adviser and attention to nutrition.","hint":"A young nun refusing food from guilt","tags":{"topic":"depression","difficulty":5,"objective":"Formulate psychotic depression respectfully in a religious setting","exams":["md-psychiatry"],"module":"depression","diagnosis":"Severe depressive episode with mood-congruent psychotic features"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-91', 'Rohini: the night nurse and the sleeping pills (insomnia with shift work)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-91-1","text":"Tired and irritable on days off","bucket":"presenting"},{"id":"form-91-2","text":"Daytime room is bright and noisy","bucket":"perpetuating"},{"id":"form-91-3","text":"Moved to a rota with three nights in a row","bucket":"precipitating"},{"id":"form-91-4","text":"Drinks coffee to get through shifts","bucket":"perpetuating"},{"id":"form-91-5","text":"Manager willing to adjust her rota","bucket":"protective"},{"id":"form-91-6","text":"Knows the medicine is a problem","bucket":"protective"},{"id":"form-91-7","text":"Rotating shifts for ten years","bucket":"predisposing"},{"id":"form-91-8","text":"Cannot sleep after night shifts without zolpidem for a year","bucket":"presenting"},{"id":"form-91-9","text":"Takes zolpidem nightly, with rebound insomnia when she skips","bucket":"perpetuating"},{"id":"form-91-10","text":"Her hospital is a 500-bed trust hospital","bucket":"distractor"},{"id":"form-91-11","text":"Light sleeper","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rohini, 38, presents with shift work sleep disorder and hypnotic dependence: inability to sleep after night shifts without zolpidem. A light-sleeping tendency and years of rotating shifts (predisposing) set the ground; a rota with consecutive nights (precipitating) worsened it. A bright, noisy day room, nightly hypnotic with rebound insomnia and caffeine (perpetuating) maintain it. A flexible manager and her insight (protective) support blackout curtains, a stable rota, timed light exposure, caffeine limits and a gradual hypnotic taper with CBT for insomnia.","hint":"A nurse who sleeps only with zolpidem","tags":{"topic":"sleep","difficulty":3,"objective":"Formulate circadian and medication factors in insomnia","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Shift work sleep disorder with hypnotic dependence"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-92', 'Aditi: the silence after the assault (PTSD after sexual violence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-92-1","text":"Flashbacks, nightmares and startle for four months","bucket":"presenting"},{"id":"form-92-2","text":"Sexually assaulted by an acquaintance after a party","bucket":"precipitating"},{"id":"form-92-3","text":"Strong family emphasis on ''honour''","bucket":"predisposing"},{"id":"form-92-4","text":"Friend who believes her","bucket":"protective"},{"id":"form-92-5","text":"Childhood bullying left her feeling unsafe","bucket":"predisposing"},{"id":"form-92-6","text":"Wants to finish her degree","bucket":"protective"},{"id":"form-92-7","text":"Has told no one except one friend","bucket":"perpetuating"},{"id":"form-92-8","text":"Avoids college and men on public transport","bucket":"presenting"},{"id":"form-92-9","text":"She studies economics","bucket":"distractor"},{"id":"form-92-10","text":"Avoidance prevents processing","bucket":"perpetuating"},{"id":"form-92-11","text":"Blames herself for going to the party","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aditi, 23, presents with post-traumatic stress disorder after a sexual assault: flashbacks, nightmares, startle and avoidance of college and travel. Childhood bullying and family emphasis on honour (predisposing) shape shame and fear of disclosure; the assault (precipitating) caused the disorder. Self-blame, secrecy and avoidance (perpetuating) keep the trauma unprocessed. A friend who believes her and her academic goals (protective) support a safety assessment, information about her legal options without pressure, and trauma-focused CBT or EMDR.","hint":"A 23-year-old who stopped going to college","tags":{"topic":"trauma","difficulty":4,"objective":"Formulate trauma with shame and safety needs","exams":["md-psychiatry","mcp-entrance"],"module":"trauma","diagnosis":"Post-traumatic stress disorder after sexual assault"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-93', 'Mr Krishnan: the year that did not soften (prolonged grief)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-93-1","text":"Wife who grieves differently but stays close","bucket":"protective"},{"id":"form-93-2","text":"Brother who visits","bucket":"protective"},{"id":"form-93-3","text":"Previous unresolved grief for his own father","bucket":"predisposing"},{"id":"form-93-4","text":"Stopped temple and social life","bucket":"perpetuating"},{"id":"form-93-5","text":"His son studied mechanical engineering","bucket":"distractor"},{"id":"form-93-6","text":"Very close relationship with his only son","bucket":"predisposing"},{"id":"form-93-7","text":"Avoids the accident road and all reminders","bucket":"perpetuating"},{"id":"form-93-8","text":"Believes moving on would betray his son","bucket":"perpetuating"},{"id":"form-93-9","text":"Cannot accept the death; avoids the room and still sets his place","bucket":"presenting"},{"id":"form-93-10","text":"Intense yearning and preoccupation with his son 18 months after his death","bucket":"presenting"},{"id":"form-93-11","text":"Son died suddenly in a road accident","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Krishnan, 58, presents with prolonged grief disorder: 18 months of intense yearning, preoccupation, difficulty accepting the death and loss of meaning after his son''s sudden death. A very close bond and earlier unresolved grief (predisposing) heightened vulnerability; the sudden accident (precipitating) caused the loss. Avoidance, beliefs that recovery would betray his son and withdrawal (perpetuating) keep grief stuck. A close wife and visiting brother (protective) support grief-focused therapy that honours the bond while helping him re-engage with life.","hint":"A man who still sets his son''s place at the table","tags":{"topic":"grief","difficulty":3,"objective":"Formulate prolonged grief disorder","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Prolonged grief disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-94', 'Sameer: the episodic ''ADHD'' (bipolar II misread)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-94-1","text":"Spells began at 21 with a demanding internship","bucket":"precipitating"},{"id":"form-94-2","text":"Supportive friends","bucket":"protective"},{"id":"form-94-3","text":"Curious and open to evidence","bucket":"protective"},{"id":"form-94-4","text":"He uses a standing desk","bucket":"distractor"},{"id":"form-94-5","text":"Irregular sleep from late launches","bucket":"perpetuating"},{"id":"form-94-6","text":"Self-labels as ADHD and seeks stimulants","bucket":"perpetuating"},{"id":"form-94-7","text":"Week-long spells of little sleep, racing ideas and productivity","bucket":"presenting"},{"id":"form-94-8","text":"Cannabis on crash days","bucket":"perpetuating"},{"id":"form-94-9","text":"Mother with depression","bucket":"predisposing"},{"id":"form-94-10","text":"Followed by low crashes","bucket":"presenting"},{"id":"form-94-11","text":"Calm, focused child according to school reports","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sameer, 26, presents with bipolar II disorder: episodic week-long hypomanic spells with reduced need for sleep and productivity, followed by low crashes. A maternal history of depression (predisposing) increases risk, while calm school reports argue against lifelong ADHD; a demanding internship (precipitating) marked onset. A self-label that leads him to seek stimulants, irregular sleep and cannabis use (perpetuating) risk destabilising mood. His openness to evidence and supportive friends (protective) support mood charting, sleep regularity, avoiding stimulants and mood-stabilising treatment.","hint":"A product manager asking for stimulants","tags":{"topic":"bipolar","difficulty":4,"objective":"Use the time course in the formulation to correct a self-label","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Bipolar II disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-95', 'Anjali: ''I''ll never be a good mother'' (perinatal anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-95-1","text":"Checks the baby''s breathing many times a night","bucket":"presenting"},{"id":"form-95-2","text":"Husband shares night duty","bucket":"protective"},{"id":"form-95-3","text":"Her own mother was critical","bucket":"predisposing"},{"id":"form-95-4","text":"Searches baby health forums at night","bucket":"perpetuating"},{"id":"form-95-5","text":"The baby''s cradle was a family heirloom","bucket":"distractor"},{"id":"form-95-6","text":"Paediatrician who reassures well","bucket":"protective"},{"id":"form-95-7","text":"Mother-in-law criticises her feeding","bucket":"perpetuating"},{"id":"form-95-8","text":"Baby had jaundice and was admitted for two days","bucket":"precipitating"},{"id":"form-95-9","text":"Little sleep from night checking","bucket":"perpetuating"},{"id":"form-95-10","text":"Constant worry about the baby''s health and her own competence for two months","bucket":"presenting"},{"id":"form-95-11","text":"Anxious temperament since school","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anjali, 27, presents with generalised anxiety after her baby''s birth: persistent worry about the baby''s health and her competence, with frequent night checks. An anxious temperament and a critical mother (predisposing) shaped self-doubt; the baby''s admission for jaundice (precipitating) began it. Night forum searching, criticism from her mother-in-law and sleep loss (perpetuating) keep it going. A husband who shares nights and a reassuring paediatrician (protective) support CBT for worry, protected sleep and limits on checking and searching.","hint":"A first-time mother checking the baby''s breathing all night","tags":{"topic":"perinatal","difficulty":2,"objective":"Sort perinatal anxiety into the 5 Ps","exams":["mcp-entrance","ma-semester"],"module":"anxiety","diagnosis":"Generalised anxiety in the postnatal period"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-96', 'Mr Ali: the worms only he can see (delusional infestation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-96-1","text":"Fixed belief that worms live under his skin, with scratching and sores","bucket":"presenting"},{"id":"form-96-2","text":"Son who brought him","bucket":"protective"},{"id":"form-96-3","text":"Night-time checking of his skin","bucket":"perpetuating"},{"id":"form-96-4","text":"Belief began after his wife''s death","bucket":"precipitating"},{"id":"form-96-5","text":"Brings skin and lint in a matchbox as proof","bucket":"presenting"},{"id":"form-96-6","text":"Lives alone and is socially isolated","bucket":"predisposing"},{"id":"form-96-7","text":"Diabetes with dry, itchy skin","bucket":"predisposing"},{"id":"form-96-8","text":"Engages if not argued with","bucket":"protective"},{"id":"form-96-9","text":"Dermatologists dismiss him and he moves to the next","bucket":"perpetuating"},{"id":"form-96-10","text":"He drove a government jeep","bucket":"distractor"},{"id":"form-96-11","text":"Uses kerosene and harsh soaps, worsening the skin","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Ali, 63, presents with delusional disorder, somatic type: a fixed belief in skin infestation with scratching, sores and ''specimens''. Diabetic skin dryness and itch and social isolation (predisposing) provide the sensations and the lack of correction; his wife''s death (precipitating) preceded onset. Harsh home treatments, being dismissed by doctors and night checking (perpetuating) maintain it. A son who brought him and his willingness to engage without argument (protective) support joint care with dermatology, treating the skin and itch, screening for medical causes and a low-dose antipsychotic.","hint":"A widower bringing ''specimens'' in a matchbox","tags":{"topic":"psychosis","difficulty":4,"objective":"Include medical contributors in a somatic delusion formulation","exams":["md-psychiatry"],"module":"psychosis","diagnosis":"Delusional disorder, somatic type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-97', 'Komal: the lithium and the kidneys (long-term treatment review)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-97-1","text":"Kidney blood test result came back lower than before","bucket":"precipitating"},{"id":"form-97-2","text":"Last lithium level and thyroid test were long ago","bucket":"perpetuating"},{"id":"form-97-3","text":"Ten years on lithium","bucket":"predisposing"},{"id":"form-97-4","text":"Two past manic episodes","bucket":"predisposing"},{"id":"form-97-5","text":"Drinks lots of water, which she thinks is the problem","bucket":"perpetuating"},{"id":"form-97-6","text":"Good relationship with her psychiatrist","bucket":"protective"},{"id":"form-97-7","text":"Thirst, passing large amounts of urine and mildly reduced kidney function","bucket":"presenting"},{"id":"form-97-8","text":"She prefers working from the office","bucket":"distractor"},{"id":"form-97-9","text":"Mood stable for ten years","bucket":"presenting"},{"id":"form-97-10","text":"Excellent adherence and insight","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Komal, 28, presents with lithium-related effects after ten years of stable bipolar I disorder: polyuria, thirst and mildly reduced kidney function. Long-term lithium (predisposing) is the cause of the kidney effects, and her two past manic episodes explain why stopping is risky; the new kidney result (precipitating) brought her in. Lapsed monitoring and misunderstanding the thirst (perpetuating) need correcting. Her adherence, insight and relationship with her psychiatrist (protective) support a shared review of lithium levels, kidney, thyroid and calcium tests and a weighed decision about continuing or switching.","hint":"A stable accountant with rising thirst","tags":{"topic":"bipolar","difficulty":2,"objective":"Use a formulation to plan long-term monitoring","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"stabilisers","diagnosis":"Bipolar I disorder in remission with lithium-related kidney effects"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-98', 'Mehul: the back that ended his factory job (chronic pain with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-98-1","text":"Escalating over-the-counter painkillers that give little relief","bucket":"perpetuating"},{"id":"form-98-2","text":"Rest and avoidance weaken his back and lower his mood","bucket":"perpetuating"},{"id":"form-98-3","text":"Lifting injury at the factory and loss of his job","bucket":"precipitating"},{"id":"form-98-4","text":"His factory made plastic buckets","bucket":"distractor"},{"id":"form-98-5","text":"Daily low back pain for two years after a lifting injury, with low mood and poor sleep","bucket":"presenting"},{"id":"form-98-6","text":"Spends most of the day lying down","bucket":"presenting"},{"id":"form-98-7","text":"Manual job with no other skills or savings","bucket":"predisposing"},{"id":"form-98-8","text":"Interest in teaching his son to repair radios","bucket":"protective"},{"id":"form-98-9","text":"Wife who wants him active again","bucket":"protective"},{"id":"form-98-10","text":"Belief that hurt always means harm","bucket":"predisposing"},{"id":"form-98-11","text":"Compensation dispute keeps attention on the injury","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mehul, 44, presents with chronic low back pain and a moderate depressive episode: two years of daily pain, low mood, poor sleep and inactivity. A manual job with no fallback and a belief that pain always signals damage (predisposing) shaped fear and loss; the lifting injury and job loss (precipitating) began the cycle. Rest and avoidance, rising painkillers and a drawn-out compensation dispute (perpetuating) keep pain and mood linked. A supportive wife and his radio-repair skill (protective) support a pain-management approach with graded activity, review of painkillers, antidepressant treatment that also helps pain and a plan for meaningful work.","hint":"A machine operator on daily painkillers who has stopped going out","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate the pain, mood and activity cycle","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Chronic low back pain with a moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-99', 'Chhotu: the whitener and the platform (child inhalant use)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-99-1","text":"Bright and resourceful","bucket":"protective"},{"id":"form-99-2","text":"Ran away at ten","bucket":"predisposing"},{"id":"form-99-3","text":"Headaches, memory problems and falls","bucket":"presenting"},{"id":"form-99-4","text":"No safe shelter at night","bucket":"perpetuating"},{"id":"form-99-5","text":"Sniffing takes away hunger and cold","bucket":"perpetuating"},{"id":"form-99-6","text":"Violent stepfather at home in Bihar","bucket":"predisposing"},{"id":"form-99-7","text":"Trusts an NGO outreach worker","bucket":"protective"},{"id":"form-99-8","text":"Sniffs correction fluid daily","bucket":"presenting"},{"id":"form-99-9","text":"Joined older boys at the station who sniff","bucket":"precipitating"},{"id":"form-99-10","text":"He collects plastic bottles to sell","bucket":"distractor"},{"id":"form-99-11","text":"Older boys exploit him","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Chhotu, 13, presents with inhalant use disorder with neurotoxic effects and urgent safeguarding needs. A violent stepfather and running away at ten (predisposing) left him unprotected; joining older boys who sniff (precipitating) began use. Relief from hunger and cold, exploitation by older boys and no safe shelter (perpetuating) maintain it. Trust in an NGO worker and his resourcefulness (protective) support child welfare referral, shelter, medical review and a gradual, trust-based plan to stop.","hint":"A 13-year-old runaway at a railway station","tags":{"topic":"substance","difficulty":4,"objective":"Formulate substance use in a child with safeguarding needs","exams":["mcp-entrance","ma-semester"],"module":"child","diagnosis":"Inhalant use disorder in a street-connected child"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-100', 'Dr Banerjee: the theatre lights are watching (stimulant-linked psychosis in a doctor)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-100-1","text":"Months of 100-hour weeks with modafinil to stay awake","bucket":"precipitating"},{"id":"form-100-2","text":"A friend who supports him","bucket":"protective"},{"id":"form-100-3","text":"Perfectionistic and competitive","bucket":"predisposing"},{"id":"form-100-4","text":"Strong motivation to keep practising","bucket":"protective"},{"id":"form-100-5","text":"Fear of career damage stops him accepting help","bucket":"perpetuating"},{"id":"form-100-6","text":"Cousin with schizophrenia","bucket":"predisposing"},{"id":"form-100-7","text":"Believes the head of department watches him through theatre lights","bucket":"presenting"},{"id":"form-100-8","text":"He trained in general surgery","bucket":"distractor"},{"id":"form-100-9","text":"Ongoing sleep deprivation and stimulant use","bucket":"perpetuating"},{"id":"form-100-10","text":"Department conflict feeds suspicion","bucket":"perpetuating"},{"id":"form-100-11","text":"Wrote about being watched in a patient''s chart","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dr Banerjee, 34, presents with a psychotic episode with persecutory beliefs about his department, linked to stimulant use and severe sleep deprivation, with a family history that keeps a primary psychosis in view. Perfectionism and a family history (predisposing) increased vulnerability; months of extreme hours on modafinil (precipitating) preceded onset. Ongoing sleep loss and stimulants, fear for his career and workplace conflict (perpetuating) maintain it. A supportive friend and his wish to practise (protective) support stopping stimulants, restoring sleep, treatment and a confidential occupational health route that protects patients and him.","hint":"A surgical resident on modafinil and three hours of sleep","tags":{"topic":"psychosis","difficulty":5,"objective":"Formulate psychosis with occupational and safety dimensions","exams":["md-psychiatry"],"module":"psychosis","diagnosis":"Psychotic episode linked to stimulant use and sleep deprivation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-101', 'Mrs Gupta: the daughter-in-law and the empty kitchen (late-life depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-101-1","text":"No interest in grandchildren","bucket":"presenting"},{"id":"form-101-2","text":"Long friendship with a neighbour","bucket":"protective"},{"id":"form-101-3","text":"Identity built around running the family kitchen","bucket":"predisposing"},{"id":"form-101-4","text":"Grandchildren who love her","bucket":"protective"},{"id":"form-101-5","text":"Osteoarthritis","bucket":"predisposing"},{"id":"form-101-6","text":"Son''s marriage; the daughter-in-law took over the kitchen","bucket":"precipitating"},{"id":"form-101-7","text":"Feels she has no role","bucket":"perpetuating"},{"id":"form-101-8","text":"Painkillers treat the pain but no one asks about mood","bucket":"perpetuating"},{"id":"form-101-9","text":"Stopped going to her bhajan group","bucket":"perpetuating"},{"id":"form-101-10","text":"The house has a terrace","bucket":"distractor"},{"id":"form-101-11","text":"Knee and back pain with low mood, poor sleep and tearfulness for a year","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Gupta, 63, presents with a moderate depressive episode expressed through body pain: a year of pain, low mood, poor sleep, tearfulness and loss of interest. Osteoarthritis and an identity centred on running the kitchen (predisposing) made role change painful; the daughter-in-law taking over (precipitating) began it. Withdrawal from her bhajan group, pain-only treatment and loss of role (perpetuating) keep it going. Grandchildren and a long friendship (protective) support treating mood and pain together and rebuilding a valued role in the family.","hint":"A 63-year-old who says her knees hurt","tags":{"topic":"depression","difficulty":1,"objective":"Sort a somatic late-life depression into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode with somatic presentation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-102', 'Tushar: three rehabs and the 7 pm craving (relapse formulation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-102-1","text":"Social anxiety eased by alcohol since college","bucket":"predisposing"},{"id":"form-102-2","text":"Insight and articulate","bucket":"protective"},{"id":"form-102-3","text":"Relapsed to drinking within a month of three residential rehabs","bucket":"presenting"},{"id":"form-102-4","text":"Belief that he is ''weak'' leads to giving up after a slip","bucket":"perpetuating"},{"id":"form-102-5","text":"Office party two weeks after discharge","bucket":"precipitating"},{"id":"form-102-6","text":"Evenings alone with nothing planned","bucket":"perpetuating"},{"id":"form-102-7","text":"No aftercare or anti-craving medicine","bucket":"perpetuating"},{"id":"form-102-8","text":"Parents still engaged","bucket":"protective"},{"id":"form-102-9","text":"Evening craving at 7 pm","bucket":"presenting"},{"id":"form-102-10","text":"He works on a banking app","bucket":"distractor"},{"id":"form-102-11","text":"Uncle with alcohol dependence","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Tushar, 33, presents with alcohol dependence with repeated early relapse after rehab. Social anxiety eased by drinking and a family history (predisposing) raise his risk; an office party soon after discharge (precipitating) triggered the latest relapse. No aftercare or anti-craving medicine, empty evenings and an abstinence-violation belief that one slip means failure (perpetuating) drive relapse. His insight and engaged parents (protective) support a relapse-prevention plan with medicine, evening structure, mutual-help groups and treatment of social anxiety.","hint":"A tester who relapses each time after discharge","tags":{"topic":"substance","difficulty":3,"objective":"Formulate relapse with triggers and missing aftercare","exams":["mcp-entrance","md-psychiatry"],"module":"substance","diagnosis":"Alcohol dependence with early relapse"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-103', 'Pushpa: the stroke and the sling (post-stroke depression, carer view)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-103-1","text":"Her school was a girls'' school","bucket":"distractor"},{"id":"form-103-2","text":"Proud, independent former principal","bucket":"predisposing"},{"id":"form-103-3","text":"Former students who visit","bucket":"protective"},{"id":"form-103-4","text":"Feels humiliated being bathed by her daughter-in-law","bucket":"perpetuating"},{"id":"form-103-5","text":"Caring family","bucket":"protective"},{"id":"form-103-6","text":"Missed physiotherapy slows recovery","bucket":"perpetuating"},{"id":"form-103-7","text":"Left-sided stroke with right arm weakness and mild speech difficulty","bucket":"precipitating"},{"id":"form-103-8","text":"Sustained low mood and hopelessness three months after a stroke","bucket":"presenting"},{"id":"form-103-9","text":"Refuses physiotherapy on many days","bucket":"presenting"},{"id":"form-103-10","text":"Avoids calls from former colleagues because of her speech","bucket":"perpetuating"},{"id":"form-103-11","text":"Atrial fibrillation and high blood pressure","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pushpa, 71, presents with post-stroke depression: sustained low mood and hopelessness that are reducing her engagement with rehabilitation. Vascular risk factors and a proud, independent identity (predisposing) shape both the stroke and her reaction; the stroke (precipitating) began the episode through brain injury and loss. Humiliation in personal care, avoidance of former colleagues and missed physiotherapy (perpetuating) maintain it. A caring family and visiting former students (protective) support antidepressant treatment, dignity-preserving care routines and rehab goals she chooses.","hint":"A retired principal who refuses physiotherapy","tags":{"topic":"depression","difficulty":2,"objective":"Show dignity and role loss in a medical-psychiatric formulation","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Post-stroke depression"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-104', 'Rhea: the weather report friends (cyclothymia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-104-1","text":"Alternating spells of a few days of high energy and a few days of low mood for eight years","bucket":"presenting"},{"id":"form-104-2","text":"No single trigger; worsened with freelance work and irregular hours","bucket":"precipitating"},{"id":"form-104-3","text":"Father with bipolar I disorder","bucket":"predisposing"},{"id":"form-104-4","text":"Fear of becoming like her father stops her seeking help","bucket":"perpetuating"},{"id":"form-104-5","text":"Over-commits in highs, causing stress in lows","bucket":"perpetuating"},{"id":"form-104-6","text":"Good insight and humour","bucket":"protective"},{"id":"form-104-7","text":"Onset at 16","bucket":"predisposing"},{"id":"form-104-8","text":"Irregular sleep from late projects","bucket":"perpetuating"},{"id":"form-104-9","text":"She designs book covers","bucket":"distractor"},{"id":"form-104-10","text":"Stable friendships","bucket":"protective"},{"id":"form-104-11","text":"Missed deadlines in lows, over-commits in highs","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rhea, 24, presents with cyclothymic disorder: eight years of frequent, short highs and lows that never reach full episode criteria. A father with bipolar I disorder and adolescent onset (predisposing) suggest genetic risk; irregular freelance hours (precipitating) worsened it. Irregular sleep, over-commitment in highs and fear-driven avoidance of help (perpetuating) maintain it. Insight, humour and stable friendships (protective) support mood charting, sleep and routine regularity, and monitoring for progression.","hint":"A designer whose moods shift every few days","tags":{"topic":"bipolar","difficulty":3,"objective":"Formulate a chronic, subthreshold mood pattern","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Cyclothymic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-105', 'Mr Agarwal: the attacks that start in the body (pheochromocytoma missed as panic)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-105-1","text":"Episodes of pounding headache, sweating and palpitations with very high blood pressure","bucket":"presenting"},{"id":"form-105-2","text":"Weight loss and blood pressure resistant to two drugs","bucket":"presenting"},{"id":"form-105-3","text":"Attacks began six months ago, some after bending or straining","bucket":"precipitating"},{"id":"form-105-4","text":"Labelled panic disorder and given an SSRI with no effect","bucket":"perpetuating"},{"id":"form-105-5","text":"No anxious temperament before","bucket":"predisposing"},{"id":"form-105-6","text":"Doctors attribute each episode to stress","bucket":"perpetuating"},{"id":"form-105-7","text":"No psychiatric history","bucket":"predisposing"},{"id":"form-105-8","text":"Keeps a detailed blood pressure log","bucket":"protective"},{"id":"form-105-9","text":"Persistent in seeking answers","bucket":"protective"},{"id":"form-105-10","text":"He files taxes for small businesses","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Agarwal, 51, presents with episodic adrenergic attacks with severe hypertension that point to a possible pheochromocytoma, not panic disorder. The absence of an anxious temperament or psychiatric history (predisposing factors that are notably missing) is a clue; attacks starting with physical symptoms and triggered by straining (precipitating) fit a medical cause. An early panic label with an ineffective SSRI and stress explanations (perpetuating) delayed diagnosis. His detailed log and persistence (protective) support urgent endocrine investigation; a formulation that cannot fill the psychological boxes is itself a warning.","hint":"An accountant with blood pressure of 220 during attacks","tags":{"topic":"anxiety","difficulty":5,"objective":"Show how a formulation can expose a missed medical cause","exams":["md-psychiatry"],"module":"anxiety","diagnosis":"Episodic attacks due to suspected pheochromocytoma"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-106', 'Mohit: the bhang laddoos at Holi (acute intoxication)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-106-1","text":"No prior cannabis experience","bucket":"predisposing"},{"id":"form-106-2","text":"Friends who brought him for help","bucket":"protective"},{"id":"form-106-3","text":"Racing heart, terror and a feeling that time has stopped two hours after edibles","bucket":"presenting"},{"id":"form-106-4","text":"Ate two bhang laddoos at Holi because the first ''did not work''","bucket":"precipitating"},{"id":"form-106-5","text":"Friends joking about it raises his fear","bucket":"perpetuating"},{"id":"form-106-6","text":"Anxious when unwell","bucket":"predisposing"},{"id":"form-106-7","text":"Healthy young man","bucket":"protective"},{"id":"form-106-8","text":"Checks his pulse repeatedly","bucket":"perpetuating"},{"id":"form-106-9","text":"Mixed some alcohol","bucket":"perpetuating"},{"id":"form-106-10","text":"Believes he is dying","bucket":"presenting"},{"id":"form-106-11","text":"He wore a white kurta for Holi","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mohit, 21, presents with acute cannabis intoxication with panic after eating edibles at Holi. Inexperience and anxiety when unwell (predisposing) made a strong reaction likely; a second laddoo before the first took effect (precipitating) caused a high dose. Friends'' joking, added alcohol and pulse checking (perpetuating) feed the fear. Caring friends and good health (protective) support calm reassurance, observation of vital signs and advice about delayed effects of edibles.","hint":"A student terrified that time has stopped","tags":{"topic":"substance","difficulty":1,"objective":"Sort a brief, self-limiting crisis into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"substance","diagnosis":"Acute cannabis intoxication with panic"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-107', 'Deepa: the transfer to Pune (mild depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-107-1","text":"Transferred from Nagpur to Pune on promotion two months ago","bucket":"precipitating"},{"id":"form-107-2","text":"Shy, takes a long time to make new friends","bucket":"predisposing"},{"id":"form-107-3","text":"Likes her work and is good at it","bucket":"protective"},{"id":"form-107-4","text":"Stays in her paying guest room every weekend","bucket":"perpetuating"},{"id":"form-107-5","text":"Sad most days, tearful in the evenings and less interested in films she used to love, for three weeks","bucket":"presenting"},{"id":"form-107-6","text":"Tells her family on the phone that all is well","bucket":"perpetuating"},{"id":"form-107-7","text":"A friendly senior colleague who invites her for lunch","bucket":"protective"},{"id":"form-107-8","text":"Still goes to work but feels flat and tired","bucket":"presenting"},{"id":"form-107-9","text":"Has always leaned on her sisters for support","bucket":"predisposing"},{"id":"form-107-10","text":"The new branch has a bigger parking area","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Deepa, 27, presents with a mild depressive episode: three weeks of low mood, evening tearfulness, reduced interest and tiredness while still working. A shy temperament and a strong reliance on her sisters (predisposing) made a move away from home hard; the transfer to Pune (precipitating) cut her off from her usual support. Staying alone in her room at weekends and hiding her feelings from family (perpetuating) keep her isolated, so the mood has no chance to lift. A warm colleague and a job she enjoys (protective) are the base for activity scheduling and rebuilding social contact. The parking area has nothing to do with her mood, so it stays out of the grid.","hint":"A bank cashier who moved cities for a promotion","tags":{"topic":"depression","difficulty":1,"objective":"Sort a mild depressive episode after a life change into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Mild depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-108', 'Harpreet: the husband in Canada (depression in a left-behind wife)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-108-1","text":"Feels she has no one to talk to","bucket":"presenting"},{"id":"form-108-2","text":"Low mood, poor sleep and loss of appetite for five weeks","bucket":"presenting"},{"id":"form-108-3","text":"A low spell after her first child was born","bucket":"predisposing"},{"id":"form-108-4","text":"Mother-in-law criticises her housework and limits her visits to her parents","bucket":"perpetuating"},{"id":"form-108-5","text":"Her own sister lives in the same city","bucket":"protective"},{"id":"form-108-6","text":"Close to her six-year-old son","bucket":"protective"},{"id":"form-108-7","text":"Husband left for Canada on a work permit two months ago and calls less often","bucket":"precipitating"},{"id":"form-108-8","text":"Married young and moved into her in-laws'' home far from her parents","bucket":"predisposing"},{"id":"form-108-9","text":"The family owns a dairy with eight buffaloes","bucket":"distractor"},{"id":"form-108-10","text":"Stays awake late waiting for his calls","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Harpreet, 26, presents with a moderate depressive episode: five weeks of low mood, poor sleep, reduced appetite and loneliness. Early marriage into a home far from her own family and a past low spell after childbirth (predisposing) left her vulnerable; her husband''s departure abroad (precipitating) removed her main confidant. Daily criticism, limited contact with her parents and late nights waiting for calls (perpetuating) keep her mood and sleep poor. Her bond with her son and a sister nearby (protective) can be used to rebuild support and routine. The dairy is part of family life but does not explain her depression, so it is a distractor.","hint":"A young mother in a Ludhiana joint family","tags":{"topic":"depression","difficulty":1,"objective":"Recognise migration of a spouse as a social stressor in depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-109', 'Manoj: the layoff email and the evening bottle (depression with alcohol)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-109-1","text":"Drinks four to five pegs every night to ''switch off''","bucket":"presenting"},{"id":"form-109-2","text":"Wife who knows and wants to help","bucket":"protective"},{"id":"form-109-3","text":"Alcohol worsens his sleep and his morning mood","bucket":"perpetuating"},{"id":"form-109-4","text":"Father drank heavily","bucket":"predisposing"},{"id":"form-109-5","text":"Applies for jobs only late at night after drinking","bucket":"perpetuating"},{"id":"form-109-6","text":"Strong technical skills and a good work record","bucket":"protective"},{"id":"form-109-7","text":"Low mood, guilt and poor concentration for six weeks","bucket":"presenting"},{"id":"form-109-8","text":"Has not told his parents and pretends to leave for work each day","bucket":"perpetuating"},{"id":"form-109-9","text":"Believes a man must always provide for his family","bucket":"predisposing"},{"id":"form-109-10","text":"He switched his phone to a new network last month","bucket":"distractor"},{"id":"form-109-11","text":"Laid off by email with forty other staff after a company cutback","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Manoj, 34, presents with a moderate depressive episode with harmful alcohol use: six weeks of low mood, guilt and poor concentration, with nightly drinking. A father who drank and a belief that his worth rests on providing (predisposing) shaped both the drinking pattern and the shame; the layoff (precipitating) hit that belief directly. Alcohol is a depressant that breaks sleep and lowers next-day mood, and the secrecy of pretending to go to work and job hunting while drunk (perpetuating) keep the cycle running. A supportive wife and solid skills (protective) give a route back. The plan should treat the drinking alongside the depression, not after it. The phone network change is a distractor.","hint":"A software tester let go in a round of layoffs","tags":{"topic":"depression","difficulty":2,"objective":"Show how alcohol can act as a perpetuating factor in depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode with harmful alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-110', 'Chidinma: far from Lagos in Manipal (depression in an international student)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-110-1","text":"Strangers in the market made racist comments and filmed her on a phone","bucket":"precipitating"},{"id":"form-110-2","text":"Feels she cannot tell her family because they sacrificed so much","bucket":"perpetuating"},{"id":"form-110-3","text":"Eldest daughter carrying her family''s hopes and fees","bucket":"predisposing"},{"id":"form-110-4","text":"Avoids leaving the campus so she has no contact outside class","bucket":"perpetuating"},{"id":"form-110-5","text":"Skips classes and eats alone in her room","bucket":"presenting"},{"id":"form-110-6","text":"Falling marks add to her sense of failure","bucket":"perpetuating"},{"id":"form-110-7","text":"Her hostel room faces the sea","bucket":"distractor"},{"id":"form-110-8","text":"A batchmate from Kerala who checks on her","bucket":"protective"},{"id":"form-110-9","text":"Low mood, crying and poor sleep for two months","bucket":"presenting"},{"id":"form-110-10","text":"A church group of other African students in the town","bucket":"protective"},{"id":"form-110-11","text":"Earlier low spell when her grandmother died","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Chidinma, 22, presents with a moderate depressive episode: two months of low mood, crying, poor sleep and withdrawal. The pressure of being the family''s hope and an earlier low spell after a bereavement (predisposing) raised her vulnerability; a racist incident in the market (precipitating) left her feeling unsafe and unwelcome. Avoidance of the town, secrecy towards her family and falling marks (perpetuating) feed a cycle of isolation and failure. Her church community and a caring batchmate (protective) are strong supports, and the college can act on the harassment. A sea view sounds pleasant but does not shape her mood, so it is a distractor.","hint":"A Nigerian medical student who has stopped going to the hostel mess","tags":{"topic":"depression","difficulty":3,"objective":"Include discrimination and acculturation stress in a formulation","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-111', 'Mrs Saraswati: ''I don''t know'' to every question (depression with memory complaints)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-111-1","text":"Daughter-in-law calls her every evening on video","bucket":"protective"},{"id":"form-111-2","text":"Low mood, poor appetite and early waking for two months","bucket":"presenting"},{"id":"form-111-3","text":"Two earlier depressive episodes in her fifties","bucket":"predisposing"},{"id":"form-111-4","text":"Good recovery from both earlier episodes","bucket":"protective"},{"id":"form-111-5","text":"She believes she is ''going senile'', which deepens her hopelessness","bucket":"perpetuating"},{"id":"form-111-6","text":"Mixes up her grandchildren''s names, as she has done all her life","bucket":"distractor"},{"id":"form-111-7","text":"Her blood pressure is well controlled","bucket":"distractor"},{"id":"form-111-8","text":"No gradual memory decline before this year","bucket":"predisposing"},{"id":"form-111-9","text":"Complains loudly of poor memory and answers ''I don''t know'' without trying","bucket":"presenting"},{"id":"form-111-10","text":"Family now handle everything, so she has no daily tasks","bucket":"perpetuating"},{"id":"form-111-11","text":"Her only son moved to Singapore with his family three months ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Saraswati, 72, presents with a depressive episode with cognitive complaints that mimic dementia: low mood, early waking, poor appetite and a fast onset of memory problems that she highlights and does not try to hide. Past depressive episodes and no earlier decline (predisposing) point towards mood; her son''s emigration (precipitating) came just before onset. Loss of daily tasks and the belief that she is going senile (perpetuating) keep the depression going. Good past recovery and daily video calls (protective) make improvement likely with treatment, and cognition should be retested once mood lifts. The card about mixing up her grandchildren''s names is tempting, but it is a lifelong habit and not a change, so it says nothing about a new illness. Controlled blood pressure is also not relevant here.","hint":"A 72-year-old whose family fear dementia","tags":{"topic":"depression","difficulty":4,"objective":"Tell depression with cognitive complaints apart from dementia","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"neurocognitive","diagnosis":"Depressive episode with cognitive impairment (depressive pseudodementia)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-112', 'Vikram: three tablets and still stuck (treatment-resistant depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-112-1","text":"Three antidepressants tried with little benefit","bucket":"presenting"},{"id":"form-112-2","text":"Willing to try therapy if his wife comes too","bucket":"protective"},{"id":"form-112-3","text":"Loud snoring and daytime sleepiness never assessed for sleep apnoea","bucket":"perpetuating"},{"id":"form-112-4","text":"Wife says they have stopped speaking except about money","bucket":"perpetuating"},{"id":"form-112-5","text":"Grew up with a father who only praised results","bucket":"predisposing"},{"id":"form-112-6","text":"The school bus fleet is being changed to electric","bucket":"distractor"},{"id":"form-112-7","text":"Takes tablets only on days he ''feels bad'', so doses were never adequate","bucket":"perpetuating"},{"id":"form-112-8","text":"Severe low mood, guilt and slowed thinking for ten months","bucket":"presenting"},{"id":"form-112-9","text":"He was born in a leap year","bucket":"distractor"},{"id":"form-112-10","text":"Spends hours each night going over the inspection in his head","bucket":"perpetuating"},{"id":"form-112-11","text":"Mother had recurrent depression","bucket":"predisposing"},{"id":"form-112-12","text":"His school failed a government inspection and lost its affiliation for a year","bucket":"precipitating"},{"id":"form-112-13","text":"Stable finances and a loyal staff","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vikram, 48, presents with a severe recurrent depressive episode labelled treatment resistant after three antidepressants. A family history of depression and a childhood where worth meant results (predisposing) form the base; the school losing its affiliation (precipitating) struck at his identity. Before calling this true resistance, the formulation shows why treatment may have failed (perpetuating): doses taken only on bad days, likely untreated sleep apnoea, a cold marriage and nightly rumination. In CBT terms the rumination and withdrawal maintain the low mood; from a psychodynamic angle the failed inspection repeats an old fear of being worthless without success. His finances, staff and openness to couple work (protective) help. Next steps are an adherence check, a sleep study, couple sessions and rumination-focused work, with ECT kept as a real option if the episode stays severe. The bus fleet and leap year cards are distractors.","hint":"A 48-year-old school owner referred for ECT","tags":{"topic":"depression","difficulty":5,"objective":"Build a full formulation that finds hidden reasons for poor response","exams":["md-psychiatry","mcp-entrance"],"module":"antidepressants","diagnosis":"Recurrent depressive disorder, current episode severe, with poor response to treatment"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-113', 'Raghav: the garba nights and the new business plans (first manic episode)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-113-1","text":"Maternal aunt treated with lithium for many years","bucket":"predisposing"},{"id":"form-113-2","text":"Denies anything is wrong and refuses to see a doctor","bucket":"perpetuating"},{"id":"form-113-3","text":"Parents who brought him in early","bucket":"protective"},{"id":"form-113-4","text":"Friends cheer his plans on social media","bucket":"perpetuating"},{"id":"form-113-5","text":"Talks fast, sleeps two hours, and has booked a hall to launch three companies","bucket":"presenting"},{"id":"form-113-6","text":"He wore a different coloured kurta each night","bucket":"distractor"},{"id":"form-113-7","text":"No substance use besides caffeine","bucket":"protective"},{"id":"form-113-8","text":"Spent his father''s savings on a car in one afternoon","bucket":"presenting"},{"id":"form-113-9","text":"Nine nights of garba with very little sleep during Navratri","bucket":"precipitating"},{"id":"form-113-10","text":"One depressive episode at 19","bucket":"predisposing"},{"id":"form-113-11","text":"Drinks energy drinks to keep going","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Raghav, 24, presents with a first manic episode: very reduced need for sleep, pressured speech, grand business plans and reckless spending. A family history of bipolar disorder and an earlier depressive episode (predisposing) suggest he was at risk; nine nights of minimal sleep during Navratri (precipitating) set off the episode, as sleep loss is a well known trigger for mania. Lack of insight, energy drinks and online encouragement (perpetuating) keep him high. Parents who acted early and the absence of drug use (protective) improve the outlook. Treatment needs a mood stabiliser or antipsychotic, sleep protection and protecting the family''s money. The kurta colours are a distractor.","hint":"A 24-year-old who slept two hours a night through Navratri","tags":{"topic":"bipolar","difficulty":2,"objective":"Link sleep loss to the onset of mania","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"bipolar","diagnosis":"Bipolar I disorder, current episode manic"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-114', 'Nazia: the positive test and the stopped tablets (bipolar disorder in pregnancy)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-114-1","text":"Husband who called the clinic","bucket":"protective"},{"id":"form-114-2","text":"She craves sour raw mango","bucket":"distractor"},{"id":"form-114-3","text":"Fears any medicine will damage the baby so refuses review","bucket":"perpetuating"},{"id":"form-114-4","text":"Husband''s family say it is just pregnancy excitement","bucket":"perpetuating"},{"id":"form-114-5","text":"Sleeping four hours, talking more and irritable for ten days","bucket":"presenting"},{"id":"form-114-6","text":"Two manic episodes in the past five years","bucket":"predisposing"},{"id":"form-114-7","text":"A good relationship with her psychiatrist","bucket":"protective"},{"id":"form-114-8","text":"Stopped lithium suddenly after reading online that it harms babies","bucket":"precipitating"},{"id":"form-114-9","text":"Eight weeks pregnant with her first child","bucket":"presenting"},{"id":"form-114-10","text":"Late nights preparing the nursery","bucket":"perpetuating"},{"id":"form-114-11","text":"Stable for three years on lithium","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Nazia, 30, presents with early hypomanic relapse of bipolar I disorder at eight weeks of pregnancy: reduced sleep, talkativeness and irritability. Past manic episodes (predisposing) mean her relapse risk is high; stopping lithium suddenly (precipitating) is one of the strongest triggers for relapse. Fear of all medicine, shrinking sleep and the family''s normalising (perpetuating) delay help. Her husband''s call and a trusted psychiatrist (protective) allow a calm, shared decision weighing the small risks of medicine against the serious risks of untreated mania in pregnancy and after birth. Food cravings are common in pregnancy and do not belong in her formulation.","hint":"A woman with bipolar I who stopped lithium the day she found out","tags":{"topic":"bipolar","difficulty":3,"objective":"Formulate relapse risk when medicine is stopped suddenly in pregnancy","exams":["md-psychiatry","mcp-entrance"],"module":"stabilisers","diagnosis":"Bipolar I disorder with early hypomanic relapse in pregnancy"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-115', 'Kabir: the drop year in Kota (adolescent depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-115-1","text":"Watches his rank fall on the weekly board","bucket":"perpetuating"},{"id":"form-115-2","text":"His room has a ceiling fan with a broken regulator","bucket":"distractor"},{"id":"form-115-3","text":"Lives alone with no friends in the city","bucket":"perpetuating"},{"id":"form-115-4","text":"Close to his grandfather, who calls daily","bucket":"protective"},{"id":"form-115-5","text":"Parents took a loan for his coaching fees","bucket":"predisposing"},{"id":"form-115-6","text":"Mentor at the coaching centre who noticed the change","bucket":"protective"},{"id":"form-115-7","text":"Sad and irritable, sleeping through mornings and missing coaching classes for a month","bucket":"presenting"},{"id":"form-115-8","text":"Hides his skipped classes from his parents","bucket":"perpetuating"},{"id":"form-115-9","text":"Says he is ''a waste of money''","bucket":"presenting"},{"id":"form-115-10","text":"Perfectionistic and quiet since childhood","bucket":"predisposing"},{"id":"form-115-11","text":"Scored far below his target in the first mock test of the drop year","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kabir, 17, presents with a moderate depressive episode: a month of low, irritable mood, oversleeping, missed classes and feelings of worthlessness. The weight of his family''s loan and a perfectionistic nature (predisposing) set him up to take setbacks hard; a poor first mock test (precipitating) triggered the episode. Living alone, weekly rank boards and hiding the truth from home (perpetuating) keep him stuck. An observant mentor and a loving grandfather (protective) are key allies. Because young people in coaching hubs are at real risk, a direct question about suicidal thoughts must be part of the first meeting. The fan regulator does not explain his low mood.","hint":"A 17-year-old preparing for JEE alone in a rented room","tags":{"topic":"depression","difficulty":1,"objective":"Sort a coaching-hub depression into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Moderate depressive episode in an adolescent"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-116', 'Mrs Sengupta: four swings in one year (rapid cycling bipolar disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-116-1","text":"Drinks wine most nights to sleep","bucket":"perpetuating"},{"id":"form-116-2","text":"Irregular sleep from grading papers late","bucket":"perpetuating"},{"id":"form-116-3","text":"First depression at 22, treated with antidepressants alone for years","bucket":"predisposing"},{"id":"form-116-4","text":"Her blood group is O negative","bucket":"distractor"},{"id":"form-116-5","text":"Supportive husband and stable job","bucket":"protective"},{"id":"form-116-6","text":"Keeps a mood diary on her phone","bucket":"protective"},{"id":"form-116-7","text":"Currently low with poor sleep and slowed thinking","bucket":"presenting"},{"id":"form-116-8","text":"She teaches Bengali literature","bucket":"distractor"},{"id":"form-116-9","text":"Four distinct mood episodes in the past year, two low and two high","bucket":"presenting"},{"id":"form-116-10","text":"Refuses mood stabilisers because she fears weight gain","bucket":"perpetuating"},{"id":"form-116-11","text":"Brother with bipolar I disorder","bucket":"predisposing"},{"id":"form-116-12","text":"Cycling sped up after her escitalopram dose was raised last year","bucket":"precipitating"},{"id":"form-116-13","text":"Untreated underactive thyroid found on recent tests","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Sengupta, 45, presents with bipolar II disorder with rapid cycling: four mood episodes in a year, currently depressed. A brother with bipolar I and years of antidepressant treatment alone (predisposing) point to a bipolar course missed early. The rise in her antidepressant dose (precipitating) was followed by faster cycling, which antidepressants can provoke in bipolar illness. Low thyroid function, nightly alcohol and irregular sleep (perpetuating) are each known to drive cycling, and her fear of weight gain blocks the main treatment. Her mood diary and a supportive husband (protective) are real assets. The plan is to taper the antidepressant carefully, treat the thyroid, cut the alcohol, protect sleep and agree on a weight-aware mood stabiliser. Her subject and blood group are distractors.","hint":"A 45-year-old college lecturer on an antidepressant for years","tags":{"topic":"bipolar","difficulty":5,"objective":"Pull medical, drug and lifestyle drivers of rapid cycling into one formulation","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Bipolar II disorder with rapid cycling"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-117', 'Nalini: the good daughter who never got angry (depression, psychodynamic view)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-117-1","text":"Her brothers both drive white cars","bucket":"distractor"},{"id":"form-117-2","text":"Mother''s stroke, after which her two brothers left all the care to her","bucket":"precipitating"},{"id":"form-117-3","text":"Low mood, harsh self-blame and exhaustion for three months","bucket":"presenting"},{"id":"form-117-4","text":"Strong sense of meaning in caring","bucket":"protective"},{"id":"form-117-5","text":"Learned that anger was selfish and must be hidden","bucket":"predisposing"},{"id":"form-117-6","text":"No time left for her own friends or music","bucket":"perpetuating"},{"id":"form-117-7","text":"Grew up as the ''good one'' who was praised for never complaining","bucket":"predisposing"},{"id":"form-117-8","text":"A cousin she can speak to honestly","bucket":"protective"},{"id":"form-117-9","text":"Swallows her resentment and turns it into self-criticism","bucket":"perpetuating"},{"id":"form-117-10","text":"Says she is a ''bad daughter'' though she does all the care","bucket":"presenting"},{"id":"form-117-11","text":"Refuses offers of help so she can stay ''the good daughter''","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Nalini, 40, presents with a moderate depressive episode: three months of low mood, exhaustion and harsh self-blame while caring for her mother. A childhood role as the uncomplaining good daughter, in which anger felt forbidden (predisposing), shaped how she copes. The stroke and her brothers'' withdrawal (precipitating) left her overloaded and rightly resentful. From a psychodynamic angle, the anger she cannot show towards her brothers is turned against herself as guilt and self-attack; refusing help and dropping her own life (perpetuating) protect her self-image but deepen the low mood. A cousin she trusts and her sense of purpose (protective) can support therapy that lets her name her anger safely and ask for fair help. The car colour is a distractor.","hint":"A 40-year-old caring alone for her mother after a stroke","tags":{"topic":"depression","difficulty":3,"objective":"Use a psychodynamic lens of anger turned inward in a depression formulation","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"psychodynamics","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-118', 'Ramesh: low but racing (depression with mixed features)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-118-1","text":"Drinks to calm the racing thoughts at night","bucket":"perpetuating"},{"id":"form-118-2","text":"Felt cheerful for a week after his daughter''s wedding two years ago, sleeping normally","bucket":"distractor"},{"id":"form-118-3","text":"Two short spells of unusual drive in his twenties","bucket":"predisposing"},{"id":"form-118-4","text":"Asks good questions about his medicines","bucket":"protective"},{"id":"form-118-5","text":"Restlessness made worse by the antidepressant dose increase","bucket":"perpetuating"},{"id":"form-118-6","text":"Started on an antidepressant three weeks ago for low mood","bucket":"precipitating"},{"id":"form-118-7","text":"Sleeps little but does not feel tired","bucket":"presenting"},{"id":"form-118-8","text":"Low mood and hopelessness with racing thoughts, irritability and talking more than usual","bucket":"presenting"},{"id":"form-118-9","text":"He works in a cement factory","bucket":"distractor"},{"id":"form-118-10","text":"Father had ''periods of big energy'' and later died by suicide","bucket":"predisposing"},{"id":"form-118-11","text":"Brings his wife to every visit","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ramesh, 39, presents with a depressive episode with mixed features: low mood and hopelessness alongside racing thoughts, irritability, pressured speech and little need for sleep. A father with possible bipolar illness and suicide, and earlier spells of high drive (predisposing), point to a bipolar course; the new antidepressant (precipitating) came just before the restless picture. A further dose rise and night drinking (perpetuating) increase both agitation and suicide risk, which is higher when mood is low and energy is high. His wife''s support and his curiosity (protective) help. The card about a cheerful week after his daughter''s wedding is tempting, but normal happiness after a joyful event, with normal sleep, is not a past high and does not count towards a bipolar history. His workplace is a distractor too. The plan is to review the antidepressant, consider a mood stabiliser and assess risk closely.","hint":"A 39-year-old whose antidepressant made him more restless","tags":{"topic":"bipolar","difficulty":4,"objective":"Tell a depressive episode with mixed features apart from plain depression","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Depressive episode with mixed features"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-119', 'Sushma: the sugars that won''t settle (depression with diabetes)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-119-1","text":"Low mood, poor sleep and loss of interest for two months","bucket":"presenting"},{"id":"form-119-2","text":"Has stopped her diet and glucose checks, and sugars are high","bucket":"presenting"},{"id":"form-119-3","text":"Doctor warned her that her kidneys are starting to be affected","bucket":"precipitating"},{"id":"form-119-4","text":"High sugars leave her tired, which she reads as proof she is failing","bucket":"perpetuating"},{"id":"form-119-5","text":"Eats sweets at night for comfort","bucket":"perpetuating"},{"id":"form-119-6","text":"She keeps a picture of Lord Ganesha above the counter","bucket":"distractor"},{"id":"form-119-7","text":"Type 2 diabetes for ten years","bucket":"predisposing"},{"id":"form-119-8","text":"Lost her husband five years ago and runs the shop alone","bucket":"predisposing"},{"id":"form-119-9","text":"Thinks ''what is the use, it will get worse anyway''","bucket":"perpetuating"},{"id":"form-119-10","text":"A local diabetes support group at the clinic","bucket":"protective"},{"id":"form-119-11","text":"Daughter-in-law who helps in the shop","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sushma, 52, presents with a moderate depressive episode alongside poorly controlled type 2 diabetes. A long-standing chronic illness and running the shop alone after widowhood (predisposing) raised her risk; news of early kidney damage (precipitating) brought on hopelessness. The two problems feed each other (perpetuating): high sugars cause fatigue that she reads as failure, comfort eating raises sugars, and hopeless thoughts stop her self-care. Her daughter-in-law and a support group (protective) can help her restart small, achievable steps. Joint care between her physician and the mental health team works best. The picture above the counter reflects her faith but is not a factor in this episode.","hint":"A 52-year-old shopkeeper who stopped checking her glucose","tags":{"topic":"depression","difficulty":2,"objective":"Show the two-way link between depression and a chronic illness","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode with type 2 diabetes"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-120', 'Ali: the labour camp in Dubai (depression in a migrant worker)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-120-1","text":"A cousin in the same camp","bucket":"protective"},{"id":"form-120-2","text":"Cries after calls home and has stopped eating with roommates","bucket":"presenting"},{"id":"form-120-3","text":"Low mood, poor sleep and loss of interest for six weeks","bucket":"presenting"},{"id":"form-120-4","text":"Wife and son he wants to return to","bucket":"protective"},{"id":"form-120-5","text":"Wages delayed for three months by the company","bucket":"precipitating"},{"id":"form-120-6","text":"Cannot send money home and feels ashamed","bucket":"perpetuating"},{"id":"form-120-7","text":"Took a large loan from an agent to get the job","bucket":"predisposing"},{"id":"form-120-8","text":"Has never lived away from his family before","bucket":"predisposing"},{"id":"form-120-9","text":"The camp canteen serves fish curry on Fridays","bucket":"distractor"},{"id":"form-120-10","text":"Lies to his wife that everything is fine","bucket":"perpetuating"},{"id":"form-120-11","text":"Works twelve-hour shifts in heat with little rest","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ali, 31, presents with a moderate depressive episode: six weeks of low mood, poor sleep, loss of interest and withdrawal. A heavy recruitment debt and no past experience of living away (predisposing) left him vulnerable; three months of unpaid wages (precipitating) set off the episode. Shame at not sending money, long hot shifts and hiding his state from his wife (perpetuating) keep it going. A cousin nearby and his family (protective) give him reasons to seek help, and welfare or consular services can help with the wage dispute. The canteen menu is a distractor.","hint":"A 31-year-old from Kerala working on a construction site","tags":{"topic":"depression","difficulty":1,"objective":"Recognise isolation and debt in a migrant worker''s depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-121', 'Prerna: fifteen, irritable and awake all night (early-onset bipolar disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-121-1","text":"Pulled all-nighters for board exam preparation","bucket":"precipitating"},{"id":"form-121-2","text":"Father has bipolar disorder","bucket":"predisposing"},{"id":"form-121-3","text":"A depressive episode last year treated with an antidepressant","bucket":"predisposing"},{"id":"form-121-4","text":"She plays badminton for her school","bucket":"distractor"},{"id":"form-121-5","text":"A school counsellor who knows her well","bucket":"protective"},{"id":"form-121-6","text":"Phone use through the night","bucket":"perpetuating"},{"id":"form-121-7","text":"Posted dozens of messages claiming she will be a famous singer","bucket":"presenting"},{"id":"form-121-8","text":"Sleeps three hours, talks nonstop and is very irritable for two weeks","bucket":"presenting"},{"id":"form-121-9","text":"Mother who keeps careful notes of her changes","bucket":"protective"},{"id":"form-121-10","text":"Parents argue in front of her about whose ''fault'' it is","bucket":"perpetuating"},{"id":"form-121-11","text":"Still taking the antidepressant from last year","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Prerna, 15, presents with a manic episode of adolescent onset: two weeks of very little sleep, pressured speech, marked irritability and grandiose plans. In young people, irritability is often more prominent than elation. A father with bipolar disorder and a prior depressive episode (predisposing) raise the likelihood of a bipolar course; all-night exam study (precipitating) cut her sleep. An ongoing antidepressant, parental conflict and night-time phone use (perpetuating) keep the mood unstable. A counsellor who knows her and a mother keeping notes (protective) help with diagnosis and school planning. Badminton is a healthy activity and not a factor in this episode.","hint":"A Class 10 student suspended for shouting at a teacher","tags":{"topic":"bipolar","difficulty":3,"objective":"Recognise how mania can look in an adolescent","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"child","diagnosis":"Bipolar I disorder, manic episode, adolescent onset"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-122', 'Dr Farhan: the resident who stopped sleeping (depression with suicide risk in a doctor)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-122-1","text":"A batchmate in the same hospital died by suicide last month","bucket":"precipitating"},{"id":"form-122-2","text":"Perfectionistic and private about distress","bucket":"predisposing"},{"id":"form-122-3","text":"Has researched lethal doses and says ''it would be easy for me''","bucket":"presenting"},{"id":"form-122-4","text":"He prefers night duty in the casualty ward","bucket":"distractor"},{"id":"form-122-5","text":"Low mood, insomnia and hopelessness for two months","bucket":"presenting"},{"id":"form-122-6","text":"Agreed to see the psychiatrist after his sister pushed","bucket":"protective"},{"id":"form-122-7","text":"Shouted at by a senior during rounds most days","bucket":"perpetuating"},{"id":"form-122-8","text":"Earlier depressive episode in medical school, never treated","bucket":"predisposing"},{"id":"form-122-9","text":"Close to his younger sister, who he does not want to hurt","bucket":"protective"},{"id":"form-122-10","text":"Thirty-six-hour duty shifts with almost no sleep","bucket":"perpetuating"},{"id":"form-122-11","text":"Easy access to medicines in the ward","bucket":"perpetuating"},{"id":"form-122-12","text":"He has a fellowship interview next year","bucket":"distractor"},{"id":"form-122-13","text":"Fears a mental health record will end his career","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dr Farhan, 28, presents with a severe depressive episode with suicidal ideation and specific method knowledge. Perfectionism, secrecy and an untreated earlier episode (predisposing) set the base; the suicide of a batchmate (precipitating) is an important risk event, since exposure to a peer''s suicide can raise risk. Extreme sleep loss, access to lethal medicines, fear of career damage and a hostile senior (perpetuating) all keep both the mood and the risk high. His bond with his sister and his agreement to come (protective) are real but thin. The plan needs a safety plan, time off duty, limited access to medicines, confidential treatment and a clear message that seeking help is safe. The fellowship interview and his duty preference are not active factors and are distractors here.","hint":"A second-year surgery resident after a colleague''s death","tags":{"topic":"suicide-risk","difficulty":5,"objective":"Weigh risk and protective factors in a doctor with depression","exams":["md-psychiatry","mcp-entrance"],"module":"suicide","diagnosis":"Severe depressive episode with suicidal ideation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-123', 'Rekha: the empty nest and the hot flushes (perimenopausal depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-123-1","text":"A friend who is a yoga teacher","bucket":"protective"},{"id":"form-123-2","text":"Low mood, tearfulness and poor sleep for two months","bucket":"presenting"},{"id":"form-123-3","text":"Her son''s college has a large library","bucket":"distractor"},{"id":"form-123-4","text":"Night sweats wake her several times a night","bucket":"perpetuating"},{"id":"form-123-5","text":"Low mood after the birth of her second child","bucket":"predisposing"},{"id":"form-123-6","text":"Interested in returning to her old tailoring work","bucket":"protective"},{"id":"form-123-7","text":"Her whole identity built around raising her children","bucket":"predisposing"},{"id":"form-123-8","text":"Husband dismisses it as ''women''s problems''","bucket":"perpetuating"},{"id":"form-123-9","text":"Feels her life has ''no purpose now''","bucket":"presenting"},{"id":"form-123-10","text":"Younger son left for college in Bengaluru as her periods became irregular","bucket":"precipitating"},{"id":"form-123-11","text":"Has stopped visiting her friends'' kitty party","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rekha, 49, presents with a moderate depressive episode in the perimenopause. A past postnatal low spell and an identity centred on raising children (predisposing) made this stage harder; her younger son leaving home at the same time as hormonal change (precipitating) began the episode. Night sweats breaking sleep, a dismissive husband and withdrawal from friends (perpetuating) keep her low. A supportive friend and her interest in tailoring (protective) suggest a plan of treating sleep and vasomotor symptoms with her gynaecologist, activity and new roles, and couple education. The college library is a distractor.","hint":"A 49-year-old homemaker in Indore","tags":{"topic":"depression","difficulty":2,"objective":"Include hormonal and role changes in midlife depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode in the perimenopause"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-124', 'Kamal: after the godown fire (depression, not adjustment disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-124-1","text":"Low mood nearly all day, every day, for five weeks, with loss of pleasure in everything","bucket":"presenting"},{"id":"form-124-2","text":"Wakes at 3 am, has lost 5 kg and feels worthless","bucket":"presenting"},{"id":"form-124-3","text":"Fire destroyed his godown and uninsured stock two months ago","bucket":"precipitating"},{"id":"form-124-4","text":"The fire brigade took forty minutes to reach","bucket":"distractor"},{"id":"form-124-5","text":"Depressive episode at 30 after his father''s death","bucket":"predisposing"},{"id":"form-124-6","text":"Tends to see setbacks as personal failures","bucket":"predisposing"},{"id":"form-124-7","text":"Felt shaken for two days after a minor road accident last year","bucket":"distractor"},{"id":"form-124-8","text":"Has started to rebuild once before","bucket":"protective"},{"id":"form-124-9","text":"Brother offering a loan to restart","bucket":"protective"},{"id":"form-124-10","text":"Spends the day replaying what he should have done","bucket":"perpetuating"},{"id":"form-124-11","text":"Has stopped going to the market or seeing traders","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kamal, 44, presents with a moderate depressive episode after a godown fire. Although the episode followed a clear stressor, he now meets full criteria for depression: pervasive low mood and loss of pleasure for over two weeks, early waking, weight loss and worthlessness. When full criteria are met, a depressive episode is diagnosed even if a stressor started it; adjustment disorder is reserved for distress that does not meet another disorder. A past episode and a self-blaming style (predisposing), the fire (precipitating), and rumination and withdrawal (perpetuating) shape the picture. His brother''s offer and past resilience (protective) help. The card about feeling shaken after a minor accident is tempting, but a short, normal reaction to a frightening event is not a past episode or a vulnerability. The fire brigade''s delay is a distractor.","hint":"A 44-year-old trader who lost his stock","tags":{"topic":"depression","difficulty":4,"objective":"Tell a full depressive episode apart from an adjustment disorder","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-125', 'Bhushan: no sleep, big plans and a new car loan (mania after stopping lithium)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-125-1","text":"Sleeps two hours, talks fast and jumps from idea to idea for a week","bucket":"presenting"},{"id":"form-125-2","text":"Believes he is ''cured'' and refuses medicine","bucket":"perpetuating"},{"id":"form-125-3","text":"Bipolar I disorder diagnosed eight years ago","bucket":"predisposing"},{"id":"form-125-4","text":"Stopped lithium two months ago because he felt well","bucket":"precipitating"},{"id":"form-125-5","text":"Wife who knows his warning signs","bucket":"protective"},{"id":"form-125-6","text":"Has recovered well each time before","bucket":"protective"},{"id":"form-125-7","text":"Sleeps very little and stays out late","bucket":"perpetuating"},{"id":"form-125-8","text":"He owns a red toolbox","bucket":"distractor"},{"id":"form-125-9","text":"Two earlier manic episodes","bucket":"predisposing"},{"id":"form-125-10","text":"Took a car loan and promised friends free wiring for their homes","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Bhushan, 32, presents with a manic relapse of bipolar I disorder: reduced need for sleep, pressured speech, flight of ideas and reckless spending. A known bipolar illness with past manic episodes (predisposing) is the base; stopping lithium because he felt well (precipitating) is one of the most common triggers of relapse. Loss of insight and continued sleep loss (perpetuating) keep the mania going. A wife who knows his early signs and a history of good recovery (protective) support restarting treatment and later relapse prevention work. The toolbox is a distractor.","hint":"A 32-year-old electrician with known bipolar disorder","tags":{"topic":"bipolar","difficulty":1,"objective":"Sort a classic manic relapse into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"bipolar","diagnosis":"Bipolar I disorder, current episode manic"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-126', 'Shanti: the ASHA worker who carries everyone''s troubles (depression with domestic violence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-126-1","text":"Long hours visiting homes with no time to rest","bucket":"perpetuating"},{"id":"form-126-2","text":"She has a new smartphone for her health reports","bucket":"distractor"},{"id":"form-126-3","text":"Husband''s beatings became more frequent after he lost his job","bucket":"precipitating"},{"id":"form-126-4","text":"Hides bruises from the women she helps","bucket":"perpetuating"},{"id":"form-126-5","text":"Husband has hit her on and off for years","bucket":"predisposing"},{"id":"form-126-6","text":"Cries when alone and has thought she would be better off dead, with no plan","bucket":"presenting"},{"id":"form-126-7","text":"Headaches, tiredness and low mood for two months","bucket":"presenting"},{"id":"form-126-8","text":"Feels she cannot complain because the family''s honour is at stake","bucket":"perpetuating"},{"id":"form-126-9","text":"Married at 17 and left school early","bucket":"predisposing"},{"id":"form-126-10","text":"A trusted supervisor at the primary health centre","bucket":"protective"},{"id":"form-126-11","text":"Respected in the village for her work","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shanti, 34, presents with a moderate depressive episode with headaches, fatigue, tearfulness and passive death wishes. Early marriage, little schooling and long-term violence at home (predisposing) form the base; escalation of beatings after her husband''s job loss (precipitating) triggered the episode. Silence for the family''s honour, overwork and hiding injuries (perpetuating) keep her trapped. Her standing in the village and a trusted supervisor (protective) can open doors to safety planning, legal options under domestic violence law and treatment. Her somatic complaints are common ways that depression is expressed and should not be dismissed. The smartphone is a distractor.","hint":"A community health worker in a Rajasthan village","tags":{"topic":"depression","difficulty":3,"objective":"Include violence at home and caring roles in a woman''s depression","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-127', 'Rocky: the DJ with three admissions (bipolar I with substance use)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-127-1","text":"Daily cannabis and weekend alcohol","bucket":"perpetuating"},{"id":"form-127-2","text":"His club is in a five-star hotel","bucket":"distractor"},{"id":"form-127-3","text":"Says he is the ''best DJ in Asia'' and will tour the world","bucket":"presenting"},{"id":"form-127-4","text":"Elated and irritable, no sleep for four days, fought with a bouncer","bucket":"presenting"},{"id":"form-127-5","text":"Stops medicine as soon as he leaves hospital","bucket":"perpetuating"},{"id":"form-127-6","text":"Onset at 20, three admissions in nine years","bucket":"predisposing"},{"id":"form-127-7","text":"Night work keeps his sleep chaotic","bucket":"perpetuating"},{"id":"form-127-8","text":"Older brother who has stayed involved","bucket":"protective"},{"id":"form-127-9","text":"He has a large following on a music streaming app","bucket":"distractor"},{"id":"form-127-10","text":"Has a nominated representative under an advance directive he made when well","bucket":"protective"},{"id":"form-127-11","text":"Sees mania as his creative ''gift''","bucket":"perpetuating"},{"id":"form-127-12","text":"Back-to-back New Year gigs with no sleep and heavy cannabis use","bucket":"precipitating"},{"id":"form-127-13","text":"Mother has recurrent depression","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rocky, 29, presents with a manic episode of bipolar I disorder with alcohol and cannabis use, arriving after a violent incident. Early onset, repeated admissions and family mood disorder (predisposing) show a severe course; sleepless gigs with heavy cannabis (precipitating) triggered this episode. Ongoing substance use, stopping medicine on discharge, night-shift sleep and his view of mania as a gift (perpetuating) explain the revolving door. In CBT terms, the positive beliefs about highs are a key target; motivational work is needed for cannabis. His brother and an advance directive with a nominated representative (protective) mean his own earlier wishes can guide care now. A long-acting medicine, sleep protection and a relapse signature plan should be discussed. His streaming followers and the hotel are distractors.","hint":"A 29-year-old brought by police after a fight at a club","tags":{"topic":"bipolar","difficulty":5,"objective":"Formulate a revolving-door bipolar course with substances and poor insight","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Bipolar I disorder, current episode manic, with alcohol and cannabis use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-128', 'Mini: the ten-year-old who stopped drawing (childhood depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-128-1","text":"Irritable, tearful and complains of tummy aches on school mornings for six weeks","bucket":"presenting"},{"id":"form-128-2","text":"Father moved out three months ago and visits rarely","bucket":"precipitating"},{"id":"form-128-3","text":"Sensitive, anxious child","bucket":"predisposing"},{"id":"form-128-4","text":"Teacher punishes her for poor homework","bucket":"perpetuating"},{"id":"form-128-5","text":"Each parent asks her what the other said","bucket":"perpetuating"},{"id":"form-128-6","text":"Her school changed its uniform colour this year","bucket":"distractor"},{"id":"form-128-7","text":"Has stopped drawing, which she loved","bucket":"presenting"},{"id":"form-128-8","text":"Loving maternal grandmother who lives with them","bucket":"protective"},{"id":"form-128-9","text":"A best friend in her class","bucket":"protective"},{"id":"form-128-10","text":"Years of loud fights between her parents","bucket":"predisposing"},{"id":"form-128-11","text":"Believes the separation is her fault for being ''naughty''","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mini, 10, presents with a moderate depressive episode: six weeks of irritability, tearfulness, morning stomach aches and loss of interest in drawing. In children, depression often shows as irritability and bodily complaints rather than stated sadness. A sensitive temperament and years of parental conflict (predisposing) left her vulnerable; her father leaving (precipitating) began the episode. Being caught between parents, blaming herself and punishment at school (perpetuating) keep it going. Her grandmother and best friend (protective) are strong supports. Work with both parents to stop using her as a messenger, and a word with her teacher, are central. The uniform change is a distractor.","hint":"A Class 5 girl after her parents separated","tags":{"topic":"depression","difficulty":2,"objective":"Recognise depression in a child, where irritability and complaints of pain are common","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Moderate depressive episode in a child"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-129', 'Mr Venu: silent and still on the bed (depression with catatonia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-129-1","text":"Holds his arm in the air when the doctor lifts it","bucket":"presenting"},{"id":"form-129-2","text":"He was a union leader at the mill","bucket":"distractor"},{"id":"form-129-3","text":"Months of low mood after losing his job at a closed textile mill","bucket":"precipitating"},{"id":"form-129-4","text":"His temperature is normal and he has never taken an antipsychotic","bucket":"distractor"},{"id":"form-129-5","text":"Brother died by suicide","bucket":"predisposing"},{"id":"form-129-6","text":"Two earlier severe depressive episodes","bucket":"predisposing"},{"id":"form-129-7","text":"Earlier episodes responded well to treatment","bucket":"protective"},{"id":"form-129-8","text":"Lies still and mute for four days, refuses food and water","bucket":"presenting"},{"id":"form-129-9","text":"Wife who brought him in","bucket":"protective"},{"id":"form-129-10","text":"Family waited, thinking he was ''just very sad''","bucket":"perpetuating"},{"id":"form-129-11","text":"Not drinking fluids, so he is getting dehydrated","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Venu, 55, presents with a severe depressive episode with catatonia: mutism, immobility, refusal of food and fluids and posturing (waxy holding of a lifted limb). Past severe episodes and a family suicide (predisposing) mark a serious mood illness; months of depression after losing his job (precipitating) led into the catatonic state. Dehydration and delay in seeking care (perpetuating) make this a medical emergency. Good response to past treatment and a caring wife (protective) are hopeful. Catatonia usually responds to benzodiazepines such as lorazepam, and ECT is very effective when they are not enough. The card about normal temperature and no antipsychotic is useful because it makes neuroleptic malignant syndrome, the main look-alike, unlikely, but it is a negative finding rather than a cause, trigger, maintaining factor or strength, so it stays out of the grid. His union role is a distractor.","hint":"A 55-year-old who has stopped eating and speaking","tags":{"topic":"depression","difficulty":4,"objective":"Recognise catatonia within a severe depression and its urgency","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Severe depressive episode with catatonia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-130', 'Siddharth: the son who took his brother''s place (depression, psychodynamic view)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-130-1","text":"His office moved to a new tower in Gurugram","bucket":"distractor"},{"id":"form-130-2","text":"Parents named him after the brother and spoke of him constantly","bucket":"predisposing"},{"id":"form-130-3","text":"Curious about himself and keen on talking therapy","bucket":"protective"},{"id":"form-130-4","text":"Believes he must succeed for two sons, not one","bucket":"perpetuating"},{"id":"form-130-5","text":"Low mood, emptiness and a feeling of living ''someone else''s life'' for three months","bucket":"presenting"},{"id":"form-130-6","text":"Has never grieved the brother he never knew","bucket":"perpetuating"},{"id":"form-130-7","text":"Avoids telling his parents his own wishes","bucket":"perpetuating"},{"id":"form-130-8","text":"Born a year after his elder brother died in a road accident","bucket":"predisposing"},{"id":"form-130-9","text":"Sleeping poorly and losing interest in work","bucket":"presenting"},{"id":"form-130-10","text":"Failed to get a partnership his parents had celebrated in advance","bucket":"precipitating"},{"id":"form-130-11","text":"Wife who encourages his love of photography","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Siddharth, 33, presents with a moderate depressive episode marked by emptiness and a sense of living someone else''s life. He was born soon after his brother''s death and raised in his shadow (predisposing), a situation sometimes described as being a replacement child. Missing the expected partnership (precipitating) broke the fragile sense that achievement made him worthy. From a psychodynamic angle, he has carried his parents'' unmourned loss and their hopes for the dead son; striving for two people, an ungrieved loss and silence about his own wishes (perpetuating) keep him empty and low. His wife''s support and his curiosity (protective) suit an insight-oriented therapy alongside usual depression care. The office move is a distractor.","hint":"A 33-year-old chartered accountant born after his brother died","tags":{"topic":"depression","difficulty":3,"objective":"Use early relationships and identity to explain an adult depression","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"psychodynamics","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-131', 'Ammamma: the village grandmother in a Bengaluru flat (late-life depression after relocation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-131-1","text":"Low mood, poor appetite and sitting by the window all day for two months","bucket":"presenting"},{"id":"form-131-2","text":"Moved to her son''s city flat after a fall at the farm","bucket":"precipitating"},{"id":"form-131-3","text":"Widowed three years ago","bucket":"predisposing"},{"id":"form-131-4","text":"Lift and traffic frighten her so she never goes out","bucket":"perpetuating"},{"id":"form-131-5","text":"Alone all day while everyone works","bucket":"perpetuating"},{"id":"form-131-6","text":"Granddaughter who sits with her in the evenings","bucket":"protective"},{"id":"form-131-7","text":"Has lived her whole life in one village","bucket":"predisposing"},{"id":"form-131-8","text":"Cannot speak the local language or the family''s English","bucket":"perpetuating"},{"id":"form-131-9","text":"The building has a swimming pool","bucket":"distractor"},{"id":"form-131-10","text":"Says ''I am just a burden here''","bucket":"presenting"},{"id":"form-131-11","text":"Daily prayer and love of old film songs","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ammamma, 74, presents with a moderate depressive episode two months after moving from her village to her son''s city flat. Widowhood and a lifetime rooted in one place (predisposing) made the move a big loss; the relocation after a fall (precipitating) began the episode. Language barriers, long hours alone and fear of going out (perpetuating) keep her isolated and feeling like a burden. Her granddaughter and her faith and music (protective) can anchor a plan of daily structure, a day centre or temple group, and family time. The swimming pool is a distractor.","hint":"A 74-year-old moved from her farm to her son''s twelfth-floor flat","tags":{"topic":"depression","difficulty":1,"objective":"Sort a late-life depression after relocation into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"lifespan","diagnosis":"Moderate depressive episode in late life"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-132', 'Pallavi: the lithium tremor and the wedding photos (bipolar depression after stopping treatment)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-132-1","text":"Has stopped going to work since the honeymoon","bucket":"presenting"},{"id":"form-132-2","text":"Stable on lithium for four years","bucket":"predisposing"},{"id":"form-132-3","text":"Bipolar I disorder with one manic episode at 22","bucket":"predisposing"},{"id":"form-132-4","text":"Husband who knows her diagnosis and supports her","bucket":"protective"},{"id":"form-132-5","text":"Worried the hand tremor and weight gain would show in wedding photos","bucket":"perpetuating"},{"id":"form-132-6","text":"Avoids the doctor because she feels guilty","bucket":"perpetuating"},{"id":"form-132-7","text":"Good response to lithium in the past","bucket":"protective"},{"id":"form-132-8","text":"Stopped lithium on her own three months before the wedding","bucket":"precipitating"},{"id":"form-132-9","text":"Hiding her diagnosis from her in-laws","bucket":"perpetuating"},{"id":"form-132-10","text":"Low mood, oversleeping and slowed movement for a month","bucket":"presenting"},{"id":"form-132-11","text":"Her wedding was held in Udaipur","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pallavi, 27, presents with a depressive episode of bipolar I disorder after stopping lithium. A known bipolar illness (predisposing) means relapse is likely without treatment; stopping lithium suddenly before her wedding (precipitating) set off the episode. Fear of visible tremor and weight gain, secrecy with her in-laws and guilt about seeing the doctor (perpetuating) delay help. Her husband''s support and past response to lithium (protective) are strengths. Taking side effects seriously, for example dose or timing changes or other mood stabilisers, keeps her in care. The wedding venue is a distractor.","hint":"A 27-year-old who stopped lithium before her wedding","tags":{"topic":"bipolar","difficulty":2,"objective":"Show how side effects lead to stopping treatment and relapse","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"stabilisers","diagnosis":"Bipolar I disorder, current episode depressed"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-133', 'Ravi Iyer: the cousin''s wedding and the question about marriage (depression and minority stress)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-133-1","text":"Says he is tired of ''living a double life''","bucket":"presenting"},{"id":"form-133-2","text":"Constant hiding and fear of being found out","bucket":"perpetuating"},{"id":"form-133-3","text":"At a cousin''s wedding, relatives announced they had found a bride for him","bucket":"precipitating"},{"id":"form-133-4","text":"Believes he will disappoint his parents whatever he does","bucket":"perpetuating"},{"id":"form-133-5","text":"An affirming sister who knows","bucket":"protective"},{"id":"form-133-6","text":"Low mood, poor sleep and withdrawal from friends for two months","bucket":"presenting"},{"id":"form-133-7","text":"Has hidden his sexuality from his conservative family","bucket":"predisposing"},{"id":"form-133-8","text":"His sexual orientation, in itself","bucket":"distractor"},{"id":"form-133-9","text":"Has stopped meeting his partner to avoid suspicion","bucket":"perpetuating"},{"id":"form-133-10","text":"A supportive queer peer group online","bucket":"protective"},{"id":"form-133-11","text":"He works in a bank on Anna Salai","bucket":"distractor"},{"id":"form-133-12","text":"Bullied in school for being ''soft''","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ravi, 29, presents with a moderate depressive episode with low mood, poor sleep and withdrawal. School bullying and years of hiding his sexuality from a conservative family (predisposing) add up to minority stress; the public announcement of a match (precipitating) made the conflict impossible to avoid. Concealment, cutting off his partner and the belief he must disappoint his parents (perpetuating) keep him low. An online peer group and an affirming sister (protective) are vital. The card naming his sexual orientation in itself is left out on purpose: sexual orientation is not a disorder or a risk factor, and it is the stigma and hiding, not his identity, that harm his mood. Care should be affirming, and any attempt to change his orientation is harmful and unethical. His workplace is a distractor.","hint":"A 29-year-old gay man in Chennai under pressure to marry","tags":{"topic":"depression","difficulty":4,"objective":"Place minority stress and family expectations correctly in a formulation","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-134', 'Mrs Chatterjee: worse after the new tablet (depression and low sodium in an older woman)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-134-1","text":"Low mood and poor appetite for three months","bucket":"presenting"},{"id":"form-134-2","text":"Drinks many glasses of water because she was told it is healthy","bucket":"perpetuating"},{"id":"form-134-3","text":"Started sertraline two weeks ago and the dose was raised last week","bucket":"precipitating"},{"id":"form-134-4","text":"Helper who noticed the change quickly","bucket":"protective"},{"id":"form-134-5","text":"Widowed a year ago and lives with a paid helper","bucket":"predisposing"},{"id":"form-134-6","text":"Takes a water tablet for blood pressure","bucket":"predisposing"},{"id":"form-134-7","text":"No cognitive problems before this month","bucket":"protective"},{"id":"form-134-8","text":"Sodium is low on blood tests","bucket":"perpetuating"},{"id":"form-134-9","text":"Family think the confusion is ''more depression'' and want a higher dose","bucket":"perpetuating"},{"id":"form-134-10","text":"She was a famous Rabindra Sangeet singer","bucket":"distractor"},{"id":"form-134-11","text":"Her son lives in Kolkata","bucket":"distractor"},{"id":"form-134-12","text":"Confused, unsteady and fell twice in the past week","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Chatterjee, 78, presents with a late-life depressive episode now complicated by new confusion and falls. Widowhood and living with paid help (predisposing) set the base for depression; a diuretic, older age and female sex raise her risk of low sodium. Starting and increasing an SSRI (precipitating) was followed within two weeks by confusion, and low sodium is a known effect of SSRIs in older people. The family reading confusion as more depression, and heavy water intake (perpetuating), could make it worse. Her alert helper and normal cognition before this month (protective) point to a reversible cause. The plan is urgent medical review of sodium, a pause or change of the antidepressant, and fall precautions. Her singing career and her son''s city are distractors.","hint":"A 78-year-old widow who became confused after starting an antidepressant","tags":{"topic":"depression","difficulty":5,"objective":"Fit a medicine side effect into a late-life depression formulation","exams":["md-psychiatry","mcp-entrance"],"module":"antidepressants","diagnosis":"Depressive episode with SSRI-associated hyponatraemia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-135', 'Jasleen: the best month of her life (recovery, not hypomania)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-135-1","text":"Has rejoined her dance class and laughs with colleagues again","bucket":"presenting"},{"id":"form-135-2","text":"No earlier periods of unusual energy","bucket":"predisposing"},{"id":"form-135-3","text":"Spent a lot on Diwali gifts last year, as she does every year","bucket":"distractor"},{"id":"form-135-4","text":"Spending, speech and judgement are her usual","bucket":"protective"},{"id":"form-135-5","text":"Sleeps seven hours and works normally","bucket":"protective"},{"id":"form-135-6","text":"Feels cheerful and energetic after eight weeks on an antidepressant","bucket":"presenting"},{"id":"form-135-7","text":"She grew up in Amritsar","bucket":"distractor"},{"id":"form-135-8","text":"One depressive episode, no family history of bipolar disorder","bucket":"predisposing"},{"id":"form-135-9","text":"Her husband, who read about bipolar disorder, worries every good day is a ''high''","bucket":"perpetuating"},{"id":"form-135-10","text":"Steady recovery since starting treatment two months ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Jasleen, 35, presents in remission from a depressive episode, feeling well after eight weeks of treatment. A single episode without bipolar family history or past highs (predisposing) makes a bipolar course less likely, and her steady improvement on treatment (precipitating) explains the change. Normal sleep, normal work and normal speech and spending (protective) show this is recovery, not hypomania. Her husband''s worry (perpetuating) can make her doubt healthy happiness, so explaining the difference matters. The card about Diwali spending is tempting, but it is her usual yearly habit and not a change, so it is not evidence of hypomania. Her home town is a distractor. It is still sensible to teach the couple the early signs of hypomania to watch for.","hint":"A 35-year-old teacher who feels well for the first time in a year","tags":{"topic":"bipolar","difficulty":4,"objective":"Avoid over-reading normal recovery as hypomania","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"bipolar","diagnosis":"Remission of a depressive episode, no hypomania"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-136', 'Sunil: the third time the darkness came back (recurrent depression and relapse prevention)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-136-1","text":"Promoted to a role with constant client calls in the evenings","bucket":"precipitating"},{"id":"form-136-2","text":"Even between episodes, some low energy and poor sleep remain","bucket":"presenting"},{"id":"form-136-3","text":"His company makes car parts","bucket":"distractor"},{"id":"form-136-4","text":"Stopped medicine after three months each time once he felt better","bucket":"perpetuating"},{"id":"form-136-5","text":"Third depressive episode in eight years, with low mood and poor concentration","bucket":"presenting"},{"id":"form-136-6","text":"A ruminative style since his teens","bucket":"predisposing"},{"id":"form-136-7","text":"Leftover symptoms never fully treated","bucket":"perpetuating"},{"id":"form-136-8","text":"Wife who spots his early warning signs","bucket":"protective"},{"id":"form-136-9","text":"He drinks two cups of filter coffee a day","bucket":"distractor"},{"id":"form-136-10","text":"Interested in mindfulness and has tried an app","bucket":"protective"},{"id":"form-136-11","text":"Mother with recurrent depression","bucket":"predisposing"},{"id":"form-136-12","text":"Ruminates for hours about ''why me'' after each setback","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sunil, 42, presents with a third depressive episode and residual symptoms between episodes. A family history of recurrent depression and a long ruminative style (predisposing) raise his risk; a stressful new role with evening calls (precipitating) set off this episode. Stopping medicine soon after feeling better, untreated residual symptoms and rumination (perpetuating) explain why it keeps returning. Each new episode raises the risk of the next, which is why the aim now is full remission and long-term maintenance. In CBT terms the rumination is the key target, and mindfulness-based cognitive therapy is designed to prevent relapse in recurrent depression. His wife''s watchfulness and his interest in mindfulness (protective) fit a written relapse prevention plan. His employer and his coffee are distractors.","hint":"A 42-year-old engineer who stops treatment each time he improves","tags":{"topic":"depression","difficulty":5,"objective":"Build a relapse-prevention formulation for recurrent depression","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"therapies","diagnosis":"Recurrent depressive disorder, current episode moderate"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-137', 'Anvi: the gate at the school bus (separation anxiety in a young child)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-137-1","text":"Fears something bad will happen to her mother while she is away","bucket":"presenting"},{"id":"form-137-2","text":"Kind class teacher who greets her at the gate","bucket":"protective"},{"id":"form-137-3","text":"Mother is anxious and checks on her often","bucket":"predisposing"},{"id":"form-137-4","text":"Close to her grandfather who lives with them","bucket":"protective"},{"id":"form-137-5","text":"Allowed to stay home on days she vomits","bucket":"perpetuating"},{"id":"form-137-6","text":"Mother calls her from work every hour to calm her","bucket":"perpetuating"},{"id":"form-137-7","text":"Shy, cautious child since a toddler","bucket":"predisposing"},{"id":"form-137-8","text":"Her school bus is yellow with a blue stripe","bucket":"distractor"},{"id":"form-137-9","text":"Cries, clings and vomits on school mornings for two months","bucket":"presenting"},{"id":"form-137-10","text":"Mother went back to work after a long break when a baby brother was born","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anvi, 7, presents with separation anxiety disorder: two months of crying, clinging and morning vomiting with fears that harm will come to her mother. A shy, cautious temperament and an anxious, protective mother (predisposing) shaped her worry; her mother''s return to work soon after a new baby arrived (precipitating) set it off. Staying home on bad days and hourly reassurance calls (perpetuating) teach her that separation really is dangerous and that she cannot cope. A warm teacher and her grandfather (protective) can help with brief, confident goodbyes and steady school attendance. The bus colour is a distractor.","hint":"A 7-year-old who screams when her mother leaves for work","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort a childhood separation anxiety into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Separation anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-138', 'Tejas: the street dog by the temple (dog phobia after a bite)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-138-1","text":"Bitten on the leg by a street dog near the temple and given rabies injections","bucket":"precipitating"},{"id":"form-138-2","text":"Refuses to walk the lane to tuition for four months","bucket":"presenting"},{"id":"form-138-3","text":"Freezes, cries and runs when he sees any dog, even a puppy","bucket":"presenting"},{"id":"form-138-4","text":"Father now drives him everywhere","bucket":"perpetuating"},{"id":"form-138-5","text":"Sensitive child who startles easily","bucket":"predisposing"},{"id":"form-138-6","text":"Watches videos of dog attacks on his cousin''s phone","bucket":"perpetuating"},{"id":"form-138-7","text":"He is learning tabla on Saturdays","bucket":"distractor"},{"id":"form-138-8","text":"Wants to play cricket in the park again","bucket":"protective"},{"id":"form-138-9","text":"Neighbour has a calm old Labrador he once liked","bucket":"protective"},{"id":"form-138-10","text":"Grandmother often warns him that dogs carry rabies","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Tejas, 9, presents with a specific phobia of dogs: intense fear and avoidance of all dogs for four months. A sensitive temperament and repeated warnings about rabies (predisposing) primed him to fear dogs; the bite and the painful injections (precipitating) turned that fear into a phobia through a frightening learning experience. Being driven everywhere and watching attack videos (perpetuating) keep the fear high because he never learns that most dogs are safe. A gentle neighbour''s dog and his wish to play in the park (protective) give a natural ladder for graded exposure. Tabla lessons are a distractor.","hint":"A 9-year-old who will not walk to tuition","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort a specific phobia that began with a frightening event","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Specific phobia, animal type (dogs)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-139', 'Harsh: the auditor who rehearses every disaster (generalised anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-139-1","text":"Moved to a firm where one audit mistake led to a colleague being fired","bucket":"precipitating"},{"id":"form-139-2","text":"Fiancée who is calm and practical","bucket":"protective"},{"id":"form-139-3","text":"Father lost his business when Harsh was twelve","bucket":"predisposing"},{"id":"form-139-4","text":"Believes worrying stops bad things happening","bucket":"perpetuating"},{"id":"form-139-5","text":"Worries most of the day about work, money and his parents'' health for over a year","bucket":"presenting"},{"id":"form-139-6","text":"He uses a standing desk at the office","bucket":"distractor"},{"id":"form-139-7","text":"Avoids any task he cannot finish perfectly","bucket":"perpetuating"},{"id":"form-139-8","text":"Re-checks his work late into the night","bucket":"perpetuating"},{"id":"form-139-9","text":"Has always been a cautious planner","bucket":"predisposing"},{"id":"form-139-10","text":"Tense neck, poor sleep and trouble concentrating","bucket":"presenting"},{"id":"form-139-11","text":"Plays football with friends on Sundays","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Harsh, 28, presents with generalised anxiety disorder: a year of hard-to-control worry across many areas with muscle tension, poor sleep and poor concentration. A family business collapse in his childhood and a cautious nature (predisposing) taught him the world is uncertain; a workplace where mistakes cost jobs (precipitating) intensified the worry. Late-night checking, the belief that worry protects him and avoidance of imperfect tasks (perpetuating) keep it going. A calm fiancée and regular football (protective) support CBT focused on tolerating uncertainty. The standing desk is a distractor.","hint":"A 28-year-old chartered accountant in Mumbai","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort generalised anxiety into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Generalised anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-140', 'Simran: blank in the board exam hall (test anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-140-1","text":"Mind goes blank, hands shake and heart races in exams","bucket":"presenting"},{"id":"form-140-2","text":"Tells herself ''if I blank again my life is over''","bucket":"perpetuating"},{"id":"form-140-3","text":"Teachers compared her to him all through school","bucket":"predisposing"},{"id":"form-140-4","text":"Fainted in the pre-board maths exam","bucket":"precipitating"},{"id":"form-140-5","text":"Scores far lower in exams than in practice at home","bucket":"presenting"},{"id":"form-140-6","text":"Skips breakfast on exam days","bucket":"perpetuating"},{"id":"form-140-7","text":"Elder brother is the family ''topper''","bucket":"predisposing"},{"id":"form-140-8","text":"Her exam centre is in another school","bucket":"distractor"},{"id":"form-140-9","text":"A coaching teacher who believes in her","bucket":"protective"},{"id":"form-140-10","text":"Studies until 3 am the night before every test","bucket":"perpetuating"},{"id":"form-140-11","text":"Strong knowledge of the subjects","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Simran, 17, presents with test anxiety: blanking, trembling and racing heart in exams with performance far below her ability. Being compared to a high-achieving brother (predisposing) tied her worth to marks; fainting in the pre-board (precipitating) made her fear the next exam. Night-long study, catastrophic thoughts and skipped breakfast (perpetuating) raise arousal and lower recall. Her real knowledge and a teacher''s faith (protective) support a plan of sleep, breakfast, breathing practice, mock exams and work on her thoughts. The exam centre location is a distractor.","hint":"A Class 12 student who knows the answers at home","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort performance anxiety in exams into the 5 Ps","exams":["ma-semester","cuet-pg","ugc-net"],"module":"anxiety","diagnosis":"Performance anxiety (test anxiety)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-141', 'Mr Gill: down on the floor at the blood test (blood-injection phobia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-141-1","text":"Feels ashamed and jokes it away instead of asking for help","bucket":"perpetuating"},{"id":"form-141-2","text":"Has refused insulin despite very high sugars","bucket":"presenting"},{"id":"form-141-3","text":"Told by his doctor last month that tablets are no longer enough and he needs injections","bucket":"precipitating"},{"id":"form-141-4","text":"He runs a dhaba on the highway","bucket":"distractor"},{"id":"form-141-5","text":"Wants to stay healthy for his grandchildren","bucket":"protective"},{"id":"form-141-6","text":"Has skipped all blood tests for two years","bucket":"perpetuating"},{"id":"form-141-7","text":"Fainted at school when a friend cut his hand","bucket":"predisposing"},{"id":"form-141-8","text":"Wife who is a nurse","bucket":"protective"},{"id":"form-141-9","text":"Feels faint and has passed out three times during blood tests","bucket":"presenting"},{"id":"form-141-10","text":"Father also ''could not stand the sight of blood''","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Gill, 45, presents with blood-injection-injury phobia that now blocks his diabetes care. Unlike most phobias, this type often causes a sudden drop in heart rate and blood pressure after an initial rise, leading to fainting. Early fainting and a father with the same fear (predisposing) suggest a family pattern; the need to start insulin (precipitating) brought the problem to a head. Years of avoiding tests and shame hidden behind jokes (perpetuating) keep the fear alive. His nurse wife and his grandchildren (protective) support graded exposure combined with applied tension, which raises blood pressure and prevents fainting. The dhaba is a distractor.","hint":"A 45-year-old who must start insulin but faints at needles","tags":{"topic":"anxiety","difficulty":2,"objective":"Recognise the fainting pattern special to blood-injection-injury phobia","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Specific phobia, blood-injection-injury type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-142', 'Farida: the inhaler and the fear (panic attacks with asthma)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-142-1","text":"Severe asthma attack at 12 that needed intensive care","bucket":"predisposing"},{"id":"form-142-2","text":"Uses her reliever inhaler many times a day, which makes her shaky","bucket":"perpetuating"},{"id":"form-142-3","text":"A friend with asthma died last year during an attack","bucket":"precipitating"},{"id":"form-142-4","text":"Mother panics whenever Farida coughs","bucket":"predisposing"},{"id":"form-142-5","text":"Avoids walking or stairs in case she gets breathless","bucket":"perpetuating"},{"id":"form-142-6","text":"A pulmonologist who explains her tests clearly","bucket":"protective"},{"id":"form-142-7","text":"Sudden breathlessness, tingling hands and fear of dying several times a week","bucket":"presenting"},{"id":"form-142-8","text":"Studying to be a pharmacist and keen to understand","bucket":"protective"},{"id":"form-142-9","text":"Peak flow is usually normal during these attacks","bucket":"presenting"},{"id":"form-142-10","text":"Goes to casualty for reassurance most weeks","bucket":"perpetuating"},{"id":"form-142-11","text":"Her family moved from Hyderabad to Pune","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Farida, 23, presents with panic disorder alongside asthma. Many attacks come with tingling and fear but a normal peak flow, which points to panic with overbreathing rather than asthma. A frightening childhood asthma crisis and an anxious mother (predisposing) made breathlessness terrifying; a friend''s death from asthma (precipitating) set off the panic cycle. Overuse of the reliever inhaler, which can cause tremor and a fast heart, avoidance of exercise and casualty visits for reassurance (perpetuating) keep her alarmed and unfit. A clear-speaking pulmonologist and her interest in medicines (protective) support joint care: a written asthma plan with peak flow checks so she can tell the two apart, and CBT for panic. The family move is a distractor.","hint":"A 23-year-old with asthma who rushes to casualty most weeks","tags":{"topic":"anxiety","difficulty":3,"objective":"Separate panic from a real medical illness that it mimics and worsens","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"anxiety","diagnosis":"Panic disorder with comorbid asthma"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-143', 'Ishita: the camera that stays off (social anxiety at a remote job)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-143-1","text":"Talented, with work clients praise","bucket":"protective"},{"id":"form-143-2","text":"Turns down chances to present her own work","bucket":"perpetuating"},{"id":"form-143-3","text":"Very self-critical about her appearance","bucket":"predisposing"},{"id":"form-143-4","text":"She works from a co-working space in Jaipur","bucket":"distractor"},{"id":"form-143-5","text":"Writes out every sentence before speaking","bucket":"perpetuating"},{"id":"form-143-6","text":"Quiet child, mocked by an uncle for her stammer which later faded","bucket":"predisposing"},{"id":"form-143-7","text":"Checks her face on screen throughout calls","bucket":"perpetuating"},{"id":"form-143-8","text":"A manager said in front of the team that her presentation was ''confusing''","bucket":"precipitating"},{"id":"form-143-9","text":"Keeps her camera off and messages instead of speaking","bucket":"presenting"},{"id":"form-143-10","text":"Intense fear of being judged on video calls and in meetings","bucket":"presenting"},{"id":"form-143-11","text":"A colleague who has offered to present with her","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ishita, 25, presents with social anxiety disorder: strong fear of judgement in meetings and video calls with avoidance. An early experience of mockery and harsh self-criticism (predisposing) built a fear of scrutiny; public criticism by her manager (precipitating) intensified it. Scripting, watching herself on screen and declining to present (perpetuating) increase self-focus and stop her learning that others judge her less harshly than she fears. Her talent and a supportive colleague (protective) are good foundations for CBT with video feedback and behavioural experiments. The co-working space is a distractor.","hint":"A 25-year-old designer who dreads every video call","tags":{"topic":"anxiety","difficulty":2,"objective":"Show how avoidance and safety behaviours maintain social anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Social anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-144', 'Mr Narang: the pension, the plot and the pills (late-life generalised anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-144-1","text":"Worries all day about money, his health and his plot of land for two years","bucket":"presenting"},{"id":"form-144-2","text":"Lifelong ''worrier'' according to his wife","bucket":"predisposing"},{"id":"form-144-3","text":"He collects old coins","bucket":"distractor"},{"id":"form-144-4","text":"Takes alprazolam from the chemist each night, now with daytime drowsiness","bucket":"perpetuating"},{"id":"form-144-5","text":"Enjoys his evening satsang group","bucket":"protective"},{"id":"form-144-6","text":"Has dropped his morning walk","bucket":"perpetuating"},{"id":"form-144-7","text":"Calls his lawyer and bank daily for reassurance","bucket":"perpetuating"},{"id":"form-144-8","text":"Restless, tense and sleeps poorly","bucket":"presenting"},{"id":"form-144-9","text":"Retirement, then a land dispute with a relative","bucket":"precipitating"},{"id":"form-144-10","text":"Lost savings in a bank collapse decades ago","bucket":"predisposing"},{"id":"form-144-11","text":"Wife and son who are patient with him","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Narang, 69, presents with generalised anxiety disorder in late life. A lifelong worrying style and a real past financial loss (predisposing) shaped his view that disaster is near; retirement and a land dispute (precipitating) gave the worry new targets. Over-the-counter benzodiazepine use, which raises fall and memory risks in older adults, daily reassurance calls and giving up exercise (perpetuating) keep him anxious and sedated. His family and satsang group (protective) can support a slow taper of the sedative, CBT adapted for older people and a return to walking. The coin collection is a distractor.","hint":"A 69-year-old retired bank officer on sleeping tablets","tags":{"topic":"anxiety","difficulty":2,"objective":"Formulate generalised anxiety in an older adult, including sedative risk","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"anxiety","diagnosis":"Generalised anxiety disorder in late life"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-145', 'Joseph: the MRI tunnel (claustrophobia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-145-1","text":"Panics in lifts, small rooms and the MRI scanner","bucket":"presenting"},{"id":"form-145-2","text":"Locked in a storeroom by older boys at boarding school","bucket":"predisposing"},{"id":"form-145-3","text":"Climbs ten floors to avoid the office lift","bucket":"perpetuating"},{"id":"form-145-4","text":"Motivated to sort out his back pain","bucket":"protective"},{"id":"form-145-5","text":"Stuck in a lift for forty minutes during a power cut last year","bucket":"precipitating"},{"id":"form-145-6","text":"Needs an MRI for back pain but has left the scanner twice","bucket":"presenting"},{"id":"form-145-7","text":"Radiographer willing to do a practice visit","bucket":"protective"},{"id":"form-145-8","text":"Generally anxious under pressure","bucket":"predisposing"},{"id":"form-145-9","text":"Keeps the car windows open even in heavy rain","bucket":"perpetuating"},{"id":"form-145-10","text":"He is a fan of old Malayalam films","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Joseph, 52, presents with a situational specific phobia of enclosed spaces that now blocks a needed MRI. A frightening school experience and a general tendency to anxiety (predisposing) laid the ground; being trapped in a lift during a power cut (precipitating) made the fear sharp and wide. Taking stairs and keeping windows open (perpetuating) prevent new learning. His wish to fix his back and a willing radiographer (protective) allow graded exposure, a practice visit and, if needed, an open or upright scanner. Films are a distractor.","hint":"A 52-year-old who ran out of the scanner twice","tags":{"topic":"anxiety","difficulty":2,"objective":"Sort a situational phobia that blocks medical care","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Specific phobia, situational type (enclosed spaces)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-146', 'Lata: when her husband travels (separation anxiety in an adult)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-146-1","text":"Insists he share his location all day","bucket":"perpetuating"},{"id":"form-146-2","text":"Calls him repeatedly and cannot sleep until he returns","bucket":"presenting"},{"id":"form-146-3","text":"Husband willing to come to sessions","bucket":"protective"},{"id":"form-146-4","text":"Husband answers every call to calm her","bucket":"perpetuating"},{"id":"form-146-5","text":"Clung to her mother as a child and missed school often","bucket":"predisposing"},{"id":"form-146-6","text":"Stays at her mother''s house when he is away","bucket":"perpetuating"},{"id":"form-146-7","text":"Husband''s new job needs him to tour two weeks a month","bucket":"precipitating"},{"id":"form-146-8","text":"Her father died suddenly in a bus accident when she was ten","bucket":"predisposing"},{"id":"form-146-9","text":"Severe fear that her husband will die in an accident whenever he travels","bucket":"presenting"},{"id":"form-146-10","text":"Good friendships at her workplace","bucket":"protective"},{"id":"form-146-11","text":"Her husband''s company sells farm tractors","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Lata, 36, presents with adult separation anxiety disorder: excessive fear that harm will come to her husband when apart, with repeated calls and poor sleep. Childhood clinginess and the sudden death of her father in an accident (predisposing) gave the fear deep roots; her husband''s new touring job (precipitating) brought it to the surface. Constant reassurance, location tracking and moving to her mother''s house (perpetuating) keep the fear going. A cooperative husband and good friendships (protective) support CBT that slowly reduces reassurance and lets her face separations. The tractor company is a distractor.","hint":"A 36-year-old who calls her husband twenty times a day on his tours","tags":{"topic":"anxiety","difficulty":2,"objective":"Recognise that separation anxiety can begin or persist in adulthood","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"anxiety","diagnosis":"Separation anxiety disorder, adult"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-147', 'Tanya: afraid of being sick (fear of vomiting, not an eating disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-147-1","text":"Eats only a few ''safe'' plain foods and has lost 4 kg","bucket":"presenting"},{"id":"form-147-2","text":"Anxious child who hated feeling unwell","bucket":"predisposing"},{"id":"form-147-3","text":"She thinks she looks fat even though she is thin","bucket":"distractor"},{"id":"form-147-4","text":"Mother has a strong disgust of illness","bucket":"predisposing"},{"id":"form-147-5","text":"Saw a classmate vomit in the school bus after a stomach infection","bucket":"precipitating"},{"id":"form-147-6","text":"Checks the expiry date of every food and smells it many times","bucket":"perpetuating"},{"id":"form-147-7","text":"Says she is terrified of throwing up, not of gaining weight","bucket":"presenting"},{"id":"form-147-8","text":"Open with her doctor about her fears","bucket":"protective"},{"id":"form-147-9","text":"Likes her body and wants to be strong for basketball","bucket":"protective"},{"id":"form-147-10","text":"Her school is in Gangtok","bucket":"distractor"},{"id":"form-147-11","text":"Avoids eating outside the home and skips birthday parties","bucket":"perpetuating"},{"id":"form-147-12","text":"Mother cooks separate ''safe'' meals","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Tanya, 14, presents with a specific phobia of vomiting with food restriction and weight loss. An anxious, illness-averse temperament and a disgust-sensitive mother (predisposing) set the stage; seeing a classmate vomit (precipitating) began the fear. Food checking, avoiding eating out and separate safe meals at home (perpetuating) keep the fear and the restriction going. Her positive body image and openness (protective) are key differences from anorexia. The card that she thinks she looks fat is left out because it is not true for her: in anorexia the fear is of weight gain with a distorted body image, while in her case the fear is of vomiting. Her school town is a distractor. Weight and physical health still need monitoring while she does graded exposure work.","hint":"A 14-year-old who eats only plain rice and has lost weight","tags":{"topic":"anxiety","difficulty":4,"objective":"Tell a phobia of vomiting apart from anorexia nervosa","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"anxiety","diagnosis":"Specific phobia of vomiting"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-148', 'Reshma: waiting for the next fit (generalised anxiety in a carer)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-148-1","text":"Constant worry, tension and poor sleep for eighteen months","bucket":"presenting"},{"id":"form-148-2","text":"She runs a beauty parlour from her home","bucket":"distractor"},{"id":"form-148-3","text":"Son''s first seizure at school, when he fell and cut his head","bucket":"precipitating"},{"id":"form-148-4","text":"Husband works away and she manages alone","bucket":"perpetuating"},{"id":"form-148-5","text":"Her own sister died young in an accident","bucket":"predisposing"},{"id":"form-148-6","text":"Searches online about sudden death in epilepsy most nights","bucket":"perpetuating"},{"id":"form-148-7","text":"A parents'' group at the neurology clinic","bucket":"protective"},{"id":"form-148-8","text":"Sleeps in her son''s room and will not let him go on school trips","bucket":"perpetuating"},{"id":"form-148-9","text":"Anxious temperament since college","bucket":"predisposing"},{"id":"form-148-10","text":"Wakes several times a night to check her son is breathing","bucket":"presenting"},{"id":"form-148-11","text":"Son''s seizures are now well controlled on medicine","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Reshma, 34, presents with generalised anxiety disorder centred on her son''s epilepsy, with constant worry, tension and night-time checking. An anxious temperament and an early family loss (predisposing) made her alert to danger; her son''s first seizure and injury (precipitating) began the worry. Sleeping in his room, restricting his activities, nightly online searching and coping alone (perpetuating) keep her anxious and may also limit her son. Good seizure control now and a parents'' group (protective) support a plan of seizure education with the neurologist, gradual reduction of checking and shared care with her husband. The parlour is a distractor.","hint":"A 34-year-old mother of a boy with epilepsy in Bhopal","tags":{"topic":"anxiety","difficulty":3,"objective":"Show how caring for a sick child can drive and maintain anxiety","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"anxiety","diagnosis":"Generalised anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-149', 'Gopal: the Hindi-medium boy in an English classroom (social anxiety with language shame)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-149-1","text":"Teased at home as ''too quiet''","bucket":"predisposing"},{"id":"form-149-2","text":"A senior from his district who mentors him","bucket":"protective"},{"id":"form-149-3","text":"Has not spoken once in four months of college","bucket":"presenting"},{"id":"form-149-4","text":"Sits at the back and leaves before the tutorial ends","bucket":"perpetuating"},{"id":"form-149-5","text":"Believes everyone sees him as a ''village boy''","bucket":"perpetuating"},{"id":"form-149-6","text":"Very strong in written assignments","bucket":"protective"},{"id":"form-149-7","text":"Fear of speaking in class or tutorials, with sweating and a shaking voice","bucket":"presenting"},{"id":"form-149-8","text":"First in his family to reach college","bucket":"predisposing"},{"id":"form-149-9","text":"His college has a large banyan tree in the lawn","bucket":"distractor"},{"id":"form-149-10","text":"Classmates laughed at his English pronunciation on the first day","bucket":"precipitating"},{"id":"form-149-11","text":"Avoids the college library where students talk in English","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Gopal, 18, presents with social anxiety disorder: intense fear of speaking in English-medium classes with sweating and a shaking voice. Being the first in his family at college and being labelled too quiet (predisposing) left him unsure of his place; classmates laughing at his pronunciation (precipitating) made the fear specific. Sitting at the back, leaving early, believing he is seen as inferior and avoiding the library (perpetuating) block disconfirming experiences. His written skill and a mentor from home (protective) are good resources. The plan should combine CBT for social anxiety with practical language support, while recognising that class and language prejudice are real, not imagined. The banyan tree is a distractor.","hint":"A first-year BA student from a village school in Delhi","tags":{"topic":"anxiety","difficulty":3,"objective":"Include language, class and culture in a social anxiety formulation","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"anxiety","diagnosis":"Social anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-150', 'Tenzin: the first attack after a joint in Manali (panic disorder after cannabis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-150-1","text":"No cannabis for six months but attacks continue","bucket":"presenting"},{"id":"form-150-2","text":"Elder sister has panic attacks","bucket":"predisposing"},{"id":"form-150-3","text":"Carries a pill strip of propranolol he never takes but checks often","bucket":"perpetuating"},{"id":"form-150-4","text":"Fears he has ''damaged his brain'' and searches for proof online","bucket":"perpetuating"},{"id":"form-150-5","text":"Avoids exercise because a fast heart feels like an attack","bucket":"perpetuating"},{"id":"form-150-6","text":"Stopped cannabis on his own","bucket":"protective"},{"id":"form-150-7","text":"Good friends at his hotel management college","bucket":"protective"},{"id":"form-150-8","text":"First attack after smoking strong cannabis on a trip to Manali","bucket":"precipitating"},{"id":"form-150-9","text":"Sudden waves of fear, chest tightness and a feeling of unreality, four times a week","bucket":"presenting"},{"id":"form-150-10","text":"Childhood asthma that frightened him","bucket":"predisposing"},{"id":"form-150-11","text":"He speaks Tibetan, Hindi and English","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Tenzin, 22, presents with panic disorder: frequent attacks with chest tightness and unreality that continue six months after his last cannabis. Childhood asthma and a sister with panic (predisposing) raised his sensitivity to body sensations; a frightening reaction to strong cannabis (precipitating) set off the first attack. Because attacks continue without the drug, this is now panic disorder rather than a substance-induced state. The belief that his brain is damaged, avoidance of exercise and carrying a pill as a safety signal (perpetuating) keep the fear of sensations alive. Stopping cannabis and good friends (protective) are strengths for CBT with exposure to body sensations. His languages are a distractor.","hint":"A 22-year-old whose attacks continued long after he stopped smoking","tags":{"topic":"anxiety","difficulty":3,"objective":"Show how a substance can start panic that then runs on its own","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"anxiety","diagnosis":"Panic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-151', 'Neelam: shaky, sweaty and losing weight (an overactive thyroid behind the anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-151-1","text":"Symptoms began a few months after the birth of her second child","bucket":"precipitating"},{"id":"form-151-2","text":"Mother has thyroid disease","bucket":"predisposing"},{"id":"form-151-3","text":"Lost 6 kg while eating more, and cannot tolerate heat","bucket":"presenting"},{"id":"form-151-4","text":"Drinks strong tea all day to fight tiredness","bucket":"perpetuating"},{"id":"form-151-5","text":"Keen to find a real answer","bucket":"protective"},{"id":"form-151-6","text":"Told it is ''just stress'' at two clinics","bucket":"perpetuating"},{"id":"form-151-7","text":"No history of anxiety before this year","bucket":"predisposing"},{"id":"form-151-8","text":"Husband who pushed for another opinion","bucket":"protective"},{"id":"form-151-9","text":"Her baby was born in a government hospital","bucket":"distractor"},{"id":"form-151-10","text":"Always gets nervous before family functions, as most people do","bucket":"distractor"},{"id":"form-151-11","text":"Restless, irritable and shaky for three months with a fast pulse even at rest","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Neelam, 31, presents with anxiety symptoms that point strongly to an overactive thyroid. A family history of thyroid disease and no earlier anxiety (predisposing) are clues; onset in the months after childbirth (precipitating) fits postpartum thyroid inflammation, which can cause a high thyroid phase. Weight loss despite good appetite, heat intolerance and a resting fast pulse are not typical of a primary anxiety disorder. Being told it is stress and drinking strong tea (perpetuating) have delayed testing and worsened her shakiness. Her husband''s persistence (protective) helps. Thyroid tests come first; anxiety treatment alone would miss the cause. The card about normal nerves before functions is a tempting look-alike, but ordinary social nerves are not a vulnerability. Her hospital of birth is a distractor.","hint":"A 31-year-old referred for ''stress'' who cannot bear the heat","tags":{"topic":"anxiety","difficulty":4,"objective":"Tell a medical cause of anxiety apart from an anxiety disorder","exams":["md-psychiatry","mcp-entrance"],"module":"anxiety","diagnosis":"Anxiety due to hyperthyroidism"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-152', 'Yash: six energy drinks and a racing heart (caffeine-induced anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-152-1","text":"He plays in an online league from Indore","bucket":"distractor"},{"id":"form-152-2","text":"Drinks more to beat the tiredness from poor sleep","bucket":"perpetuating"},{"id":"form-152-3","text":"An uncle has panic disorder","bucket":"distractor"},{"id":"form-152-4","text":"Symptoms eased during a weekend trip with no energy drinks","bucket":"protective"},{"id":"form-152-5","text":"No anxiety problems before this term","bucket":"predisposing"},{"id":"form-152-6","text":"Takes pre-workout powder before the gym","bucket":"perpetuating"},{"id":"form-152-7","text":"Willing to cut down","bucket":"protective"},{"id":"form-152-8","text":"Sensitive to coffee since school","bucket":"predisposing"},{"id":"form-152-9","text":"Started drinking five to six energy drinks a day during semester exams and night gaming","bucket":"precipitating"},{"id":"form-152-10","text":"Jittery, restless, with a racing heart and sudden fear in the evenings for a month","bucket":"presenting"},{"id":"form-152-11","text":"Poor sleep and trips to the toilet many times a night","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Yash, 20, presents with caffeine-induced anxiety disorder: jitteriness, palpitations, sudden fear, insomnia and frequent urination after a big rise in caffeine from energy drinks and pre-workout powder. Natural sensitivity to caffeine (predisposing) and a sharp increase during exams and gaming (precipitating) explain the timing. Drinking more to beat tiredness from poor sleep (perpetuating) keeps the loop going. The clear easing on a caffeine-free weekend (protective) is strong evidence that the substance is the cause. The card about an uncle with panic disorder is tempting, but a family history alone does not explain symptoms that track caffeine so closely, so it is not a key factor here. His gaming league is a distractor. A slow taper avoids caffeine withdrawal headaches.","hint":"A 20-year-old gamer and student with ''panic attacks''","tags":{"topic":"anxiety","difficulty":4,"objective":"Tell a substance-induced anxiety apart from panic disorder","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"substance","diagnosis":"Caffeine-induced anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-153', 'Bhavna: the knife in the kitchen drawer (harm obsessions, not generalised worry)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-153-1","text":"Has hidden all knives and will not be alone with the baby","bucket":"presenting"},{"id":"form-153-2","text":"Avoids bathing the baby alone","bucket":"perpetuating"},{"id":"form-153-3","text":"Her baby was born in the month of Shravan","bucket":"distractor"},{"id":"form-153-4","text":"Tries hard to push the thoughts away, which makes them return more","bucket":"perpetuating"},{"id":"form-153-5","text":"High sense of moral responsibility","bucket":"predisposing"},{"id":"form-153-6","text":"Worries about many everyday things, like bills and the weather","bucket":"distractor"},{"id":"form-153-7","text":"Checking habits in her teens around locks","bucket":"predisposing"},{"id":"form-153-8","text":"Loves her baby and is caring and gentle","bucket":"protective"},{"id":"form-153-9","text":"Husband who is supportive and patient","bucket":"protective"},{"id":"form-153-10","text":"Sudden, unwanted images of stabbing her baby that horrify her","bucket":"presenting"},{"id":"form-153-11","text":"Asks her husband many times a day if she is ''a bad person''","bucket":"perpetuating"},{"id":"form-153-12","text":"Birth of her first baby three months ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Bhavna, 29, presents with obsessive-compulsive disorder with harm obsessions after childbirth: unwanted, horrifying images of hurting her baby, with avoidance and reassurance seeking. Earlier checking habits and an inflated sense of responsibility (predisposing) set the stage; the birth of her baby (precipitating) gave the obsessions their target. Avoidance, reassurance seeking and thought suppression (perpetuating) make the thoughts feel more dangerous and more frequent. Her obvious love for the baby and a patient husband (protective) are hopeful, and the horror she feels about the thoughts is typical of OCD and does not mean she is a risk. The card about worrying about bills and weather is a tempting look-alike for generalised anxiety, but it does not fit: her thoughts are sudden, image-based and against her values, not ongoing everyday worries. The month of birth is a distractor.","hint":"A 29-year-old new mother afraid of her own thoughts","tags":{"topic":"ocd","difficulty":4,"objective":"Tell intrusive harm obsessions apart from generalised worry and from real risk","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with harm obsessions"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-154', 'Aman: alone at lunch since school (autism, not social anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-154-1","text":"Very upset by changes in routine and loud office noise","bucket":"presenting"},{"id":"form-154-2","text":"He travels to work by metro","bucket":"distractor"},{"id":"form-154-3","text":"Spoke late and lined up his toy cars as a child","bucket":"predisposing"},{"id":"form-154-4","text":"Excellent coder valued by his team lead","bucket":"protective"},{"id":"form-154-5","text":"Masks by copying colleagues'' phrases, which exhausts him","bucket":"perpetuating"},{"id":"form-154-6","text":"Fears being judged and blushes when speaking","bucket":"distractor"},{"id":"form-154-7","text":"Office lights and noise overwhelm him each afternoon","bucket":"perpetuating"},{"id":"form-154-8","text":"Finds conversation confusing and does not know when to speak or stop","bucket":"presenting"},{"id":"form-154-9","text":"Parents who accept him as he is","bucket":"protective"},{"id":"form-154-10","text":"Moved to an open-plan office with team lunches every day","bucket":"precipitating"},{"id":"form-154-11","text":"Deep interest in train timetables since age six","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aman, 26, presents with features of autism without intellectual impairment, first noticed in adulthood. Late speech, lining up toys and an intense lifelong interest (predisposing) show the condition was present from early childhood; the move to an open-plan office with daily team lunches (precipitating) exposed his difficulties. Constant masking and sensory overload (perpetuating) cause exhaustion. His coding skill and accepting parents (protective) support workplace adjustments and autism-informed support. The card about fearing judgement and blushing is a tempting look-alike for social anxiety, but it does not describe him: his difficulty is in reading social rules and coping with sensory input, not fear of being evaluated. His commute is a distractor. Social anxiety can occur alongside autism, so it is still worth asking about.","hint":"A 26-year-old software developer referred for social anxiety","tags":{"topic":"neurodevelopmental","difficulty":4,"objective":"Tell autism without intellectual disability apart from social anxiety in an adult","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"child","diagnosis":"Autism spectrum disorder without intellectual impairment"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-155', 'Mr Saini: anxious since the tablets ran out (benzodiazepine withdrawal)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-155-1","text":"Believes he ''cannot sleep without medicine''","bucket":"perpetuating"},{"id":"form-155-2","text":"Took clonazepam every night for nine years after a short period of insomnia","bucket":"predisposing"},{"id":"form-155-3","text":"Chemist stopped supplying the tablets without a prescription last week","bucket":"precipitating"},{"id":"form-155-4","text":"Drinking whisky to replace the tablets","bucket":"perpetuating"},{"id":"form-155-5","text":"Had a fight with his neighbour over parking two years ago","bucket":"distractor"},{"id":"form-155-6","text":"Agreed to see a doctor rather than search other chemists","bucket":"protective"},{"id":"form-155-7","text":"He owns a sweet shop","bucket":"distractor"},{"id":"form-155-8","text":"Mild worrying nature","bucket":"predisposing"},{"id":"form-155-9","text":"Daughter who is a pharmacist","bucket":"protective"},{"id":"form-155-10","text":"Feels his heart racing and noises seem too loud","bucket":"presenting"},{"id":"form-155-11","text":"Shaky, sweating, sleepless and very anxious for four days","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Saini, 58, presents with sedative withdrawal: tremor, sweating, insomnia, anxiety, palpitations and sensitivity to sound four days after stopping long-term clonazepam. Nine years of nightly use (predisposing) led to physical dependence; the sudden loss of supply (precipitating) caused withdrawal. Using whisky as a substitute and the belief he cannot sleep without medicine (perpetuating) add risk, since abrupt benzodiazepine withdrawal can cause seizures. His willingness to see a doctor and a pharmacist daughter (protective) allow a safe plan: restart a benzodiazepine under supervision and taper slowly, with CBT for insomnia. The old parking fight is a tempting stressor but it is long past and unrelated to the timing. The sweet shop is a distractor.","hint":"A 58-year-old whose chemist stopped selling without a prescription","tags":{"topic":"substance","difficulty":4,"objective":"Tell withdrawal anxiety apart from a new anxiety disorder","exams":["md-psychiatry","mcp-entrance"],"module":"substance","diagnosis":"Sedative withdrawal"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-156', 'Mrs Malhotra: the fraud call and the empty house (anxiety, panic, low mood and alcohol)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-156-1","text":"Checks her bank app dozens of times a day","bucket":"perpetuating"},{"id":"form-156-2","text":"Grew up in a family that lost everything in Partition, with constant talk of danger","bucket":"predisposing"},{"id":"form-156-3","text":"Low mood, poor sleep and drinking two large pegs of whisky most nights","bucket":"presenting"},{"id":"form-156-4","text":"Lost twelve lakh rupees to a phone fraud posing as her bank","bucket":"precipitating"},{"id":"form-156-5","text":"Long record of running the business well","bucket":"protective"},{"id":"form-156-6","text":"Stopped going to the office and relies on a manager she does not trust","bucket":"perpetuating"},{"id":"form-156-7","text":"Refuses to tell her sons so they will not think she is foolish","bucket":"perpetuating"},{"id":"form-156-8","text":"Her factory is in Ludhiana''s industrial area","bucket":"distractor"},{"id":"form-156-9","text":"Friend from her women''s club who visits weekly","bucket":"protective"},{"id":"form-156-10","text":"Drinks to calm the panic, then wakes anxious at 4 am","bucket":"perpetuating"},{"id":"form-156-11","text":"She has a pet Pomeranian","bucket":"distractor"},{"id":"form-156-12","text":"Constant worry and frequent panic attacks for a year","bucket":"presenting"},{"id":"form-156-13","text":"Widowed suddenly three years ago","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Malhotra, 61, presents with generalised anxiety with panic attacks, depressive symptoms and harmful drinking. A sudden widowhood and a family history steeped in loss and danger (predisposing) shaped her expectation of disaster; the phone fraud (precipitating) confirmed her worst fears. Several loops feed each other (perpetuating): bank checking fuels worry, alcohol settles panic for an hour then causes early waking and rebound anxiety, shame keeps her from her sons, and staying away from work leaves her feeling out of control. In CBT terms, each safety strategy blocks recovery; from a psychodynamic angle, the fraud reopens an old family story of sudden ruin. Her business skill and a loyal friend (protective) can anchor a plan: reduce alcohol safely, treat anxiety and mood, gradually return to work, and help her share the loss with her sons. The factory location and pet are distractors.","hint":"A 61-year-old widow who runs her late husband''s garment business","tags":{"topic":"anxiety","difficulty":5,"objective":"Build a full formulation where several problems feed each other","exams":["md-psychiatry","mcp-entrance"],"module":"anxiety","diagnosis":"Generalised anxiety disorder with panic attacks, depressive symptoms and harmful alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-157', 'Zara: the tummy aches and the father in hospital (childhood anxiety in a family under stress)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-157-1","text":"Her school follows the ICSE board","bucket":"distractor"},{"id":"form-157-2","text":"Allowed to stay home when she has pain, so she misses school often","bucket":"perpetuating"},{"id":"form-157-3","text":"Mother''s own anxiety is high and she checks Zara''s temperature often","bucket":"perpetuating"},{"id":"form-157-4","text":"Overhears adults'' worried talk but nobody explains what is happening","bucket":"perpetuating"},{"id":"form-157-5","text":"A school counsellor and a best friend who visit","bucket":"protective"},{"id":"form-157-6","text":"Worries constantly about her father dying and about school marks","bucket":"presenting"},{"id":"form-157-7","text":"Takes on care of her younger brother and skips play","bucket":"perpetuating"},{"id":"form-157-8","text":"Father is responding well to treatment","bucket":"protective"},{"id":"form-157-9","text":"Father diagnosed with lymphoma and started chemotherapy","bucket":"precipitating"},{"id":"form-157-10","text":"She is learning Kathak","bucket":"distractor"},{"id":"form-157-11","text":"Daily stomach aches and headaches with no medical cause for four months","bucket":"presenting"},{"id":"form-157-12","text":"Mother has had panic attacks for years","bucket":"predisposing"},{"id":"form-157-13","text":"Anxious and perfectionistic since early childhood","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Zara, 12, presents with generalised anxiety with separation fears, shown mainly through daily stomach aches and headaches. An anxious, perfectionistic temperament and a mother with panic (predisposing) gave her a vulnerability, partly genetic and partly learned. Her father''s cancer (precipitating) brought real fear into the home. From a family systems view, silence about the illness lets her imagine the worst, and she has taken on an adult role caring for her brother; from a CBT view, staying home when in pain and her mother''s checking (perpetuating) reward the symptoms and confirm danger. Her father''s good response and supportive counsellor and friend (protective) are strong assets. The plan combines honest, age-appropriate talk about the illness, a school return plan, CBT for anxiety, and support for her mother''s own anxiety. Kathak and the school board are distractors.","hint":"A 12-year-old missing school while her father has cancer treatment","tags":{"topic":"anxiety","difficulty":5,"objective":"Use family systems and CBT views together in a child''s formulation","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"child","diagnosis":"Generalised anxiety disorder in a child with separation anxiety features"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-158', 'Imtiaz: the attacks began when he moved out (panic, psychodynamic view)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-158-1","text":"Goes back to his parents'' home most evenings after an attack","bucket":"perpetuating"},{"id":"form-158-2","text":"Separation anxiety as a child","bucket":"predisposing"},{"id":"form-158-3","text":"Feels safe only when he visits his father''s house","bucket":"presenting"},{"id":"form-158-4","text":"Panic attacks with chest pain and fear of collapse, three or four a week for two months","bucket":"presenting"},{"id":"form-158-5","text":"Feels guilty for ''leaving'' his mother and avoids talking about it","bucket":"perpetuating"},{"id":"form-158-6","text":"Interested in understanding why the attacks started","bucket":"protective"},{"id":"form-158-7","text":"Checks his pulse whenever he is alone","bucket":"perpetuating"},{"id":"form-158-8","text":"Moved with his new wife to a flat across the city","bucket":"precipitating"},{"id":"form-158-9","text":"Only son of a strict, controlling father and a fragile mother who needed him close","bucket":"predisposing"},{"id":"form-158-10","text":"Wife who is warm and patient","bucket":"protective"},{"id":"form-158-11","text":"The new flat is on the sixth floor","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Imtiaz, 30, presents with panic disorder that began when he moved out of his family home. A controlling father, a mother who kept him close and childhood separation anxiety (predisposing) made independence feel dangerous; the move to his own home (precipitating) set off the attacks. From a psychodynamic angle, the attacks may express an unspoken conflict between wanting an adult life with his wife and guilt about leaving his mother; returning home after each attack soothes the guilt but keeps him from separating. Unspoken guilt and pulse checking (perpetuating) maintain the cycle, and CBT would add work on catastrophic readings of chest pain. A warm wife and his curiosity (protective) suit a combined approach. The floor number is a distractor.","hint":"A 30-year-old who left his father''s house to live with his new wife","tags":{"topic":"anxiety","difficulty":3,"objective":"Add a psychodynamic angle on separation and autonomy to a panic formulation","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"psychodynamics","diagnosis":"Panic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-159', 'Aparna: the thesis in Edinburgh (panic, perfectionism and poor sleep in a research student)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-159-1","text":"Close friends in an Indian students'' group","bucket":"protective"},{"id":"form-159-2","text":"Raised to believe anything less than the best is failure","bucket":"predisposing"},{"id":"form-159-3","text":"University counselling service with an open slot","bucket":"protective"},{"id":"form-159-4","text":"Works through the night, then lies in bed worrying","bucket":"perpetuating"},{"id":"form-159-5","text":"Skips meals so she ''does not waste time''","bucket":"perpetuating"},{"id":"form-159-6","text":"Rewrites the same paragraph for hours","bucket":"perpetuating"},{"id":"form-159-7","text":"Supervisor returned her thesis chapter with heavy criticism two months before her funding ends","bucket":"precipitating"},{"id":"form-159-8","text":"Her flat is near a famous castle","bucket":"distractor"},{"id":"form-159-9","text":"Avoids her supervisor''s emails until late at night","bucket":"perpetuating"},{"id":"form-159-10","text":"She drinks masala chai made with oat milk","bucket":"distractor"},{"id":"form-159-11","text":"Panic attacks at her desk and at night, several a week","bucket":"presenting"},{"id":"form-159-12","text":"Sleeps four hours, skips meals and has lost weight","bucket":"presenting"},{"id":"form-159-13","text":"Generalised worry since her school years in Chennai","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aparna, 27, presents with panic disorder alongside clinical perfectionism, insomnia and weight loss in the final months of a PhD. A family code that only the best counts and long-standing worry (predisposing) built the base; harsh feedback near the end of her funding, with her visa at stake (precipitating), set off the attacks. Endless rewriting, night working, skipped meals and avoiding emails (perpetuating) raise arousal and make each attack more likely, while poor sleep and hunger add their own physical stress. Weight loss is a reason to ask gently about eating. A counselling slot and a supportive student group (protective) are ready resources. CBT for panic and perfectionism, sleep and meal routines, and a frank talk with her supervisor and the university about deadlines are the next steps. The castle and the chai are distractors.","hint":"A 27-year-old Indian PhD student whose visa depends on finishing","tags":{"topic":"anxiety","difficulty":5,"objective":"Pull perfectionism, sleep, eating and visa stress into one formulation","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"anxiety","diagnosis":"Panic disorder with clinical perfectionism and insomnia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-160', 'Mr Malik: the shock box in his chest (anxiety after a heart attack)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-160-1","text":"Heart attack last year, then one painful shock from his implanted defibrillator","bucket":"precipitating"},{"id":"form-160-2","text":"Anxious temperament all his life","bucket":"predisposing"},{"id":"form-160-3","text":"Low fitness now makes him breathless, which he reads as heart failure","bucket":"perpetuating"},{"id":"form-160-4","text":"His device was made in Ireland","bucket":"distractor"},{"id":"form-160-5","text":"Constant fear of another heart attack and of the device shocking him","bucket":"presenting"},{"id":"form-160-6","text":"He was a cloth merchant in Old Delhi","bucket":"distractor"},{"id":"form-160-7","text":"Wife will not let him lift anything or climb stairs","bucket":"perpetuating"},{"id":"form-160-8","text":"Has stopped walking, sex and leaving the house for six months","bucket":"presenting"},{"id":"form-160-9","text":"Checks his pulse and blood pressure many times a day","bucket":"perpetuating"},{"id":"form-160-10","text":"Father died of a heart attack at 60","bucket":"predisposing"},{"id":"form-160-11","text":"Close to his grandchildren and wants to travel to Jeddah for Umrah","bucket":"protective"},{"id":"form-160-12","text":"Cardiologist reports good heart function and offers cardiac rehabilitation","bucket":"protective"},{"id":"form-160-13","text":"Reads every heart rhythm on his smartwatch as a warning","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Malik, 63, presents with an anxiety disorder with marked avoidance after a heart attack and a shock from his implanted defibrillator. An anxious nature and his father''s early cardiac death (predisposing) shaped his fear; the heart attack and the painful shock (precipitating) were real and frightening events, so this is fear grown far beyond current risk, not imagined illness. Body checking, his wife''s protective limits, smartwatch monitoring and loss of fitness that causes breathlessness (perpetuating) keep the fear alive and even make him weaker. Good heart function, cardiac rehabilitation and strong life goals such as Umrah (protective) allow a plan that combines supervised exercise with CBT for health-focused anxiety, involving his wife as a coach. His trade and the device maker are distractors.","hint":"A 63-year-old with an implanted defibrillator who has stopped walking","tags":{"topic":"anxiety","difficulty":5,"objective":"Formulate anxiety when the body really is at risk","exams":["md-psychiatry","mcp-entrance"],"module":"anxiety","diagnosis":"Anxiety disorder with avoidance after cardiac events"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-161', 'Shruti: the lizard on the bathroom wall (animal phobia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-161-1","text":"Screams and runs at the sight of a house lizard","bucket":"presenting"},{"id":"form-161-2","text":"Wants to manage on her own when she starts work","bucket":"protective"},{"id":"form-161-3","text":"Avoids the hostel bathroom at night","bucket":"perpetuating"},{"id":"form-161-4","text":"Roommate who is patient and helpful","bucket":"protective"},{"id":"form-161-5","text":"Sleeps with the lights on and keeps a broom by the bed","bucket":"perpetuating"},{"id":"form-161-6","text":"Was told as a child that a lizard falling on you is bad luck","bucket":"predisposing"},{"id":"form-161-7","text":"A lizard fell on her shoulder in her hostel room last month","bucket":"precipitating"},{"id":"form-161-8","text":"She studies commerce at a Lucknow college","bucket":"distractor"},{"id":"form-161-9","text":"Mother is also terrified of lizards","bucket":"predisposing"},{"id":"form-161-10","text":"Makes her roommate check the bathroom before she enters","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shruti, 22, presents with a specific phobia of lizards: intense fear and avoidance with frequent checking by others. A mother with the same fear and superstitions learned in childhood (predisposing) built the phobia through observation and stories; a lizard falling on her (precipitating) made it worse. Lights on, the broom and bathroom avoidance (perpetuating) keep the fear going. A helpful roommate and her wish for independence (protective) support graded exposure, starting with pictures and moving to being in a room with a lizard. Her course and college are distractors.","hint":"A 22-year-old who will not enter rooms until checked","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort a common specific phobia into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Specific phobia, animal type (lizards)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-162', 'Mr Desai: the flight to Toronto (fear of flying)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-162-1","text":"He runs a diamond polishing unit in Surat","bucket":"distractor"},{"id":"form-162-2","text":"Dislikes situations he cannot control","bucket":"predisposing"},{"id":"form-162-3","text":"Wife who flies often and is calm","bucket":"protective"},{"id":"form-162-4","text":"Strong wish to attend his daughter''s wedding in four months","bucket":"protective"},{"id":"form-162-5","text":"Has cancelled two booked trips","bucket":"presenting"},{"id":"form-162-6","text":"Severe fear of flying with racing heart and sweating at the thought of a plane","bucket":"presenting"},{"id":"form-162-7","text":"Anxious traveller since his youth","bucket":"predisposing"},{"id":"form-162-8","text":"Watches air crash news and documentaries","bucket":"perpetuating"},{"id":"form-162-9","text":"Has avoided all flights since then, travelling only by train","bucket":"perpetuating"},{"id":"form-162-10","text":"A very bumpy flight with an emergency landing ten years ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Desai, 57, presents with a specific phobia of flying with anticipatory anxiety and cancelled trips. An anxious travelling style and dislike of not being in control (predisposing) made him vulnerable; a frightening emergency landing (precipitating) started the fear. Ten years of avoidance and watching crash news (perpetuating) have kept it strong. His wish to attend his daughter''s wedding and a calm wife (protective) give a clear goal for CBT with graded exposure, from videos and airport visits to a short domestic flight before the long one. The diamond unit is a distractor.","hint":"A 57-year-old who must fly to his daughter''s wedding","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort a situational phobia with a clear deadline into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Specific phobia, situational type (flying)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-163', 'Vinay: the HIV test he repeats every month (illness anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-163-1","text":"Strict upbringing in which sex was shameful","bucket":"predisposing"},{"id":"form-163-2","text":"Fiancée who wants to understand","bucket":"protective"},{"id":"form-163-3","text":"Has avoided his fiancée physically for a year","bucket":"perpetuating"},{"id":"form-163-4","text":"He works in a pharmaceutical sales team","bucket":"distractor"},{"id":"form-163-5","text":"A counsellor at the testing centre who knows him","bucket":"protective"},{"id":"form-163-6","text":"Checks his lymph nodes and tongue daily","bucket":"perpetuating"},{"id":"form-163-7","text":"Searches online about early HIV signs late at night","bucket":"perpetuating"},{"id":"form-163-8","text":"Has had eight negative tests and feels calm only for a day after each","bucket":"presenting"},{"id":"form-163-9","text":"Convinced he has HIV after one encounter two years ago","bucket":"presenting"},{"id":"form-163-10","text":"Watched an uncle die of AIDS when he was a teenager","bucket":"predisposing"},{"id":"form-163-11","text":"Unprotected encounter on a work trip, followed by guilt","bucket":"precipitating"},{"id":"form-163-12","text":"Tests at a new lab every month","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vinay, 30, presents with illness anxiety disorder: two years of conviction that he has HIV despite eight negative tests, with only brief relief. A shame-laden view of sex and a frightening uncle''s death (predisposing) made HIV his worst fear; an unprotected encounter followed by guilt (precipitating) began it. Repeated testing, body checking, night-time searching and avoidance of intimacy (perpetuating) give short relief but strengthen the doubt. Once the window period is well past, more tests add no information, which is a key teaching point. A trusted counsellor and an understanding fiancée (protective) support CBT that limits checking and testing and works on guilt. His job is a distractor.","hint":"A 30-year-old whose eight negative tests do not settle him","tags":{"topic":"somatic","difficulty":3,"objective":"Show how repeated testing maintains illness anxiety","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"more-disorders","diagnosis":"Illness anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-164', 'Sujata: attacks only when she is low (panic attacks within depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-164-1","text":"One depressive episode in her twenties","bucket":"predisposing"},{"id":"form-164-2","text":"She lives in Thane","bucket":"distractor"},{"id":"form-164-3","text":"Has stopped her work as a tuition teacher","bucket":"perpetuating"},{"id":"form-164-4","text":"Lies awake ruminating, which often ends in an attack","bucket":"perpetuating"},{"id":"form-164-5","text":"Discovered her husband''s affair","bucket":"precipitating"},{"id":"form-164-6","text":"Sister she can confide in","bucket":"protective"},{"id":"form-164-7","text":"Low mood, poor sleep and loss of interest for two months","bucket":"presenting"},{"id":"form-164-8","text":"Tends to keep problems to herself","bucket":"predisposing"},{"id":"form-164-9","text":"Good response to treatment for her earlier depression","bucket":"protective"},{"id":"form-164-10","text":"Panic attacks twice a week, only since the low mood began","bucket":"presenting"},{"id":"form-164-11","text":"Had one panic attack during a bad flu five years ago and none until now","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sujata, 37, presents with a moderate depressive episode with panic attacks. The attacks began only with the low mood and come out of rumination at night, so they are best seen as part of the depression, not a separate panic disorder; the specifier ''with panic attacks'' captures this. A past depressive episode and a private coping style (predisposing) set the stage; discovering the affair (precipitating) began the episode. Night rumination and giving up her work (perpetuating) keep both mood and panic going. Her sister and past response to treatment (protective) are hopeful. The card about one attack during flu is tempting, but a single attack years ago during illness is common and does not make panic disorder. Her home town is a distractor. Treating the depression should reduce the attacks.","hint":"A 37-year-old referred for panic disorder","tags":{"topic":"anxiety","difficulty":4,"objective":"Tell panic attacks inside a depressive episode apart from panic disorder","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"depression","diagnosis":"Moderate depressive episode with panic attacks"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-165', 'Kritika: the patches and the college photos (social anxiety with vitiligo)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-165-1","text":"Vitiligo patches on her face and hands since age twelve","bucket":"predisposing"},{"id":"form-165-2","text":"Relatives often suggested remedies and asked if it was ''catching''","bucket":"predisposing"},{"id":"form-165-3","text":"Covers her hands with long sleeves even in summer heat","bucket":"perpetuating"},{"id":"form-165-4","text":"Believes no one will want to marry her","bucket":"perpetuating"},{"id":"form-165-5","text":"Avoids presentations, photos and eating in the canteen","bucket":"presenting"},{"id":"form-165-6","text":"She studies fashion design","bucket":"distractor"},{"id":"form-165-7","text":"Keeps her head down so she never sees people''s real reactions","bucket":"perpetuating"},{"id":"form-165-8","text":"Best friend who stood up for her online","bucket":"protective"},{"id":"form-165-9","text":"A classmate posted a photo of her with a mocking caption","bucket":"precipitating"},{"id":"form-165-10","text":"Strong fear of people staring at her and judging her skin","bucket":"presenting"},{"id":"form-165-11","text":"A dermatologist she trusts","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kritika, 19, presents with social anxiety disorder linked to stigma about her vitiligo. A visible skin condition and years of intrusive comments from relatives (predisposing) taught her to expect negative judgement; an online mocking post (precipitating) intensified her fear. Covering up, avoiding eye contact and her belief that she is unlovable (perpetuating) keep her focused on her appearance and stop her testing her fears. A trusted dermatologist and a loyal friend (protective) are strengths. Vitiligo is not contagious, and clear facts can help her family too. CBT for social anxiety, support for appearance-related distress and peer support are useful. Her course is a distractor.","hint":"A 19-year-old who now refuses group photos and class presentations","tags":{"topic":"anxiety","difficulty":2,"objective":"Show how stigma about a visible skin condition can feed social anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Social anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-166', 'Mr Paul: worries that are new at seventy (late-onset anxiety with early memory changes)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-166-1","text":"Poor sleep from night-time checking of doors","bucket":"perpetuating"},{"id":"form-166-2","text":"No anxiety before seventy","bucket":"predisposing"},{"id":"form-166-3","text":"He designed bridges in the north-east for thirty years","bucket":"distractor"},{"id":"form-166-4","text":"Frightened by his own forgetfulness, which raises his worry","bucket":"perpetuating"},{"id":"form-166-5","text":"Misplaces things and repeats questions, which his wife has noticed","bucket":"presenting"},{"id":"form-166-6","text":"He grows orchids","bucket":"distractor"},{"id":"form-166-7","text":"Strong church community and adult children nearby","bucket":"protective"},{"id":"form-166-8","text":"Wife who keeps a careful diary of changes","bucket":"protective"},{"id":"form-166-9","text":"A small stroke found on a scan after a fall last year","bucket":"precipitating"},{"id":"form-166-10","text":"Stopped his church choir and social visits","bucket":"perpetuating"},{"id":"form-166-11","text":"High blood pressure and diabetes for twenty years","bucket":"predisposing"},{"id":"form-166-12","text":"New, constant worry about money, locks and his health for eight months","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Paul, 70, presents with new-onset anxiety in late life alongside early memory changes. Because he had no anxiety before seventy, the formulation asks what has changed in the brain or body. Long-standing vascular risk factors (predisposing) and a small stroke (precipitating) suggest vascular brain changes, which can cause both anxiety and mild cognitive decline. His fear of his own forgetfulness, social withdrawal and broken sleep from checking (perpetuating) worsen both mood and memory. A watchful wife and strong church and family support (protective) are real assets. The plan includes cognitive testing, vascular risk control, sleep care, simple anxiety strategies and staying socially active. His career and orchids are distractors.","hint":"A retired engineer in Shillong who now worries about everything","tags":{"topic":"anxiety","difficulty":5,"objective":"Recognise when new anxiety in late life may signal brain change","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Late-onset anxiety with mild neurocognitive disorder under assessment"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-167', 'Arnav: the books must be straight (symmetry OCD in a teenager)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-167-1","text":"Must arrange his books, pens and shoes until they feel ''just right'', taking an hour each morning","bucket":"presenting"},{"id":"form-167-2","text":"Very distressed if anyone moves his things","bucket":"presenting"},{"id":"form-167-3","text":"Father has checking habits","bucket":"predisposing"},{"id":"form-167-4","text":"Mother reorders his desk for him to save time","bucket":"perpetuating"},{"id":"form-167-5","text":"Good friends in his cricket team","bucket":"protective"},{"id":"form-167-6","text":"Restarts the whole ritual if interrupted","bucket":"perpetuating"},{"id":"form-167-7","text":"Knows the rituals are excessive and wants to stop","bucket":"protective"},{"id":"form-167-8","text":"His school is near the railway station","bucket":"distractor"},{"id":"form-167-9","text":"Moved to a new school with a stricter timetable this year","bucket":"precipitating"},{"id":"form-167-10","text":"Rigid, rule-following child","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arnav, 13, presents with obsessive-compulsive disorder of the symmetry and ordering type: an hour of arranging until things feel just right, with great distress when they are moved. A father with checking habits and a rigid temperament (predisposing) raise his risk; a new, stricter school (precipitating) added pressure. His mother helping with the arranging and restarting the ritual when interrupted (perpetuating) keep it going; helping with rituals is called family accommodation. His insight and friendships (protective) support exposure and response prevention, with the family learning to step back. The school''s location is a distractor.","hint":"A 13-year-old who is late for school every day","tags":{"topic":"ocd","difficulty":1,"objective":"Sort a symmetry and ordering OCD into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder, symmetry and ordering type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-168', 'Zubair: the prayer that must be perfect (religious scrupulosity)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-168-1","text":"Anxious, guilt-prone child","bucket":"predisposing"},{"id":"form-168-2","text":"Unwanted blasphemous thoughts during prayer that horrify him","bucket":"presenting"},{"id":"form-168-3","text":"Tries to push the thoughts away, which makes them stronger","bucket":"perpetuating"},{"id":"form-168-4","text":"Strict teacher at madrasa who stressed punishment for mistakes","bucket":"predisposing"},{"id":"form-168-5","text":"Repeats prayers and ablutions many times because he fears they were not valid","bucket":"presenting"},{"id":"form-168-6","text":"Asks the imam for reassurance after every prayer","bucket":"perpetuating"},{"id":"form-168-7","text":"His father''s death last year, after which he became very devout","bucket":"precipitating"},{"id":"form-168-8","text":"Imam who says his worship is acceptable and suggests he see a doctor","bucket":"protective"},{"id":"form-168-9","text":"Avoids the mosque at busy times in case he makes a mistake","bucket":"perpetuating"},{"id":"form-168-10","text":"He works at a mobile repair shop","bucket":"distractor"},{"id":"form-168-11","text":"Supportive mother","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Zubair, 24, presents with OCD with religious obsessions: intrusive blasphemous thoughts and fears that his prayers are invalid, with repeated prayers and washing. A guilt-prone nature and a fear-based early religious teaching (predisposing) made him vulnerable; grief after his father''s death (precipitating) deepened his religious focus and the doubts. Reassurance from the imam, thought suppression and avoidance (perpetuating) keep the doubts alive. The fact that his own faith leader sees the behaviour as excessive is a useful sign that this is OCD rather than ordinary devotion. A supportive imam and mother (protective) can help with exposure and response prevention, ideally with the imam''s blessing. His job is a distractor.","hint":"A 24-year-old who repeats his namaz many times","tags":{"topic":"ocd","difficulty":2,"objective":"Recognise religious obsessions and rituals as OCD, not devotion","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with religious obsessions (scrupulosity)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-169', 'Nandini: the scabs on her arms (skin-picking disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-169-1","text":"Magnifying mirror in the bathroom","bucket":"perpetuating"},{"id":"form-169-2","text":"Feels relief and then shame, and hides it from her partner","bucket":"perpetuating"},{"id":"form-169-3","text":"Has tried many times to stop","bucket":"presenting"},{"id":"form-169-4","text":"Picks while scrolling her phone in bed","bucket":"perpetuating"},{"id":"form-169-5","text":"Motivated by her upcoming wedding","bucket":"protective"},{"id":"form-169-6","text":"Picks at small bumps on her arms and face for an hour or more each night, causing scars","bucket":"presenting"},{"id":"form-169-7","text":"She likes making candles as a hobby","bucket":"distractor"},{"id":"form-169-8","text":"Acne flare during a stressful job change","bucket":"precipitating"},{"id":"form-169-9","text":"Mother picks at her cuticles","bucket":"predisposing"},{"id":"form-169-10","text":"Nail biting since childhood","bucket":"predisposing"},{"id":"form-169-11","text":"Dermatologist who treated the acne","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Nandini, 26, presents with excoriation disorder: repeated skin picking causing scars, with failed attempts to stop. Childhood nail biting and a mother with a similar habit (predisposing) suggest vulnerability; an acne flare during a stressful job change (precipitating) gave the picking new targets. Picking while scrolling in bed, the relief followed by shame and secrecy, and the magnifying mirror (perpetuating) keep the habit going. A dermatologist and a meaningful goal (protective) support habit reversal training, which teaches awareness of triggers and a competing response, and removing cues like the mirror. Candle making is a distractor.","hint":"A 26-year-old who wears full sleeves even in May","tags":{"topic":"ocd","difficulty":2,"objective":"Show how tension and relief maintain a body-focused repetitive behaviour","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Excoriation (skin-picking) disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-170', 'Karthik: does he really love her? (relationship obsessions before a wedding)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-170-1","text":"Needs certainty before any decision","bucket":"predisposing"},{"id":"form-170-2","text":"Fiancée is warm and they enjoy each other''s company","bucket":"protective"},{"id":"form-170-3","text":"Compares his feelings to film romances and to past crushes","bucket":"presenting"},{"id":"form-170-4","text":"Checking habits as a student","bucket":"predisposing"},{"id":"form-170-5","text":"Hours a day spent asking himself if he truly loves his fiancée","bucket":"presenting"},{"id":"form-170-6","text":"Recognises the doubt feels ''stuck'' and excessive","bucket":"protective"},{"id":"form-170-7","text":"Avoids seeing his fiancée in case the doubt gets worse","bucket":"perpetuating"},{"id":"form-170-8","text":"The wedding is planned in Madurai","bucket":"distractor"},{"id":"form-170-9","text":"Asks friends again and again whether his feelings are ''enough''","bucket":"perpetuating"},{"id":"form-170-10","text":"Engagement fixed after only three meetings","bucket":"precipitating"},{"id":"form-170-11","text":"Takes online quizzes about true love","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Karthik, 28, presents with OCD with relationship obsessions: repeated, distressing doubts about whether he loves his fiancée, with checking of his feelings and reassurance seeking. Earlier checking habits and intolerance of uncertainty (predisposing) set the stage; an engagement fixed quickly (precipitating) gave the doubt a target. Asking friends, online quizzes and avoiding his fiancée (perpetuating) keep the doubt alive, because no answer can give the total certainty he seeks. The key difference from ordinary doubt is the stuck, repetitive quality and the rituals. His insight and a good relationship (protective) support exposure and response prevention focused on living with uncertainty. The wedding venue is a distractor.","hint":"A 28-year-old engaged through an arranged match","tags":{"topic":"ocd","difficulty":3,"objective":"Recognise obsessional doubt about a relationship as OCD","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with relationship obsessions"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-171', 'Aryan: the thought he cannot unthink (sexual orientation obsessions)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-171-1","text":"Checks his reactions when he sees men and women, many times a day","bucket":"presenting"},{"id":"form-171-2","text":"Grew up in a home where sex was never discussed","bucket":"predisposing"},{"id":"form-171-3","text":"Avoids male friends and the gym","bucket":"perpetuating"},{"id":"form-171-4","text":"Intrusive, unwanted doubts that he might be gay, which cause him great anxiety","bucket":"presenting"},{"id":"form-171-5","text":"Brother who is calm and kind","bucket":"protective"},{"id":"form-171-6","text":"Childhood counting rituals","bucket":"predisposing"},{"id":"form-171-7","text":"He is curious and comfortable about the idea of being attracted to men","bucket":"distractor"},{"id":"form-171-8","text":"He wants to study architecture","bucket":"distractor"},{"id":"form-171-9","text":"Can see that the checking makes things worse","bucket":"protective"},{"id":"form-171-10","text":"Asks his elder brother for reassurance","bucket":"perpetuating"},{"id":"form-171-11","text":"Watches videos to test his arousal, then doubts the result","bucket":"perpetuating"},{"id":"form-171-12","text":"A friend joked that he ''looked at'' another boy","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aryan, 17, presents with OCD focused on sexual orientation: unwanted doubts about being gay that cause great anxiety, with checking, testing and reassurance seeking. Earlier counting rituals and a home where sex was never discussed (predisposing) set the scene; a friend''s joke (precipitating) gave the obsession its target. Testing his arousal, seeking reassurance and avoiding male friends (perpetuating) keep the doubt alive. His brother and his insight (protective) support exposure and response prevention. The card saying he is curious and comfortable about attraction to men does not fit him: genuine questioning tends to feel exploratory rather than horrifying, while his thoughts are unwanted and driven by fear. That card is left out. Treatment targets the checking and the fear, not his orientation, and must never aim to change anyone''s orientation. His study plans are a distractor.","hint":"A 17-year-old terrified he ''might be gay'' though he says he is not","tags":{"topic":"ocd","difficulty":4,"objective":"Tell sexual orientation obsessions apart from genuine identity questioning","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with sexual orientation obsessions"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-172', 'Gulshan: is the water poisoned? (OCD with poor insight, not a delusion)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-172-1","text":"Husband who wants to help","bucket":"protective"},{"id":"form-172-2","text":"Mother with similar rituals","bucket":"predisposing"},{"id":"form-172-3","text":"Contamination fears since her twenties that came and went","bucket":"predisposing"},{"id":"form-172-4","text":"Family follow her water rules to avoid fights","bucket":"perpetuating"},{"id":"form-172-5","text":"She makes pickles to sell","bucket":"distractor"},{"id":"form-172-6","text":"Believes the neighbours are poisoning her water to drive her out","bucket":"distractor"},{"id":"form-172-7","text":"Can sometimes say ''maybe I am overdoing it'' when calm","bucket":"protective"},{"id":"form-172-8","text":"Feels fairly sure the water at home may be contaminated and boils and filters it five times","bucket":"presenting"},{"id":"form-172-9","text":"Will drink only water she has treated herself","bucket":"presenting"},{"id":"form-172-10","text":"Has stopped visiting relatives because she cannot control their water","bucket":"perpetuating"},{"id":"form-172-11","text":"A jaundice outbreak in her colony two years ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Gulshan, 40, presents with OCD with poor insight: strong doubts about contamination with repeated boiling and filtering. Long-standing fluctuating contamination fears and a mother with rituals (predisposing) show a lifelong pattern; a real jaundice outbreak (precipitating) intensified it. Family accommodation and avoidance of relatives (perpetuating) keep it going. Her occasional ability to doubt her fears (protective) is an important clue that this is not a delusion, and a supportive husband helps. The card about neighbours deliberately poisoning her is left out because it is not her belief: a fixed belief of persecution would point to a psychotic illness. In OCD, even with poor insight, the fear is of contamination with doubt, not of being targeted. Pickle making is a distractor. Treatment is ERP with an SSRI, often at higher doses than for depression.","hint":"A 40-year-old who boils and filters water five times","tags":{"topic":"ocd","difficulty":4,"objective":"Tell OCD with poor insight apart from a delusional belief","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with poor insight"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-173', 'Mrs Ranganathan: the rituals that run the house (severe OCD with family accommodation and depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-173-1","text":"Washing and cleaning for six to eight hours a day, with raw, bleeding hands","bucket":"presenting"},{"id":"form-173-2","text":"She is an expert in Carnatic music","bucket":"distractor"},{"id":"form-173-3","text":"Her mother-in-law''s death in hospital from an infection, which she blames on herself","bucket":"precipitating"},{"id":"form-173-4","text":"Low mood, hopelessness and saying she is ''a burden'' for three months","bucket":"presenting"},{"id":"form-173-5","text":"OCD began at 19 and was never treated fully","bucket":"predisposing"},{"id":"form-173-6","text":"Daughter who is studying psychology and has read about OCD","bucket":"protective"},{"id":"form-173-7","text":"Has asked for help herself this time","bucket":"protective"},{"id":"form-173-8","text":"The family owns a textile shop in T Nagar","bucket":"distractor"},{"id":"form-173-9","text":"No longer goes to the temple, which was her main support","bucket":"perpetuating"},{"id":"form-173-10","text":"Perfectionistic, high sense of responsibility for the family''s purity and safety","bucket":"predisposing"},{"id":"form-173-11","text":"Husband buys extra soap and detergent to avoid her distress","bucket":"perpetuating"},{"id":"form-173-12","text":"Everyone at home must change clothes and bathe before entering","bucket":"perpetuating"},{"id":"form-173-13","text":"Took an SSRI for one month at a low dose, then stopped","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Ranganathan, 46, presents with severe OCD with long hours of washing and cleaning, now complicated by secondary depression. Untreated OCD since early adulthood and a strong sense of responsibility for her family''s safety (predisposing) set the base; her mother-in-law''s death from infection (precipitating) fed guilt and a surge in rituals. Family accommodation has grown until the household follows her rules, an inadequate short SSRI trial left her untreated, and loss of the temple removed a support (perpetuating). In CBT terms, each accommodated ritual confirms the fear; the depression adds hopelessness, so suicide risk must be asked about. Her daughter''s knowledge and her own help-seeking (protective) are real strengths. A plan of an SSRI at an adequate dose and duration, ERP with family sessions to reduce accommodation step by step, and skin care is needed. Her family''s shop and her music are distractors.","hint":"A 46-year-old whose joint family now follows her washing rules","tags":{"topic":"ocd","difficulty":5,"objective":"Build a full formulation of severe OCD with family patterns and low mood","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Severe obsessive-compulsive disorder with secondary depression"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-174', 'Abdul: the sanitiser that never runs out (contamination OCD after the pandemic)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-174-1","text":"Uses a full bottle of sanitiser a day and washes his hands until they crack","bucket":"presenting"},{"id":"form-174-2","text":"Tidy and cautious since childhood","bucket":"predisposing"},{"id":"form-174-3","text":"His branch is on the ground floor","bucket":"distractor"},{"id":"form-174-4","text":"His father was seriously ill with COVID in 2021","bucket":"precipitating"},{"id":"form-174-5","text":"Manager who supports a therapy schedule","bucket":"protective"},{"id":"form-174-6","text":"Intrusive fears of carrying germs home to his baby","bucket":"presenting"},{"id":"form-174-7","text":"Wife washes his office clothes separately to calm him","bucket":"perpetuating"},{"id":"form-174-8","text":"Knows his fear is excessive","bucket":"protective"},{"id":"form-174-9","text":"Brief counting habit as a teenager","bucket":"predisposing"},{"id":"form-174-10","text":"Showers for an hour after work","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Abdul, 33, presents with contamination OCD: intrusive fears of bringing germs to his baby with excessive sanitising, washing and showering. A cautious temperament and an earlier counting habit (predisposing) suggest vulnerability; his father''s serious COVID illness (precipitating) gave the fear a real origin. Long showers and his wife''s separate washing (perpetuating) keep the fear going by preventing new learning. His insight and a supportive manager (protective) suit exposure and response prevention. The branch floor is a distractor.","hint":"A 33-year-old bank clerk who sprays every note he touches","tags":{"topic":"ocd","difficulty":1,"objective":"Sort a contamination OCD that began with a real threat","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder, contamination type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-175', 'Sonal: one week after the bus accident (acute stress disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-175-1","text":"College offering counselling to all students","bucket":"protective"},{"id":"form-175-2","text":"Earlier fright when her house was burgled","bucket":"predisposing"},{"id":"form-175-3","text":"Close family who came at once","bucket":"protective"},{"id":"form-175-4","text":"The bus was going to a trekking camp","bucket":"distractor"},{"id":"form-175-5","text":"Her college bus overturned on a ghat road; two students died","bucket":"precipitating"},{"id":"form-175-6","text":"Flashbacks of the crash, nightmares and feeling detached from herself, for one week","bucket":"presenting"},{"id":"form-175-7","text":"Avoids any talk of the crash","bucket":"perpetuating"},{"id":"form-175-8","text":"Sleeps only two hours a night","bucket":"perpetuating"},{"id":"form-175-9","text":"Jumps at loud noises and cannot sit in a bus","bucket":"presenting"},{"id":"form-175-10","text":"Anxious temperament","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sonal, 20, presents with acute stress disorder one week after a fatal bus crash: intrusive memories, nightmares, detachment, startle and avoidance. An anxious temperament and an earlier frightening event (predisposing) raise her vulnerability; the crash with the deaths of classmates (precipitating) is the trauma. Avoidance and severe sleep loss (perpetuating) can make it harder to recover. Close family and college counselling (protective) are vital. Acute stress disorder is diagnosed between three days and one month after a trauma; if symptoms last longer, PTSD is considered. Brief trauma-focused CBT can help prevent PTSD. The trip''s destination is a distractor.","hint":"A 20-year-old student who survived a bus crash on the ghat road","tags":{"topic":"trauma","difficulty":1,"objective":"Sort an acute stress reaction within the first month into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"trauma","diagnosis":"Acute stress disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-176', 'Nisha: after the divorce papers (adjustment disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-176-1","text":"Tearful, worried and unable to focus at work for six weeks","bucket":"presenting"},{"id":"form-176-2","text":"Tends to bottle things up","bucket":"predisposing"},{"id":"form-176-3","text":"Relatives keep asking what she did wrong","bucket":"perpetuating"},{"id":"form-176-4","text":"Stays up late reading his messages from years ago","bucket":"perpetuating"},{"id":"form-176-5","text":"Financially independent","bucket":"protective"},{"id":"form-176-6","text":"Her own parents'' bitter divorce when she was fifteen","bucket":"predisposing"},{"id":"form-176-7","text":"Husband filed for divorce two months ago","bucket":"precipitating"},{"id":"form-176-8","text":"Not severe enough for a depressive episode and still managing her classes","bucket":"presenting"},{"id":"form-176-9","text":"A colleague who is also a close friend","bucket":"protective"},{"id":"form-176-10","text":"She teaches geography","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Nisha, 35, presents with an adjustment disorder with mixed anxiety and low mood: tearfulness, worry and poor focus starting soon after a clear stressor, without meeting criteria for a depressive episode. A habit of bottling things up and memories of her parents'' divorce (predisposing) made this harder; her husband filing for divorce (precipitating) began it. Relatives'' blame and re-reading old messages (perpetuating) keep the distress alive. A close friend and financial independence (protective) predict good recovery with brief supportive and problem-solving therapy. Her subject is a distractor.","hint":"A 35-year-old teacher who cannot focus since the separation","tags":{"topic":"trauma","difficulty":1,"objective":"Sort a stress-linked adjustment disorder into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"trauma","diagnosis":"Adjustment disorder with mixed anxiety and depressed mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-177', 'Anu: the night the hill came down (PTSD in a child after a landslide)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-177-1","text":"A teacher running play sessions in the camp","bucket":"protective"},{"id":"form-177-2","text":"Anxious, sensitive child","bucket":"predisposing"},{"id":"form-177-3","text":"Nightmares, clinging, and fear of rain for four months","bucket":"presenting"},{"id":"form-177-4","text":"Loving elder cousin who stays with her","bucket":"protective"},{"id":"form-177-5","text":"Plays the landslide again and again with sand and toy houses","bucket":"presenting"},{"id":"form-177-6","text":"Father works away in the Gulf","bucket":"predisposing"},{"id":"form-177-7","text":"Landslide destroyed her village; her grandmother was among those who died","bucket":"precipitating"},{"id":"form-177-8","text":"Each monsoon shower brings back the fear","bucket":"perpetuating"},{"id":"form-177-9","text":"Mother is too distressed herself to talk about it","bucket":"perpetuating"},{"id":"form-177-10","text":"Her favourite colour is pink","bucket":"distractor"},{"id":"form-177-11","text":"Living in a relief camp with no routine or school","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anu, 8, presents with PTSD after a landslide that killed her grandmother. In children, re-experiencing often shows as repetitive play about the event, and fear can show as clinging and nightmares without clear content. An anxious temperament and an absent father (predisposing) leave her with less support; the landslide and bereavement (precipitating) are the trauma. Life in a relief camp without school, a mother overwhelmed by her own grief, and rain as a constant reminder (perpetuating) keep the symptoms going. A teacher running play sessions and her cousin (protective) are vital. Restoring routine and school, supporting her mother, and trauma-focused CBT adapted for children are the plan. Her favourite colour is a distractor.","hint":"An 8-year-old from Wayanad who re-enacts the disaster in play","tags":{"topic":"trauma","difficulty":3,"objective":"Recognise how PTSD shows in young children","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"child","diagnosis":"Posttraumatic stress disorder in a child"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-178', 'Constable Shaikh: the blast site at the station (PTSD in a police officer)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-178-1","text":"Wife who noticed the change and spoke to his senior","bucket":"protective"},{"id":"form-178-2","text":"Believes a policeman must never show fear","bucket":"predisposing"},{"id":"form-178-3","text":"Drinks every night to sleep","bucket":"perpetuating"},{"id":"form-178-4","text":"First on the scene of a train blast with many dead","bucket":"precipitating"},{"id":"form-178-5","text":"He was awarded a medal for the rescue","bucket":"distractor"},{"id":"form-178-6","text":"A senior officer who supports a referral","bucket":"protective"},{"id":"form-178-7","text":"Irritable, jumpy and avoiding the railway station","bucket":"presenting"},{"id":"form-178-8","text":"Volunteers for night patrols so he does not have to sleep","bucket":"perpetuating"},{"id":"form-178-9","text":"Colleagues mock anyone who sees the ''mind doctor''","bucket":"perpetuating"},{"id":"form-178-10","text":"Flashbacks and nightmares of the blast scene, eight months on","bucket":"presenting"},{"id":"form-178-11","text":"Two earlier traumatic duties with no debrief","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Constable Shaikh, 41, presents with PTSD eight months after attending a train blast: flashbacks, nightmares, irritability, startle and avoidance. Earlier traumatic duties without support and a belief that police must not show fear (predisposing) raised his risk; the blast scene (precipitating) is the index trauma. Drinking to sleep, taking night duty to avoid sleep and a mocking work culture (perpetuating) keep the symptoms going. His wife and a supportive senior (protective) open the door to trauma-focused therapy such as trauma-focused CBT or EMDR, and to treatment for the drinking. The medal is a distractor; recognition does not protect against PTSD.","hint":"A 41-year-old who was first at the scene of a train blast","tags":{"topic":"trauma","difficulty":2,"objective":"Show how work culture can maintain PTSD in first responders","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"trauma","diagnosis":"Posttraumatic stress disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-179', 'Rukhsar: the anger and the flashbacks (complex PTSD, not borderline personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-179-1","text":"Her stepfather moved back to the family home after her mother''s illness","bucket":"precipitating"},{"id":"form-179-2","text":"She is good at badminton","bucket":"distractor"},{"id":"form-179-3","text":"Numbs herself with long working hours","bucket":"perpetuating"},{"id":"form-179-4","text":"Frantic efforts to avoid being left, with rapidly swinging views of others","bucket":"distractor"},{"id":"form-179-5","text":"Flashbacks and nightmares of childhood beatings, with strong avoidance","bucket":"presenting"},{"id":"form-179-6","text":"Avoids her family entirely, which leaves her very alone","bucket":"perpetuating"},{"id":"form-179-7","text":"One long, steady friendship","bucket":"protective"},{"id":"form-179-8","text":"Persistent shame, a stable belief that she is worthless and keeps people at a distance","bucket":"presenting"},{"id":"form-179-9","text":"Years of physical abuse by her stepfather from age six to sixteen","bucket":"predisposing"},{"id":"form-179-10","text":"Stable job as a lab technician for eight years","bucket":"protective"},{"id":"form-179-11","text":"No adult who protected her","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rukhsar, 30, presents with complex PTSD: core PTSD symptoms plus lasting problems with self-worth, emotion and relationships after years of abuse. Prolonged childhood abuse without protection (predisposing) is typical of complex PTSD; her stepfather''s return (precipitating) worsened the symptoms. Total avoidance of family and numbing through overwork (perpetuating) keep her isolated. A stable job and a long friendship (protective) are important differences from borderline personality, where relationships and identity tend to be unstable. The card about frantic fear of abandonment and swinging views of others is left out because it does not describe her; it fits borderline personality, the look-alike. Her pattern is a stable negative self-view and keeping distance. Badminton is a distractor. Phase-based, trauma-focused therapy is suitable.","hint":"A 30-year-old who grew up with years of abuse at home","tags":{"topic":"trauma","difficulty":4,"objective":"Tell complex PTSD apart from borderline personality disorder","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"trauma","diagnosis":"Complex posttraumatic stress disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-180', 'Hasina: the camp in Delhi (PTSD in a refugee)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-180-1","text":"Nightmares and flashbacks of her village burning, headaches and poor sleep","bucket":"presenting"},{"id":"form-180-2","text":"No news of her husband","bucket":"perpetuating"},{"id":"form-180-3","text":"Lost her father in an earlier attack","bucket":"predisposing"},{"id":"form-180-4","text":"Strong bond with other women in the camp","bucket":"protective"},{"id":"form-180-5","text":"Grew up amid violence and loss of rights","bucket":"predisposing"},{"id":"form-180-6","text":"Language barrier with local services","bucket":"perpetuating"},{"id":"form-180-7","text":"The camp is near the Yamuna river","bucket":"distractor"},{"id":"form-180-8","text":"Startles at the sound of shouting and avoids talking about home","bucket":"presenting"},{"id":"form-180-9","text":"Fear of eviction or detention in the camp","bucket":"perpetuating"},{"id":"form-180-10","text":"An NGO health worker who speaks her language","bucket":"protective"},{"id":"form-180-11","text":"Village burned and her husband went missing as they fled","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Hasina, 27, presents with PTSD after violence and flight: nightmares, flashbacks, startle, avoidance and headaches, which are a common way distress is expressed. Long exposure to violence and an earlier loss (predisposing) made her vulnerable; the burning of her village and her husband going missing (precipitating) are the main traumas. Ongoing insecurity, unresolved loss and language barriers (perpetuating) mean the threat is not fully over, so safety and practical needs come before deep trauma work. Women''s solidarity in the camp and a health worker who speaks her language (protective) are key. The river nearby is a distractor.","hint":"A 27-year-old Rohingya woman with two small children","tags":{"topic":"trauma","difficulty":3,"objective":"Include displacement and ongoing insecurity in a trauma formulation","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"trauma","diagnosis":"Posttraumatic stress disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-181', 'Sister Mary: the night the oxygen ran out (moral injury and PTSD in a nurse)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-181-1","text":"Works extra shifts in other wards to keep busy","bucket":"perpetuating"},{"id":"form-181-2","text":"Intrusive memories of patients gasping, nightmares and avoidance of the ICU","bucket":"presenting"},{"id":"form-181-3","text":"Strong guilt that she ''chose who lived''","bucket":"presenting"},{"id":"form-181-4","text":"Colleagues who were there and also want to talk","bucket":"protective"},{"id":"form-181-5","text":"Night shift when the hospital''s oxygen supply ran out and several patients died","bucket":"precipitating"},{"id":"form-181-6","text":"Deep sense of duty from her faith and training","bucket":"predisposing"},{"id":"form-181-7","text":"She trained at a nursing college in Kottayam","bucket":"distractor"},{"id":"form-181-8","text":"Believes she should be punished","bucket":"perpetuating"},{"id":"form-181-9","text":"Has never spoken about that night","bucket":"perpetuating"},{"id":"form-181-10","text":"Religious community she trusts","bucket":"protective"},{"id":"form-181-11","text":"Takes responsibility for things outside her control","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sister Mary, 44, presents with PTSD with strong features of moral injury: intrusive memories, nightmares and avoidance, plus guilt that she betrayed her own values. A strong sense of duty and a tendency to take responsibility for everything (predisposing) shaped how she judged herself; the night the oxygen ran out (precipitating) forced impossible choices. Silence, a belief that she deserves punishment and overwork (perpetuating) keep the guilt locked in. Her religious community and colleagues who shared the night (protective) offer a place for compassion and shared meaning. Trauma-focused therapy that tackles guilt and self-blame, and naming the system failure, are central. Her nursing college is a distractor.","hint":"A 44-year-old ICU nurse two years after the second COVID wave","tags":{"topic":"trauma","difficulty":3,"objective":"Add moral injury, guilt and shame to a PTSD formulation","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"trauma","diagnosis":"Posttraumatic stress disorder with moral injury"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-182', 'Pratik: after the robbery at the ATM (adjustment disorder, not PTSD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-182-1","text":"Worried, tense and sleeping poorly for five weeks since the robbery","bucket":"presenting"},{"id":"form-182-2","text":"Robbed at knifepoint at an ATM late at night","bucket":"precipitating"},{"id":"form-182-3","text":"Worries about rent constantly","bucket":"perpetuating"},{"id":"form-182-4","text":"Has stopped late deliveries and is losing income","bucket":"perpetuating"},{"id":"form-182-5","text":"Delivery company has offered a daytime shift","bucket":"protective"},{"id":"form-182-6","text":"Brother who shares the rent","bucket":"protective"},{"id":"form-182-7","text":"He rides a blue scooter","bucket":"distractor"},{"id":"form-182-8","text":"Works long hours with no fixed income","bucket":"predisposing"},{"id":"form-182-9","text":"Felt shaky and tearful for an hour after the robbery, as anyone would","bucket":"distractor"},{"id":"form-182-10","text":"No flashbacks or nightmares, and he still uses ATMs in daylight","bucket":"presenting"},{"id":"form-182-11","text":"Shy and a worrier","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pratik, 24, presents with an adjustment disorder with anxiety after a robbery at knifepoint. Although the robbery was a threat to life and could cause PTSD, he has no intrusive memories or nightmares and avoids only late-night work, so PTSD criteria are not met. A shy, worrying nature and insecure work (predisposing) shaped his response; the robbery (precipitating) started it. Loss of income from stopping late shifts and rent worry (perpetuating) keep it going, now more about money than fear. His brother and the offer of day shifts (protective) point to problem-solving and a graded return to work. The card about feeling shaky for an hour after the robbery is tempting, but that is a normal immediate reaction and is not a disorder or a factor. The scooter is a distractor. He should be reviewed in case PTSD symptoms appear later.","hint":"A 24-year-old delivery rider robbed at knifepoint","tags":{"topic":"trauma","difficulty":4,"objective":"Tell an adjustment disorder after a frightening event apart from PTSD","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"trauma","diagnosis":"Adjustment disorder with anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-183', 'Roshni: the voice of the man who hurt her (PTSD with trauma-linked voices)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-183-1","text":"Childhood neglect","bucket":"predisposing"},{"id":"form-183-2","text":"Nightmares, flashbacks, startle and avoidance of the place it happened","bucket":"presenting"},{"id":"form-183-3","text":"Hears the voice of the man who assaulted her, saying the same threats he used","bucket":"presenting"},{"id":"form-183-4","text":"Good functioning between episodes, with clear thinking and normal speech","bucket":"protective"},{"id":"form-183-5","text":"Has never told anyone the full story","bucket":"perpetuating"},{"id":"form-183-6","text":"Earlier unwanted touching by a relative at age twelve","bucket":"predisposing"},{"id":"form-183-7","text":"The man still works in the same building","bucket":"perpetuating"},{"id":"form-183-8","text":"Sleeps very little because of nightmares","bucket":"perpetuating"},{"id":"form-183-9","text":"Sexually assaulted by a co-worker a year ago","bucket":"precipitating"},{"id":"form-183-10","text":"Long spell of withdrawal, flat emotion and odd beliefs before the assault","bucket":"distractor"},{"id":"form-183-11","text":"A friend from college who believes her","bucket":"protective"},{"id":"form-183-12","text":"Her office is in a tech park","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Roshni, 25, presents with PTSD with trauma-related voices. The voice is that of her attacker and repeats his words, it comes with flashbacks and nightmares, and her thinking and speech are otherwise clear, all of which point to PTSD rather than schizophrenia. Earlier neglect and abuse (predisposing) raise her vulnerability; the assault (precipitating) is the index trauma. Silence, ongoing contact with the attacker and poor sleep (perpetuating) keep the symptoms going. A believing friend and good functioning (protective) are strengths. The card about a long spell of withdrawal and odd beliefs before the assault is left out because it is not her history; that prodrome would point to a psychotic disorder. Her office location is a distractor. Safety at work, her legal options and trauma-focused therapy come first.","hint":"A 25-year-old referred with ''schizophrenia'' after hearing a voice","tags":{"topic":"trauma","difficulty":4,"objective":"Tell trauma-linked voices in PTSD apart from a primary psychotic illness","exams":["md-psychiatry","mcp-entrance"],"module":"trauma","diagnosis":"Posttraumatic stress disorder with trauma-related hallucinations"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-184', 'Havildar Thapa: headaches, memory and nightmares after the IED (PTSD with mild brain injury)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-184-1","text":"Nightmares, flashbacks and jumpiness, with anger outbursts at home","bucket":"presenting"},{"id":"form-184-2","text":"Two earlier deployments in conflict zones","bucket":"predisposing"},{"id":"form-184-3","text":"A unit commander who encourages treatment","bucket":"protective"},{"id":"form-184-4","text":"Headaches lead him to avoid activity, so he becomes unfit and low","bucket":"perpetuating"},{"id":"form-184-5","text":"An IED blast hit his vehicle; he was knocked out briefly and a friend died","bucket":"precipitating"},{"id":"form-184-6","text":"Drinks rum every night to sleep","bucket":"perpetuating"},{"id":"form-184-7","text":"Wife and young son he is close to","bucket":"protective"},{"id":"form-184-8","text":"He is from Darjeeling","bucket":"distractor"},{"id":"form-184-9","text":"Refuses to talk to the unit doctor for fear of losing his posting","bucket":"perpetuating"},{"id":"form-184-10","text":"Grew up with a father who drank and was violent","bucket":"predisposing"},{"id":"form-184-11","text":"Headaches, poor concentration and forgetting tasks since the blast","bucket":"presenting"},{"id":"form-184-12","text":"He is a champion boxer in his regiment","bucket":"distractor"},{"id":"form-184-13","text":"Feels guilty that he survived","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Havildar Thapa, 34, presents with PTSD alongside the effects of a mild traumatic brain injury after a blast. The two overlap: poor concentration, irritability, headaches and sleep problems can come from either, so both need assessment. Earlier deployments and a violent childhood home (predisposing) raised his risk; the blast with loss of consciousness and the death of a friend (precipitating) caused both the brain injury and the trauma. Nightly drinking, avoidance of activity, survivor guilt and fear for his career (perpetuating) keep both problems going. His family and a supportive commander (protective) help. The plan includes neurological review and cognitive testing, headache care, trauma-focused therapy, alcohol reduction and anger management with his wife involved. His home town and boxing title are distractors, though repeated head blows in boxing could be worth asking about.","hint":"A 34-year-old soldier six months after a roadside blast","tags":{"topic":"trauma","difficulty":5,"objective":"Untangle PTSD from the effects of a mild brain injury in one formulation","exams":["md-psychiatry","mcp-entrance"],"module":"trauma","diagnosis":"Posttraumatic stress disorder with mild traumatic brain injury"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-185', 'Mr Jadhav: the flood rescuer who drinks (PTSD, alcohol and violence at home)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-185-1","text":"Father drank heavily","bucket":"predisposing"},{"id":"form-185-2","text":"Panchayat leader who offered to help him find treatment","bucket":"protective"},{"id":"form-185-3","text":"Drinks a bottle of country liquor daily and has hit his wife twice when drunk","bucket":"presenting"},{"id":"form-185-4","text":"Morning shakes that only alcohol settles","bucket":"perpetuating"},{"id":"form-185-5","text":"A news channel interviewed him after the flood","bucket":"distractor"},{"id":"form-185-6","text":"Wife hides the violence for fear of shame","bucket":"perpetuating"},{"id":"form-185-7","text":"His boat is painted orange","bucket":"distractor"},{"id":"form-185-8","text":"Pulled dozens from floodwater in 2019 but could not save a child who slipped from his hands","bucket":"precipitating"},{"id":"form-185-9","text":"Two sons who still look up to him","bucket":"protective"},{"id":"form-185-10","text":"Cannot fish because the river terrifies him, so money is short","bucket":"perpetuating"},{"id":"form-185-11","text":"Left school early and has no other trade","bucket":"predisposing"},{"id":"form-185-12","text":"Nightmares of bodies in the water, flashbacks and avoiding the river","bucket":"presenting"},{"id":"form-185-13","text":"Neighbours call him a hero, so he feels he cannot admit he is struggling","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Jadhav, 46, presents with PTSD and alcohol dependence, with violence towards his wife when drunk. A father who drank and limited work options (predisposing) raised his risk; the floods, and above all the child he could not save (precipitating), are the core trauma. Morning withdrawal, loss of his livelihood from avoiding the river, a hero image that silences him, and hidden violence (perpetuating) keep the cycle going. His sons and a willing panchayat leader (protective) are routes to care. The formulation must hold risk to others: his wife''s safety, and her access to support under domestic violence law, are part of the plan alongside medically managed alcohol withdrawal and later trauma-focused work. The boat colour and media interview are distractors.","hint":"A 46-year-old fisherman who saved many in the Kolhapur floods","tags":{"topic":"trauma","difficulty":5,"objective":"Formulate trauma, substance use and risk to others together","exams":["md-psychiatry","mcp-entrance"],"module":"trauma","diagnosis":"Posttraumatic stress disorder with alcohol dependence"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-186', 'Pihu: the uncle and the secret (a child after sexual abuse)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-186-1","text":"She is the class monitor","bucket":"distractor"},{"id":"form-186-2","text":"Grandmother says to ''keep it inside the family''","bucket":"perpetuating"},{"id":"form-186-3","text":"The uncle still visits the family home","bucket":"perpetuating"},{"id":"form-186-4","text":"Pihu believes it was her fault for not telling sooner","bucket":"perpetuating"},{"id":"form-186-5","text":"Sad, withdrawn and scared of being touched; disclosed abuse to her school counsellor","bucket":"presenting"},{"id":"form-186-6","text":"New bedwetting, nightmares and sudden refusal to visit her aunt''s house for three months","bucket":"presenting"},{"id":"form-186-7","text":"Never taught names for body parts or about safe and unsafe touch","bucket":"predisposing"},{"id":"form-186-8","text":"Her aunt lives in Jodhpur","bucket":"distractor"},{"id":"form-186-9","text":"Mother believed her at once","bucket":"protective"},{"id":"form-186-10","text":"Repeated abuse by an uncle during holiday stays","bucket":"precipitating"},{"id":"form-186-11","text":"School counsellor who acted quickly","bucket":"protective"},{"id":"form-186-12","text":"Parents both work long hours and she was often left with relatives","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pihu, 11, presents with PTSD after repeated sexual abuse by a relative, shown by new bedwetting, nightmares, avoidance, withdrawal and fear of touch. Long periods in others'' care and no body-safety teaching (predisposing) left her less protected; the repeated abuse (precipitating) is the trauma. Ongoing contact with the abuser, family pressure for silence and her self-blame (perpetuating) keep her unsafe and distressed. Her mother''s belief and a quick-acting counsellor (protective) are among the strongest predictors of recovery. Safety comes first: in India, professionals who learn of child sexual abuse must report it under the POCSO Act, and contact with the uncle must stop. Child-friendly trauma-focused CBT, support for the parents and medical care follow. Her role as monitor and her aunt''s city are distractors.","hint":"An 11-year-old who has started wetting the bed and refuses to go to her aunt''s house","tags":{"topic":"trauma","difficulty":5,"objective":"Build a child trauma formulation that includes safety and legal duties","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"child","diagnosis":"Posttraumatic stress disorder in a child after sexual abuse"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-187', 'Dheeraj: the crush at the mela (PTSD after a stampede)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-187-1","text":"He travelled to the fair by train","bucket":"distractor"},{"id":"form-187-2","text":"Tends to blame himself","bucket":"predisposing"},{"id":"form-187-3","text":"Avoids every crowded place, including his son''s school function","bucket":"perpetuating"},{"id":"form-187-4","text":"Flashbacks of being crushed and of his mother falling, five months on","bucket":"presenting"},{"id":"form-187-5","text":"Blames himself for letting go of her hand","bucket":"perpetuating"},{"id":"form-187-6","text":"Mother has survived and does not blame him","bucket":"protective"},{"id":"form-187-7","text":"Sleeps very little","bucket":"perpetuating"},{"id":"form-187-8","text":"A stampede at a religious fair in which his mother was badly injured","bucket":"precipitating"},{"id":"form-187-9","text":"Wife and children who want him back to his old self","bucket":"protective"},{"id":"form-187-10","text":"Earlier depression after a business loss","bucket":"predisposing"},{"id":"form-187-11","text":"Cannot go into crowds, markets or temples","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dheeraj, 38, presents with PTSD after a stampede: flashbacks, avoidance of crowds and poor sleep. An earlier depression and a self-blaming style (predisposing) increased his risk; the stampede and his mother''s injury (precipitating) are the trauma. Self-blame about letting go, wide avoidance and sleep loss (perpetuating) keep it going. His mother''s survival and forgiveness and a loving family (protective) are strong supports for trauma-focused CBT that tackles the guilt and uses graded return to crowded places. The train journey is a distractor.","hint":"A 38-year-old who lost his mother''s hand in the crowd","tags":{"topic":"trauma","difficulty":2,"objective":"Sort a PTSD that follows a mass-gathering disaster","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"trauma","diagnosis":"Posttraumatic stress disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-188', 'Prachi: the boss''s messages at midnight (adjustment disorder after workplace harassment)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-188-1","text":"A friend in the HR team who says the Internal Committee can help","bucket":"protective"},{"id":"form-188-2","text":"Savings for three months","bucket":"protective"},{"id":"form-188-3","text":"Anxious, tearful and dreading work for two months","bucket":"presenting"},{"id":"form-188-4","text":"Colleagues say ''that is just how he is''","bucket":"perpetuating"},{"id":"form-188-5","text":"Her office has free lunch on Fridays","bucket":"distractor"},{"id":"form-188-6","text":"Answers his messages at night so he will not be angry","bucket":"perpetuating"},{"id":"form-188-7","text":"First job after college","bucket":"predisposing"},{"id":"form-188-8","text":"Sleeps badly and checks her phone for his messages at night","bucket":"presenting"},{"id":"form-188-9","text":"Raised to avoid conflict and keep elders happy","bucket":"predisposing"},{"id":"form-188-10","text":"Has not reported him because she fears losing her job","bucket":"perpetuating"},{"id":"form-188-11","text":"New manager began sending her personal comments and late-night messages","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Prachi, 27, presents with an adjustment disorder with anxiety linked to harassment by her manager. A conflict-avoiding upbringing and inexperience at work (predisposing) made it hard to push back; the manager''s comments and late-night messages (precipitating) started the distress. Fear of reporting, answering at night and colleagues normalising his behaviour (perpetuating) keep the stressor active. Her HR friend, who points to the workplace Internal Committee for sexual harassment complaints, and her savings (protective) give her options. Because the stressor is ongoing, the plan includes support to use her rights, boundaries around her phone, and anxiety management. Free Friday lunches are a distractor.","hint":"A 27-year-old marketing executive in Gurugram","tags":{"topic":"trauma","difficulty":2,"objective":"Show how an ongoing stressor keeps an adjustment disorder going","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"trauma","diagnosis":"Adjustment disorder with anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-189', 'Geeta: the cooking gas blast (PTSD and appearance distress after burns)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-189-1","text":"The family recently changed their gas supplier","bucket":"distractor"},{"id":"form-189-2","text":"Flashbacks of the flames and avoidance of the kitchen","bucket":"presenting"},{"id":"form-189-3","text":"Relatives stare and ask if her husband will leave her","bucket":"perpetuating"},{"id":"form-189-4","text":"A burns support group at the hospital","bucket":"protective"},{"id":"form-189-5","text":"Covers her face and has stopped going out","bucket":"presenting"},{"id":"form-189-6","text":"LPG cylinder leak caught fire while she was cooking","bucket":"precipitating"},{"id":"form-189-7","text":"Earlier low mood after a miscarriage","bucket":"predisposing"},{"id":"form-189-8","text":"Refuses mirrors and has missed physiotherapy for her scars","bucket":"perpetuating"},{"id":"form-189-9","text":"Will not cook at all, so feels useless at home","bucket":"perpetuating"},{"id":"form-189-10","text":"Husband who stays by her side","bucket":"protective"},{"id":"form-189-11","text":"Values her appearance highly in a family that comments on it","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Geeta, 32, presents with PTSD and appearance-related distress after burns from a gas fire. An earlier low spell and an appearance-focused family (predisposing) raised her vulnerability; the fire (precipitating) is the trauma. Stares and hurtful questions, avoiding mirrors and physiotherapy, and loss of her cooking role (perpetuating) feed shame, isolation and avoidance. A loyal husband and a burns support group (protective) are strong assets. Trauma-focused therapy, graded return to the kitchen, scar care and work on appearance anxiety with peer support fit together. The new gas supplier is a distractor.","hint":"A 32-year-old with facial burns four months after a cylinder fire","tags":{"topic":"trauma","difficulty":3,"objective":"Include body image and stigma in a trauma formulation","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"trauma","diagnosis":"Posttraumatic stress disorder with appearance-related distress"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-190', 'Ritesh: the new school in a new city (adjustment disorder in a teenager)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-190-1","text":"Sad, irritable and refusing to talk at home for six weeks","bucket":"presenting"},{"id":"form-190-2","text":"Father''s job means moves every few years","bucket":"predisposing"},{"id":"form-190-3","text":"Shy boy who took years to make friends in Jaipur","bucket":"predisposing"},{"id":"form-190-4","text":"Grades have dropped but he still goes to school","bucket":"presenting"},{"id":"form-190-5","text":"Family moved to Guwahati mid-year","bucket":"precipitating"},{"id":"form-190-6","text":"Parents argue about the move in front of him","bucket":"perpetuating"},{"id":"form-190-7","text":"Joined the school football team","bucket":"protective"},{"id":"form-190-8","text":"Close relationship with his mother","bucket":"protective"},{"id":"form-190-9","text":"Spends evenings gaming online with old friends instead of meeting new ones","bucket":"perpetuating"},{"id":"form-190-10","text":"The new flat has a balcony","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ritesh, 14, presents with an adjustment disorder with low mood after a family move: sadness, irritability and slipping grades without a full depressive episode. A shy temperament and repeated moves (predisposing) made the change hard; moving mid-year (precipitating) started it. Spending all his time with old friends online and parental arguments (perpetuating) slow his settling. Football and a close bond with his mother (protective) can help him build new friendships with time. The balcony is a distractor.","hint":"A 14-year-old whose father was transferred to Guwahati","tags":{"topic":"trauma","difficulty":1,"objective":"Sort a teen''s reaction to a move into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Adjustment disorder with depressed mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-191', 'Mr Sethi: the trains of 1947 return (late-life reactivation of trauma)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-191-1","text":"Frightened by crowds and loud voices, and says ''they are coming''","bucket":"presenting"},{"id":"form-191-2","text":"Loss of his busy routine removed his old way of coping","bucket":"perpetuating"},{"id":"form-191-3","text":"Never spoke about it and built a busy business life","bucket":"predisposing"},{"id":"form-191-4","text":"Witnessed killings on a train from Lahore during Partition at age six","bucket":"predisposing"},{"id":"form-191-5","text":"He prefers tea with jaggery","bucket":"distractor"},{"id":"form-191-6","text":"Wakes at night shouting about a train and dead bodies, for six months","bucket":"presenting"},{"id":"form-191-7","text":"Family correct him and say ''that was long ago''","bucket":"perpetuating"},{"id":"form-191-8","text":"TV news of riots and violence plays loudly at home","bucket":"perpetuating"},{"id":"form-191-9","text":"Sikh gurdwara community that visits him","bucket":"protective"},{"id":"form-191-10","text":"Diagnosed with early Alzheimer''s disease last year, with his wife''s death soon after","bucket":"precipitating"},{"id":"form-191-11","text":"Granddaughter who listens to his stories calmly","bucket":"protective"},{"id":"form-191-12","text":"He once owned three cloth shops in Karol Bagh","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Sethi, 85, presents with reactivated trauma symptoms in the setting of early Alzheimer''s disease: night terrors about a train, fear of crowds and loud voices. Witnessing killings as a child during Partition, never processed and kept away by work (predisposing), is the root trauma. Dementia and his wife''s death (precipitating) weakened the defences and routines that kept the memories at bay. Loss of routine, distressing news on TV and family correcting him (perpetuating) heighten fear. A listening granddaughter and his gurdwara community (protective) bring comfort. The plan focuses on safety, calm and validation, reducing triggers, steady routines, care with sedating medicines, and gentle reminiscence. His shops and tea are distractors.","hint":"An 85-year-old with early dementia who wakes shouting about the train","tags":{"topic":"trauma","difficulty":5,"objective":"Formulate old trauma that returns as memory fails in late life","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Reactivated posttraumatic stress symptoms with Alzheimer''s disease"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-192', 'Mr Kurian: the tsunami that came back at retirement (PTSD with delayed expression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-192-1","text":"Active in his church","bucket":"protective"},{"id":"form-192-2","text":"Drinks more in the evenings","bucket":"perpetuating"},{"id":"form-192-3","text":"Lost his brother and his boat in the tsunami","bucket":"predisposing"},{"id":"form-192-4","text":"He built a new boat in 2006","bucket":"distractor"},{"id":"form-192-5","text":"Retired last year and moved to a house facing the sea","bucket":"precipitating"},{"id":"form-192-6","text":"Had short, mild bad dreams for a few weeks after the tsunami, then none for years","bucket":"distractor"},{"id":"form-192-7","text":"Flashbacks and nightmares of the 2004 tsunami for the past year","bucket":"presenting"},{"id":"form-192-8","text":"Long empty days with no work to fill them","bucket":"perpetuating"},{"id":"form-192-9","text":"Watches sea-storm news over and over","bucket":"perpetuating"},{"id":"form-192-10","text":"Kept busy rebuilding and never talked about it","bucket":"predisposing"},{"id":"form-192-11","text":"Daughter who is a nurse","bucket":"protective"},{"id":"form-192-12","text":"Avoids the beach, which he once loved","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kurian, 62, presents with PTSD with delayed expression: full symptoms that began many years after the 2004 tsunami. The specifier applies when full criteria are not met until at least six months after the event. Losing his brother and boat, then coping only by keeping busy (predisposing), left the trauma unprocessed; retirement and moving to face the sea (precipitating) removed his distraction and added a constant reminder. Empty days, repeated storm news and more drinking (perpetuating) keep it going. His church and nurse daughter (protective) support trauma-focused therapy and a fuller daily routine. The card about mild bad dreams for a few weeks after the tsunami is tempting, but a brief normal reaction does not change the picture; delayed expression allows some early symptoms below full criteria. The new boat is a distractor.","hint":"A 62-year-old former fisherman from Kanyakumari","tags":{"topic":"trauma","difficulty":4,"objective":"Recognise delayed-expression PTSD and what triggers it","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"trauma","diagnosis":"Posttraumatic stress disorder with delayed expression"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-193', 'Ira: the crime reporter who cannot switch off (PTSD from repeated exposure at work)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-193-1","text":"Newsroom culture that sees distress as weakness","bucket":"perpetuating"},{"id":"form-193-2","text":"Tends to over-identify with victims","bucket":"predisposing"},{"id":"form-193-3","text":"Editor who offers a break from the crime desk","bucket":"protective"},{"id":"form-193-4","text":"Has stopped her running and her book club","bucket":"perpetuating"},{"id":"form-193-5","text":"Ten years on the crime beat with no debriefing","bucket":"predisposing"},{"id":"form-193-6","text":"Re-reads case files at night to ''get it right''","bucket":"perpetuating"},{"id":"form-193-7","text":"Intrusive images of crime scenes and victims'' families, and nightmares","bucket":"presenting"},{"id":"form-193-8","text":"She writes for an English daily in Delhi","bucket":"distractor"},{"id":"form-193-9","text":"Covered the murder of a child near her own home","bucket":"precipitating"},{"id":"form-193-10","text":"Numb, irritable and on edge, with no interest in friends for four months","bucket":"presenting"},{"id":"form-193-11","text":"Partner who is supportive","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ira, 33, presents with PTSD from repeated exposure to traumatic details through her work as a crime reporter. Work-related repeated exposure to aversive details counts as a trauma route, while watching media for leisure does not. Years on the crime beat without support and a habit of identifying closely with victims (predisposing) built up her load; a child''s murder close to home (precipitating) broke through. Night reading of files, a newsroom culture against showing distress, and dropping her outlets (perpetuating) keep it going. An understanding editor and partner (protective) support a break from the desk, trauma-focused therapy and peer support. Her newspaper is a distractor.","hint":"A 33-year-old journalist who covers violent crime","tags":{"topic":"trauma","difficulty":3,"objective":"Recognise repeated work exposure to traumatic details as a route to PTSD","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"trauma","diagnosis":"Posttraumatic stress disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-194', 'Murugan: the truck in the mirror (PTSD after a road crash)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-194-1","text":"A truck hit his auto on the highway; his passenger was badly hurt","bucket":"precipitating"},{"id":"form-194-2","text":"Earlier panic attacks in his twenties","bucket":"predisposing"},{"id":"form-194-3","text":"Drives only short lanes in the town to avoid the highway","bucket":"perpetuating"},{"id":"form-194-4","text":"Drinks at night to sleep","bucket":"perpetuating"},{"id":"form-194-5","text":"Flashbacks of a truck hitting his auto, nightmares and jumping at horns, for four months","bucket":"presenting"},{"id":"form-194-6","text":"His auto is yellow and green","bucket":"distractor"},{"id":"form-194-7","text":"Wife who supports him","bucket":"protective"},{"id":"form-194-8","text":"Avoids the highway and has lost half his income","bucket":"presenting"},{"id":"form-194-9","text":"Auto drivers'' union offering help","bucket":"protective"},{"id":"form-194-10","text":"Few close friends","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Murugan, 40, presents with PTSD after a road crash: flashbacks, nightmares, startle and avoidance of the highway. Earlier anxiety and few friends (predisposing) raise his risk; the crash and his passenger''s injuries (precipitating) are the trauma. Avoiding the highway and drinking to sleep (perpetuating) keep the fear and the sleep problems going. His wife and union support (protective) help him access trauma-focused CBT with graded return to highway driving. The auto''s colours are a distractor.","hint":"A 40-year-old auto driver who will not drive on the highway","tags":{"topic":"trauma","difficulty":1,"objective":"Sort a clear PTSD picture into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"trauma","diagnosis":"Posttraumatic stress disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-195', 'Rehaan: rituals, tics and a restless mind (OCD with tics and ADHD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-195-1","text":"A paediatrician who knows the family well","bucket":"protective"},{"id":"form-195-2","text":"Rituals take up homework time, so he stays up late","bucket":"perpetuating"},{"id":"form-195-3","text":"Moved to Class 10 with board exams and more homework","bucket":"precipitating"},{"id":"form-195-4","text":"Parents argue about whether he is ''doing it on purpose''","bucket":"perpetuating"},{"id":"form-195-5","text":"Classmates mimic his tics","bucket":"perpetuating"},{"id":"form-195-6","text":"ADHD signs since primary school","bucket":"predisposing"},{"id":"form-195-7","text":"He travels to school by the school van","bucket":"distractor"},{"id":"form-195-8","text":"His favourite food is biryani","bucket":"distractor"},{"id":"form-195-9","text":"Father had tics as a child","bucket":"predisposing"},{"id":"form-195-10","text":"Motor tics of blinking and shoulder shrugs, and poor focus and restlessness in class","bucket":"presenting"},{"id":"form-195-11","text":"Must tap things in fours and check his bag many times, with fear of bad luck if he does not","bucket":"presenting"},{"id":"form-195-12","text":"Teachers punish him for ''fidgeting'', which raises his stress and tics","bucket":"perpetuating"},{"id":"form-195-13","text":"Gifted at drawing and proud of his comics","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rehaan, 15, presents with OCD, a tic disorder and ADHD, which often occur together. A father with tics and early ADHD signs (predisposing) point to a shared developmental vulnerability; the move into board exam year (precipitating) increased demands. Punishment for fidgeting, late nights from rituals, parental conflict about intent and peer mimicry (perpetuating) all raise stress, which worsens both tics and rituals. Tics are not done on purpose, which is an important message for parents and teachers. His drawing skill and a trusted paediatrician (protective) help. The plan should sort out which problem causes the most impairment, use ERP for OCD, habit reversal for tics, ADHD treatment and school adjustments such as extra time. The school van and biryani are distractors.","hint":"A 15-year-old who taps, blinks and checks, and cannot finish homework","tags":{"topic":"ocd","difficulty":5,"objective":"Build a formulation for overlapping OCD, tics and ADHD","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with tic disorder and ADHD"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-196', 'Mrs Pai: counting to keep her family safe (OCD with mental rituals)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-196-1","text":"Counts to 108 in her head and repeats a prayer to ''cancel'' each thought, hours a day","bucket":"presenting"},{"id":"form-196-2","text":"Intrusive thoughts that her husband will die in an accident","bucket":"presenting"},{"id":"form-196-3","text":"Has always been a careful, conscientious person","bucket":"predisposing"},{"id":"form-196-4","text":"Her husband drives a white sedan","bucket":"distractor"},{"id":"form-196-5","text":"Asks her husband to call her when he reaches office","bucket":"perpetuating"},{"id":"form-196-6","text":"Her husband had a minor road accident six months ago","bucket":"precipitating"},{"id":"form-196-7","text":"Believes thinking about an accident makes it more likely","bucket":"perpetuating"},{"id":"form-196-8","text":"Enjoys her gardening group","bucket":"protective"},{"id":"form-196-9","text":"Restarts counting if she loses count","bucket":"perpetuating"},{"id":"form-196-10","text":"Mother had similar rituals","bucket":"predisposing"},{"id":"form-196-11","text":"Husband who is patient and understanding","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Pai, 50, presents with OCD with mental compulsions: intrusive fears of her husband''s death with silent counting and prayer rituals to cancel them. Mental rituals are compulsions even though nobody can see them. A mother with rituals and a conscientious nature (predisposing) raised her risk; her husband''s minor accident (precipitating) gave the fear a focus. Restarting the counts, reassurance calls and the belief that thinking about an event makes it happen, called thought-action fusion (perpetuating), keep the cycle going. A patient husband and her gardening group (protective) support ERP that includes stopping mental rituals and testing thought-action fusion. The car is a distractor.","hint":"A 50-year-old homemaker whose rituals happen silently in her head","tags":{"topic":"ocd","difficulty":2,"objective":"Recognise covert mental rituals as compulsions","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with mental compulsions"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-197', 'Sameera: the five days after the results (brief psychotic disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-197-1","text":"No psychotic symptoms before this week","bucket":"presenting"},{"id":"form-197-2","text":"Failed her first-year university exams and was shouted at by her father","bucket":"precipitating"},{"id":"form-197-3","text":"Not sleeping at all since the result","bucket":"perpetuating"},{"id":"form-197-4","text":"Cousin treated for a short psychotic illness","bucket":"predisposing"},{"id":"form-197-5","text":"Sensitive, anxious personality","bucket":"predisposing"},{"id":"form-197-6","text":"Sudden belief that her parents had been replaced, with frightened talk and poor sleep, for five days","bucket":"presenting"},{"id":"form-197-7","text":"Family brought her to hospital quickly","bucket":"protective"},{"id":"form-197-8","text":"Her college is in Aligarh","bucket":"distractor"},{"id":"form-197-9","text":"Good functioning until last week","bucket":"protective"},{"id":"form-197-10","text":"Relatives crowding the house and arguing about black magic","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sameera, 19, presents with a brief psychotic disorder: a sudden onset of delusions and disturbed behaviour lasting days, after a major stress. Brief psychotic disorder lasts at least one day and less than one month, with full return to the earlier level. A family history of psychosis and a sensitive temperament (predisposing) raised her vulnerability; failing her exams and her father''s anger (precipitating) came just before onset. Total sleep loss and a crowded, tense house (perpetuating) can keep the episode going. Good earlier functioning and fast help-seeking (protective) predict a good recovery, though she will need follow-up. Her college location is a distractor.","hint":"A 19-year-old who suddenly believed her family were imposters","tags":{"topic":"psychosis","difficulty":1,"objective":"Sort a sudden, short psychotic episode after stress into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"psychosis","diagnosis":"Brief psychotic disorder with marked stressor"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-198', 'Mr Kale: the missed injection (schizophrenia relapse after stopping a depot)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-198-1","text":"Hearing voices that insult him and believing neighbours are spying, for three weeks","bucket":"presenting"},{"id":"form-198-2","text":"Schizophrenia for twenty years with three earlier relapses","bucket":"predisposing"},{"id":"form-198-3","text":"Lives alone after his mother''s death","bucket":"predisposing"},{"id":"form-198-4","text":"Suspicion stops him opening the door to the health worker","bucket":"perpetuating"},{"id":"form-198-5","text":"Responded well to the depot before","bucket":"protective"},{"id":"form-198-6","text":"Not sleeping and has locked himself in his room","bucket":"presenting"},{"id":"form-198-7","text":"Missed two monthly depot injections when the clinic moved","bucket":"precipitating"},{"id":"form-198-8","text":"Nobody now reminds him of appointments","bucket":"perpetuating"},{"id":"form-198-9","text":"He used to work in a printing press","bucket":"distractor"},{"id":"form-198-10","text":"Long, trusting relationship with the clinic nurse","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kale, 44, presents with a relapse of schizophrenia: insulting voices, persecutory beliefs, sleeplessness and withdrawal. Long-standing illness with past relapses and living alone (predisposing) make relapse likely when treatment stops; missing two depot injections after the clinic moved (precipitating) triggered it. No one to remind him and suspicion that keeps the health worker out (perpetuating) block his return to care. A trusted nurse and good past response to the depot (protective) are the route back, with a reminder system and a home visit. The printing press is a distractor.","hint":"A 44-year-old who skipped two monthly injections","tags":{"topic":"psychosis","difficulty":1,"objective":"Sort a relapse after missed long-acting treatment into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"antipsychotics","diagnosis":"Schizophrenia, relapse"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-199', 'Jyoti: the voices that stay when the mood lifts (schizoaffective disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-199-1","text":"Steady relationship with her psychiatrist","bucket":"protective"},{"id":"form-199-2","text":"Voices continue for over a month when her mood is normal","bucket":"presenting"},{"id":"form-199-3","text":"Manic and depressive episodes with voices and persecutory beliefs","bucket":"presenting"},{"id":"form-199-4","text":"Takes her antipsychotic only when voices get loud","bucket":"perpetuating"},{"id":"form-199-5","text":"Night shifts break her sleep","bucket":"perpetuating"},{"id":"form-199-6","text":"She works at a call centre in Noida","bucket":"distractor"},{"id":"form-199-7","text":"Stopped her mood stabiliser when she started a new job","bucket":"precipitating"},{"id":"form-199-8","text":"Voices that appear only at the height of her mood episodes and vanish when mood settles","bucket":"distractor"},{"id":"form-199-9","text":"Mother with schizophrenia and an uncle with bipolar disorder","bucket":"predisposing"},{"id":"form-199-10","text":"Onset at 20","bucket":"predisposing"},{"id":"form-199-11","text":"Sister who keeps a mood and symptom chart","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Jyoti, 32, presents with schizoaffective disorder, bipolar type: mood episodes with psychosis, and psychotic symptoms that persist for weeks without a mood episode. That period of psychosis without mood symptoms is the key to the diagnosis. A mixed family history of schizophrenia and bipolar disorder and early onset (predisposing) fit this picture; stopping her mood stabiliser (precipitating) set off the latest episode. Night shifts and irregular antipsychotic use (perpetuating) keep her unstable. Her sister''s charting and a stable therapeutic relationship (protective) help. The card about voices only at the height of mood episodes is left out because it does not fit her; it describes bipolar disorder with psychotic features, the look-alike. Her workplace is a distractor. She needs both a mood stabiliser and an antipsychotic with day-shift work if possible.","hint":"A 32-year-old with mood episodes and voices that never fully go","tags":{"topic":"psychosis","difficulty":4,"objective":"Tell schizoaffective disorder apart from bipolar disorder with psychotic features","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Schizoaffective disorder, bipolar type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-200', 'Biswajit: the crystals and the energy lines (schizotypal personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-200-1","text":"Reliable at work and has held the same job for ten years","bucket":"protective"},{"id":"form-200-2","text":"Office move to a crowded open-plan floor, after which his anxiety rose","bucket":"precipitating"},{"id":"form-200-3","text":"Elder sister who visits weekly","bucket":"protective"},{"id":"form-200-4","text":"Colleagues mock his clothes and talk","bucket":"perpetuating"},{"id":"form-200-5","text":"Avoids all social contact, so his ideas are never tested","bucket":"perpetuating"},{"id":"form-200-6","text":"Uncle with schizophrenia","bucket":"predisposing"},{"id":"form-200-7","text":"He prefers fish curry with mustard","bucket":"distractor"},{"id":"form-200-8","text":"Believes he can sense ''energy lines'' and arranges crystals to protect his flat","bucket":"presenting"},{"id":"form-200-9","text":"Few friends, dresses unusually and feels very anxious with people","bucket":"presenting"},{"id":"form-200-10","text":"Spends nights on online forums about energy and signs","bucket":"perpetuating"},{"id":"form-200-11","text":"Isolated, odd child who was bullied","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Biswajit, 35, presents with schizotypal personality disorder: odd beliefs and magical thinking, eccentric appearance, few close relationships and social anxiety that does not fade with familiarity, as a long-standing pattern. Unlike a psychotic illness, his beliefs are not fixed delusions and he keeps working. A relative with schizophrenia and a lonely, bullied childhood (predisposing) fit the schizophrenia spectrum; the crowded new office (precipitating) raised his anxiety. Avoidance, late-night forums and mockery at work (perpetuating) deepen his isolation. His job record and a caring sister (protective) help. Supportive therapy, social skills work and watching for any move towards psychosis are the plan. His food preference is a distractor.","hint":"A 35-year-old clerk who has always been ''strange'' and alone","tags":{"topic":"personality","difficulty":3,"objective":"Formulate a lifelong pattern of odd beliefs and social anxiety without psychosis","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Schizotypal personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-201', 'Sudhir: the critical brother and the third relapse (high expressed emotion)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-201-1","text":"Mother is over-involved and does everything for him","bucket":"perpetuating"},{"id":"form-201-2","text":"Brother calls him ''lazy'' and ''mad'' every day","bucket":"perpetuating"},{"id":"form-201-3","text":"Schizophrenia since 22, with two earlier relapses","bucket":"predisposing"},{"id":"form-201-4","text":"Sleeps late and misses tablets during the wedding period","bucket":"perpetuating"},{"id":"form-201-5","text":"Voices and suspicion back for a month, after two years of stability","bucket":"presenting"},{"id":"form-201-6","text":"Father who is calm and supportive","bucket":"protective"},{"id":"form-201-7","text":"The wedding hall was air-conditioned","bucket":"distractor"},{"id":"form-201-8","text":"Liked his job and wants it back","bucket":"protective"},{"id":"form-201-9","text":"Has stopped going to his job at a printing unit","bucket":"presenting"},{"id":"form-201-10","text":"Sensitive to stress","bucket":"predisposing"},{"id":"form-201-11","text":"Brother''s wedding, with relatives staying and long days of rituals","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sudhir, 29, presents with a relapse of schizophrenia after two stable years. A long illness and sensitivity to stress (predisposing) set the base; a busy family wedding (precipitating) disrupted his routine. High expressed emotion, meaning criticism and hostility from his brother and over-involvement from his mother, along with missed tablets and poor sleep (perpetuating), are well known drivers of relapse. His calm father and wish to return to work (protective) are strengths. Family psychoeducation to lower criticism and over-involvement, restarting medicine and a supported return to work make up the plan. The wedding hall is a distractor.","hint":"A 29-year-old with schizophrenia who relapses after each family quarrel","tags":{"topic":"psychosis","difficulty":2,"objective":"Show how family expressed emotion can maintain relapse","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"psychosis","diagnosis":"Schizophrenia, relapse"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-202', 'Mr Abraham: two antipsychotics and still hearing voices (treatment-resistant schizophrenia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-202-1","text":"Poor school performance before onset","bucket":"predisposing"},{"id":"form-202-2","text":"Socially withdrawn, which leaves him alone with the voices","bucket":"perpetuating"},{"id":"form-202-3","text":"Unable to work or go out alone","bucket":"presenting"},{"id":"form-202-4","text":"No new trigger; the voices never fully went","bucket":"precipitating"},{"id":"form-202-5","text":"Onset at 17 with a long time before treatment","bucket":"predisposing"},{"id":"form-202-6","text":"Brother who will bring him for blood tests","bucket":"protective"},{"id":"form-202-7","text":"Takes medicine reliably, confirmed by blood levels","bucket":"protective"},{"id":"form-202-8","text":"Family fear ''the strong medicine'' and the blood tests","bucket":"perpetuating"},{"id":"form-202-9","text":"He has a tattoo of a cross on his arm","bucket":"distractor"},{"id":"form-202-10","text":"Constant commanding and insulting voices for six years","bucket":"presenting"},{"id":"form-202-11","text":"Two antipsychotics at good doses for long enough, both with little effect","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Abraham, 38, presents with treatment-resistant schizophrenia: persistent voices and poor functioning despite two adequate antipsychotic trials, with adherence confirmed. Early onset, long untreated illness and poor premorbid functioning (predisposing) are linked with a harder course. There is no new precipitant; the illness has simply not responded. The failed trials, the family''s fear of the next medicine and social withdrawal (perpetuating) keep him unwell. Reliable adherence and a brother who will help with blood monitoring (protective) make clozapine possible, which is the medicine of choice for treatment-resistant schizophrenia, with regular blood counts for a fall in white cells. His tattoo is a distractor.","hint":"A 38-year-old who has taken his tablets faithfully for years","tags":{"topic":"psychosis","difficulty":3,"objective":"Recognise when a formulation should lead to clozapine","exams":["md-psychiatry","mcp-entrance"],"module":"antipsychotics","diagnosis":"Treatment-resistant schizophrenia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-203', 'Santosh: the days after the cluster of fits (postictal psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-203-1","text":"A cluster of four seizures in one day after missing his anti-seizure medicine","bucket":"precipitating"},{"id":"form-203-2","text":"Temporal lobe epilepsy for fifteen years","bucket":"predisposing"},{"id":"form-203-3","text":"No psychosis between seizure clusters","bucket":"predisposing"},{"id":"form-203-4","text":"Months of slow withdrawal and odd beliefs without any seizures","bucket":"distractor"},{"id":"form-203-5","text":"Frightened, suspicious and hearing voices, starting two days after a cluster of seizures","bucket":"presenting"},{"id":"form-203-6","text":"Wife who knows the pattern and keeps a seizure diary","bucket":"protective"},{"id":"form-203-7","text":"He is a sales manager for a seed company","bucket":"distractor"},{"id":"form-203-8","text":"Has had the same pattern once before, which settled in a week","bucket":"presenting"},{"id":"form-203-9","text":"Missed doses during a busy work trip","bucket":"perpetuating"},{"id":"form-203-10","text":"Clear thinking between episodes and a steady job","bucket":"protective"},{"id":"form-203-11","text":"Sleep loss from travel","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Santosh, 33, presents with postictal psychosis: psychotic symptoms that began after a lucid gap of about two days following a cluster of seizures, as happened once before. Long-standing temporal lobe epilepsy (predisposing) is the base; a seizure cluster after missed medicine (precipitating) triggered this episode. Missed doses and sleep loss on a work trip (perpetuating) raise the risk of more seizures. Normal functioning between episodes and a wife who keeps a diary (protective) help. The card about months of slow withdrawal and odd beliefs without seizures is left out because it is not his story; that would point to a primary psychotic illness. His job is a distractor. Better seizure control is the main prevention, with short-term antipsychotic or benzodiazepine use for the episode.","hint":"A 33-year-old with epilepsy who became paranoid two days after seizures","tags":{"topic":"psychosis","difficulty":4,"objective":"Tell postictal psychosis apart from a primary psychotic illness","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Postictal psychosis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-204', 'The Sharma sisters: the rays from next door (shared delusional beliefs)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-204-1","text":"A quarrel with the neighbours over a water tank last year","bucket":"precipitating"},{"id":"form-204-2","text":"A niece who visits and is trusted by both","bucket":"protective"},{"id":"form-204-3","text":"Younger sister never hears any other view","bucket":"perpetuating"},{"id":"form-204-4","text":"They have a rose garden on the terrace","bucket":"distractor"},{"id":"form-204-5","text":"Both believe the neighbours send harmful rays through the wall","bucket":"presenting"},{"id":"form-204-6","text":"Younger sister is shy and has always depended on her","bucket":"predisposing"},{"id":"form-204-7","text":"Elder sister has had persecutory beliefs for years","bucket":"predisposing"},{"id":"form-204-8","text":"Have covered the walls with foil and stopped going out","bucket":"presenting"},{"id":"form-204-9","text":"Live in isolation with no other close relationships","bucket":"perpetuating"},{"id":"form-204-10","text":"Younger sister doubts the rays when she stays with a cousin","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"The Sharma sisters present with shared persecutory beliefs: the elder has long-standing delusional disorder, and the younger, who depends on her, has taken on the same belief. Older classifications called this shared psychotic disorder; now it is described as delusional symptoms in the partner of someone with a delusional disorder. The elder''s illness and the younger''s dependence (predisposing) set the stage; a quarrel with the neighbours (precipitating) gave the belief a target. Isolation together (perpetuating) keeps the belief unchallenged. The younger sister''s doubt when apart (protective) is a strong sign that separation and support can help her, while the elder sister needs treatment for delusional disorder. The niece is a key ally. The rose garden is a distractor.","hint":"Two unmarried sisters in their sixties who live alone together","tags":{"topic":"psychosis","difficulty":3,"objective":"Formulate a delusion shared by a dependent partner","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"psychosis","diagnosis":"Delusional disorder in the elder sister, with shared delusional beliefs in the younger"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-205', 'Bhola: found on the platform (chronic schizophrenia and homelessness)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-205-1","text":"Others at the station steal his food and push him away","bucket":"perpetuating"},{"id":"form-205-2","text":"Remembers his mother''s name and his village","bucket":"protective"},{"id":"form-205-3","text":"Police brought him in after he was found with a leg wound on the platform","bucket":"precipitating"},{"id":"form-205-4","text":"Calm and accepting of food and wound care","bucket":"protective"},{"id":"form-205-5","text":"Cannot give his full address but names a village in Bihar","bucket":"presenting"},{"id":"form-205-6","text":"Says he ''came for work'' many years ago","bucket":"predisposing"},{"id":"form-205-7","text":"No treatment, no shelter and no ID card","bucket":"perpetuating"},{"id":"form-205-8","text":"He sings old devotional songs","bucket":"distractor"},{"id":"form-205-9","text":"Old scar suggesting earlier treatment with injections","bucket":"predisposing"},{"id":"form-205-10","text":"Talks to himself, believes he is being followed by the CBI, and is very thin and unwashed","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Bhola, in his forties, presents with chronic, untreated schizophrenia with homelessness: persecutory delusions, self-talk, poor self-care and malnutrition. A likely past illness and migration for work (predisposing) suggest he lost contact with family and care; the leg wound (precipitating) brought him to services. No shelter, treatment or identity papers, and abuse at the station (perpetuating) keep him unwell. In India, the Mental Health Care Act 2017 gives police a duty to bring a homeless person who appears to have mental illness to a public mental health establishment for assessment, and requires efforts to trace family. His calm cooperation and memory of his village and mother (protective) make treatment and family tracing possible. His singing is a distractor.","hint":"A man in his forties brought by police from a railway station","tags":{"topic":"psychosis","difficulty":3,"objective":"Include homelessness and legal duties in a psychosis formulation","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"ethics-law","diagnosis":"Schizophrenia, chronic, with homelessness"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-206', 'Mr Kamath: the visitors after the surgery (delirium, not schizophrenia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-206-1","text":"Mild memory complaints in the past year","bucket":"predisposing"},{"id":"form-206-2","text":"Daughter who can stay with him","bucket":"protective"},{"id":"form-206-3","text":"Hip surgery two days ago, with strong pain medicine","bucket":"precipitating"},{"id":"form-206-4","text":"Glasses and hearing aid left at home","bucket":"perpetuating"},{"id":"form-206-5","text":"Sees strangers and children in his room at night and pulls at his drip","bucket":"presenting"},{"id":"form-206-6","text":"Long history of hearing voices since his thirties","bucket":"distractor"},{"id":"form-206-7","text":"Constipation and a urine catheter","bucket":"perpetuating"},{"id":"form-206-8","text":"Alert one hour and drowsy and muddled the next","bucket":"presenting"},{"id":"form-206-9","text":"Poor eyesight and hearing","bucket":"predisposing"},{"id":"form-206-10","text":"He was a cashier at a cooperative bank","bucket":"distractor"},{"id":"form-206-11","text":"Night-time noise and lights in the ward","bucket":"perpetuating"},{"id":"form-206-12","text":"Was fully independent before the fall","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kamath, 76, presents with delirium after hip surgery: visual hallucinations, agitation and fluctuating attention and alertness. Mild earlier memory problems and sensory loss (predisposing) increase delirium risk; surgery and strong pain medicine (precipitating) triggered it. Ward noise, missing glasses and hearing aid, constipation and a catheter (perpetuating) keep it going. A daughter who can stay and good earlier independence (protective) support a plan of finding and treating causes, reviewing medicines, restoring aids, keeping a normal day and night pattern and having familiar faces present. The card about hearing voices since his thirties is left out because he has no such history; it would point to a long-standing psychotic illness rather than an acute, fluctuating delirium. His old job is a distractor.","hint":"A 76-year-old who saw strangers in his room after a hip operation","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Tell delirium apart from a new psychotic illness in an older adult","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Delirium after surgery"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-207', 'Mehak: psychosis, fits and a strange stiffness (autoimmune encephalitis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-207-1","text":"Odd mouth movements, stiffness and swings in pulse and blood pressure","bucket":"presenting"},{"id":"form-207-2","text":"Given an antipsychotic and became more rigid","bucket":"perpetuating"},{"id":"form-207-3","text":"A flu-like illness two weeks before","bucket":"predisposing"},{"id":"form-207-4","text":"Rapid onset after the flu-like illness, worsening each day","bucket":"precipitating"},{"id":"form-207-5","text":"Faith healer visit delayed the hospital admission","bucket":"perpetuating"},{"id":"form-207-6","text":"Family were told it was ''only stress'' at first","bucket":"perpetuating"},{"id":"form-207-7","text":"Early in the course, so treatment can still work well","bucket":"protective"},{"id":"form-207-8","text":"She is the youngest of four sisters","bucket":"distractor"},{"id":"form-207-9","text":"Sudden fear, voices and disorganised talk over ten days, then a seizure","bucket":"presenting"},{"id":"form-207-10","text":"No psychiatric history and good functioning","bucket":"predisposing"},{"id":"form-207-11","text":"She was preparing for the UPSC exam","bucket":"distractor"},{"id":"form-207-12","text":"Brother who insisted on a neurology opinion","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mehak, 23, presents with a rapidly developing psychosis that now includes a seizure, abnormal movements and unstable pulse and blood pressure, which together are red flags for autoimmune encephalitis, such as anti-NMDA receptor encephalitis. No psychiatric history (predisposing factors notably absent) and a flu-like illness before onset (precipitating) fit an inflammatory cause. In young women this condition is sometimes linked with an ovarian tumour that should be looked for. Increased rigidity after an antipsychotic, early dismissal as stress and a delay through a faith healer (perpetuating) are dangerous because sensitivity to antipsychotics is common in this illness. A brother who pushed for neurology and early presentation (protective) give hope, as it often responds to immune treatment. Workup includes spinal fluid, antibody tests, an EEG and MRI. Her exam plans and family position are distractors, though stress from exams may have been wrongly blamed.","hint":"A 23-year-old with sudden psychosis who then had a seizure","tags":{"topic":"psychosis","difficulty":5,"objective":"Recognise red flags that a new psychosis may be a brain inflammation","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Suspected anti-NMDA receptor encephalitis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-208', 'Lalremruata: the pink tablets in Aizawl (methamphetamine psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-208-1","text":"Scratches at his skin, sure insects are crawling under it","bucket":"presenting"},{"id":"form-208-2","text":"A three-day binge of tablets after losing his job","bucket":"precipitating"},{"id":"form-208-3","text":"Friends who use still visit him","bucket":"perpetuating"},{"id":"form-208-4","text":"Not sleeping and not eating","bucket":"perpetuating"},{"id":"form-208-5","text":"Mother and church elders who are supportive","bucket":"protective"},{"id":"form-208-6","text":"Tablets are cheap and easy to get in his area","bucket":"perpetuating"},{"id":"form-208-7","text":"Was a good footballer and wants to play again","bucket":"protective"},{"id":"form-208-8","text":"Believes a gang is hunting him, hears footsteps outside and has not slept for four days","bucket":"presenting"},{"id":"form-208-9","text":"He speaks Mizo and English","bucket":"distractor"},{"id":"form-208-10","text":"Started using methamphetamine tablets with friends at 18","bucket":"predisposing"},{"id":"form-208-11","text":"Father drank heavily and left the family","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Lalremruata, 24, presents with methamphetamine-induced psychosis: persecutory delusions, auditory hallucinations, tactile hallucinations of insects and sleeplessness after a binge. Years of stimulant use and a disrupted family (predisposing) raised his risk; a binge after losing his job (precipitating) triggered the episode. Using friends, easy supply, sleeplessness and poor eating (perpetuating) keep him unwell and at risk of relapse. Stimulant psychosis usually settles with abstinence and short-term treatment, but repeated episodes can become longer lasting. His mother, church community and football (protective) are strong supports for rehabilitation. His languages are a distractor.","hint":"A 24-year-old who believes he is being hunted by a gang","tags":{"topic":"substance","difficulty":3,"objective":"Formulate a stimulant-induced psychosis and its relapse risks","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"substance","diagnosis":"Methamphetamine-induced psychotic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-209', 'Vasant: the TV news is about him (paranoid schizophrenia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-209-1","text":"No drug or alcohol use","bucket":"protective"},{"id":"form-209-2","text":"Mother who brings him to the clinic","bucket":"protective"},{"id":"form-209-3","text":"Quiet, withdrawn teenager","bucket":"predisposing"},{"id":"form-209-4","text":"Refuses medicine, saying he is not ill","bucket":"perpetuating"},{"id":"form-209-5","text":"Father''s brother has schizophrenia","bucket":"predisposing"},{"id":"form-209-6","text":"Believes the TV news sends coded messages about him and hears voices commenting on him, for eight months","bucket":"presenting"},{"id":"form-209-7","text":"Stopped working and talks to himself","bucket":"presenting"},{"id":"form-209-8","text":"He was born in Solapur","bucket":"distractor"},{"id":"form-209-9","text":"Watches news channels all day for messages","bucket":"perpetuating"},{"id":"form-209-10","text":"Lost his job at a garment export unit","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vasant, 26, presents with schizophrenia: delusions of reference about the TV news and commenting voices for eight months, with decline in work and self-care. A family history of schizophrenia and a withdrawn adolescence (predisposing) raised his vulnerability; losing his job (precipitating) came around the time of worsening. Lack of insight and watching the news all day (perpetuating) feed the delusions. His mother''s support and the absence of substance use (protective) improve the outlook. Building trust, family psychoeducation and an antipsychotic are the first steps. His place of birth is a distractor.","hint":"A 26-year-old who believes newsreaders send him messages","tags":{"topic":"psychosis","difficulty":1,"objective":"Sort a classic schizophrenia picture into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"psychosis","diagnosis":"Schizophrenia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-210', 'Kirti: the actor who loves her (erotomanic delusional disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-210-1","text":"Sensitive to rejection since her teens","bucket":"predisposing"},{"id":"form-210-2","text":"Reads hidden messages into his social media posts","bucket":"perpetuating"},{"id":"form-210-3","text":"Rejection by security guards is seen as proof that ''they are keeping us apart''","bucket":"perpetuating"},{"id":"form-210-4","text":"Works normally as an accountant","bucket":"protective"},{"id":"form-210-5","text":"Firmly believes a famous actor is secretly in love with her and sends signals in his films","bucket":"presenting"},{"id":"form-210-6","text":"Broken engagement a year ago","bucket":"precipitating"},{"id":"form-210-7","text":"Has waited outside his house many times","bucket":"presenting"},{"id":"form-210-8","text":"Lonely, with few close relationships","bucket":"predisposing"},{"id":"form-210-9","text":"She enjoys making rangoli at Diwali","bucket":"distractor"},{"id":"form-210-10","text":"Sister she trusts","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kirti, 34, presents with erotomanic delusional disorder: a fixed false belief that a famous actor loves her, with otherwise normal functioning. Loneliness and sensitivity to rejection (predisposing) left her vulnerable; a broken engagement (precipitating) came before the belief began. Reading signs into his posts and treating every rejection as proof (perpetuating) keep the belief fixed. Her intact work and a trusted sister (protective) help engagement. Stalking can lead to legal trouble and, rarely, harm, so risk needs regular review. Treatment includes a trusting relationship and antipsychotic medicine. Rangoli is a distractor.","hint":"A 34-year-old who travels to a film star''s house in Mumbai","tags":{"topic":"psychosis","difficulty":2,"objective":"Recognise erotomanic delusional disorder and its risks","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"psychosis","diagnosis":"Delusional disorder, erotomanic type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-211', 'Faisal: twenty kilos and a lot of shame (antipsychotic weight gain and stopping treatment)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-211-1","text":"Skips doses and wants to stop the medicine","bucket":"presenting"},{"id":"form-211-2","text":"A relative called him ''fat'' at a wedding, and his doctor found prediabetes","bucket":"precipitating"},{"id":"form-211-3","text":"Late-night eating from increased appetite","bucket":"perpetuating"},{"id":"form-211-4","text":"Feels ashamed and avoids friends","bucket":"perpetuating"},{"id":"form-211-5","text":"Little exercise since his illness began","bucket":"predisposing"},{"id":"form-211-6","text":"He likes cricket highlights on his phone","bucket":"distractor"},{"id":"form-211-7","text":"Family history of diabetes","bucket":"predisposing"},{"id":"form-211-8","text":"Doctor willing to discuss other options","bucket":"protective"},{"id":"form-211-9","text":"Sits at home most of the day","bucket":"perpetuating"},{"id":"form-211-10","text":"Psychosis well controlled for a year","bucket":"protective"},{"id":"form-211-11","text":"Gained 20 kg in a year on olanzapine and now has high sugars","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Faisal, 27, presents with schizophrenia in remission, now complicated by large antipsychotic-related weight gain and prediabetes, with stopping medicine as a risk. Olanzapine is among the antipsychotics most linked with weight gain and raised sugar. A family history of diabetes and inactivity (predisposing) increased the risk; a hurtful comment and a prediabetes result (precipitating) brought it to a head. Night eating, inactivity and shame (perpetuating) worsen both weight and mood. Good control of psychosis and an open doctor (protective) allow a plan: lifestyle help, regular metabolic checks and a possible switch to a medicine with fewer metabolic effects, so that he stays well and stays on treatment. Cricket highlights are a distractor.","hint":"A 27-year-old with schizophrenia who wants to stop olanzapine","tags":{"topic":"psychosis","difficulty":2,"objective":"Show how side effects can become a perpetuating factor for relapse","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"antipsychotics","diagnosis":"Schizophrenia, in remission, with antipsychotic-related weight gain"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-212', 'Rinku: pacing after the injection (akathisia, not worse psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-212-1","text":"Started haloperidol a week ago and the dose was raised","bucket":"precipitating"},{"id":"form-212-2","text":"Mother who noticed it began with the medicine","bucket":"protective"},{"id":"form-212-3","text":"Staff read the pacing as agitation and gave more haloperidol","bucket":"perpetuating"},{"id":"form-212-4","text":"Before treatment he was restless because voices told him to keep moving","bucket":"distractor"},{"id":"form-212-5","text":"Paces, rocks and cannot sit still, with a terrible inner restlessness, for five days","bucket":"presenting"},{"id":"form-212-6","text":"Distress from the restlessness is making him talk of running away","bucket":"perpetuating"},{"id":"form-212-7","text":"Voices have reduced since treatment started","bucket":"presenting"},{"id":"form-212-8","text":"Young and new to antipsychotics","bucket":"predisposing"},{"id":"form-212-9","text":"First episode of psychosis, never treated before","bucket":"predisposing"},{"id":"form-212-10","text":"Can clearly describe the feeling in his legs","bucket":"protective"},{"id":"form-212-11","text":"He is a college kabaddi player","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rinku, 22, presents with antipsychotic-induced akathisia: a distressing inner restlessness with pacing and rocking that began soon after starting and raising haloperidol, while his voices are improving. Being young and new to antipsychotics (predisposing) raised his risk; the dose rise (precipitating) triggered it. Misreading it as agitation and giving more of the same drug (perpetuating) makes it worse, and akathisia is linked with distress, poor adherence and even suicidal thoughts. His clear description and his mother''s timing (protective) are key clues. Management is to lower the dose or switch, and consider propranolol. The card about restlessness before treatment because of voices is tempting, but that was a different, earlier problem, and his current restlessness began with the medicine. Kabaddi is a distractor.","hint":"A 22-year-old who cannot sit still since starting haloperidol","tags":{"topic":"psychosis","difficulty":4,"objective":"Tell akathisia apart from agitation due to psychosis","exams":["md-psychiatry","mcp-entrance"],"module":"antipsychotics","diagnosis":"Antipsychotic-induced akathisia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-213', 'Arpit: the engineer who understood his illness (depression and suicide risk after psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-213-1","text":"Parents who want him to come home for a while","bucket":"protective"},{"id":"form-213-2","text":"Low mood, hopelessness and thoughts of ending his life since the voices stopped","bucket":"presenting"},{"id":"form-213-3","text":"Has stored a strip of his tablets","bucket":"perpetuating"},{"id":"form-213-4","text":"Believes schizophrenia means lifelong failure","bucket":"perpetuating"},{"id":"form-213-5","text":"Grandfather died by suicide","bucket":"predisposing"},{"id":"form-213-6","text":"Has stopped meeting friends out of shame","bucket":"perpetuating"},{"id":"form-213-7","text":"Gained insight that he has schizophrenia after reading his discharge papers","bucket":"precipitating"},{"id":"form-213-8","text":"Psychiatrist he trusts","bucket":"protective"},{"id":"form-213-9","text":"Says ''I will never be normal, my career is finished''","bucket":"presenting"},{"id":"form-213-10","text":"He studied at an engineering college in Pune","bucket":"distractor"},{"id":"form-213-11","text":"He plays the guitar","bucket":"distractor"},{"id":"form-213-12","text":"Lives alone in a rented flat near his old college","bucket":"perpetuating"},{"id":"form-213-13","text":"High achiever, top of his class before illness","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arpit, 25, presents with post-psychotic depression with suicidal ideation, months after recovering from a first episode of psychosis. A high-achieving past, which makes loss feel greater, and a family history of suicide (predisposing) raise his risk; gaining insight into his diagnosis (precipitating) brought hopelessness. Insight is good for treatment but can raise suicide risk in young, educated men early in schizophrenia, especially with hopelessness. The belief that schizophrenia means lifelong failure, living alone, withdrawal and stored tablets (perpetuating) keep both the mood and risk high. A trusted psychiatrist and parents who want him home (protective) help. The plan: safety planning, removing stored tablets, staying with family, treating the depression, and hope-building with recovery stories and a return to study or work. His guitar and college are distractors.","hint":"A 25-year-old three months after recovering from a first episode","tags":{"topic":"psychosis","difficulty":5,"objective":"Formulate suicide risk that rises as insight returns after psychosis","exams":["md-psychiatry","mcp-entrance"],"module":"suicide","diagnosis":"Post-psychotic depression with suicidal ideation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-214', 'Suman: the mother with schizophrenia and the new baby (planning care after birth)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-214-1","text":"She was a primary school teacher before marriage","bucket":"distractor"},{"id":"form-214-2","text":"Lives with her husband and mother-in-law","bucket":"predisposing"},{"id":"form-214-3","text":"Pregnancy and the coming birth, with the risk of relapse after delivery","bucket":"precipitating"},{"id":"form-214-4","text":"Thinking of stopping medicine to protect the baby","bucket":"perpetuating"},{"id":"form-214-5","text":"Afraid she will be ''sent away'' and the baby taken","bucket":"presenting"},{"id":"form-214-6","text":"Husband who shares night duties","bucket":"protective"},{"id":"form-214-7","text":"Night feeds will break her sleep","bucket":"perpetuating"},{"id":"form-214-8","text":"Has a good relationship with her psychiatrist and obstetrician","bucket":"protective"},{"id":"form-214-9","text":"Two relapses in the past, each after major stress and poor sleep","bucket":"predisposing"},{"id":"form-214-10","text":"Her baby shower is planned in her mother''s town","bucket":"distractor"},{"id":"form-214-11","text":"Mother-in-law tells neighbours she ''should not have children''","bucket":"perpetuating"},{"id":"form-214-12","text":"Stable on aripiprazole for two years, now seven months pregnant","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Suman, 31, is stable with schizophrenia and seven months pregnant, and the formulation aims to prevent relapse after the birth. Past relapses linked to stress and sleep loss (predisposing) mean the weeks after delivery are high risk; the birth itself (precipitating) is the coming trigger. Stigma at home, the idea of stopping medicine and broken sleep from night feeds (perpetuating) all raise the risk. Her husband''s help and good links with her psychiatrist and obstetrician (protective) are strong assets. The plan is to continue effective medicine after weighing risks with her, protect sleep with shared night feeds, involve the family, and review her often after birth. Having a mental illness does not on its own remove a mother''s right to care for her baby; support and safety planning come first. Her past job and the baby shower are distractors.","hint":"A 31-year-old seven months pregnant, stable on treatment","tags":{"topic":"perinatal","difficulty":5,"objective":"Plan around relapse risk after birth while respecting a mother''s rights","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Schizophrenia, stable, in pregnancy, with high relapse risk after birth"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-215', 'Kishore: the voices that tell him to protect his mother (command hallucinations and risk of violence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-215-1","text":"Loves his mother and listens to her","bucket":"protective"},{"id":"form-215-2","text":"Neighbour feud is real and ongoing over land","bucket":"perpetuating"},{"id":"form-215-3","text":"Threatened the neighbour with a sickle two days ago","bucket":"presenting"},{"id":"form-215-4","text":"Voices order him to ''deal with'' a neighbour they say is poisoning his mother","bucket":"presenting"},{"id":"form-215-5","text":"Past assault when drunk","bucket":"predisposing"},{"id":"form-215-6","text":"Sickle and other farm tools at home","bucket":"perpetuating"},{"id":"form-215-7","text":"Believes the voices and feels he must obey to protect his mother","bucket":"perpetuating"},{"id":"form-215-8","text":"He grows sugarcane","bucket":"distractor"},{"id":"form-215-9","text":"Accepts admission when she asks","bucket":"protective"},{"id":"form-215-10","text":"He was born in a leap year","bucket":"distractor"},{"id":"form-215-11","text":"Alcohol lowers his control","bucket":"perpetuating"},{"id":"form-215-12","text":"Stopped medicine and drank heavily for a week after his father''s death anniversary","bucket":"precipitating"},{"id":"form-215-13","text":"Schizophrenia for eight years with poor adherence","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kishore, 30, presents with a relapse of schizophrenia with command hallucinations and alcohol misuse, and a recent threat with a weapon. Long illness with poor adherence and past violence when drunk (predisposing) raise risk; stopping medicine and heavy drinking around a grief anniversary (precipitating) triggered relapse. Belief in the voices and a felt need to obey, alcohol, access to weapons and a real feud that the delusion has attached to (perpetuating) all increase the risk of acting on the voices. Past violence, substance use and believing the voices are among the strongest risk markers. His love for his mother and his willingness to accept admission at her request (protective) help. The plan is admission, treatment of psychosis, alcohol withdrawal care, removal of weapons at discharge, and a long-acting medicine. His crop and birth year are distractors.","hint":"A 30-year-old who threatened a neighbour with a sickle","tags":{"topic":"psychosis","difficulty":5,"objective":"Build a risk formulation around command hallucinations and substances","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Schizophrenia with command hallucinations and alcohol misuse"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-216', 'Aditya: something is changing (at-risk mental state)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-216-1","text":"Mother had a psychotic episode after his birth","bucket":"predisposing"},{"id":"form-216-2","text":"Hears his name called faintly now and then, and his grades have dropped","bucket":"presenting"},{"id":"form-216-3","text":"Feels people may be looking at him, but can doubt it, for four months","bucket":"presenting"},{"id":"form-216-4","text":"Cannabis use most weekends","bucket":"perpetuating"},{"id":"form-216-5","text":"Knows these experiences are probably ''in his head''","bucket":"protective"},{"id":"form-216-6","text":"Sleeps at 3 am after gaming","bucket":"perpetuating"},{"id":"form-216-7","text":"Started smoking cannabis with older friends","bucket":"precipitating"},{"id":"form-216-8","text":"Withdrawn from school friends","bucket":"perpetuating"},{"id":"form-216-9","text":"Socially anxious since childhood","bucket":"predisposing"},{"id":"form-216-10","text":"Parents who noticed and brought him early","bucket":"protective"},{"id":"form-216-11","text":"He studies in an English-medium school","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aditya, 17, presents with an at-risk mental state for psychosis: mild, brief psychotic-like experiences that he can still doubt, with falling grades. Family history of psychosis and social anxiety (predisposing) raise his vulnerability; starting cannabis (precipitating) came before the change. Late nights, ongoing cannabis and withdrawal (perpetuating) can push towards a full episode. His retained insight and observant parents (protective) mean early help can make a real difference. Stopping cannabis, regular sleep, CBT and monitoring are first steps; antipsychotics are not usually used at this stage. His school type is a distractor.","hint":"A 17-year-old with odd feelings and falling grades","tags":{"topic":"psychosis","difficulty":2,"objective":"Recognise a high-risk state before psychosis","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"psychosis","diagnosis":"Clinical high risk for psychosis (attenuated psychotic symptoms)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-217', 'Mrs D''Mello: the children on the sofa who are not there (Charles Bonnet syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-217-1","text":"Macular degeneration with severe loss of central vision","bucket":"predisposing"},{"id":"form-217-2","text":"Fear that she is ''going mad'' stops her telling the doctor","bucket":"perpetuating"},{"id":"form-217-3","text":"Knows they are not real and is calm but embarrassed","bucket":"presenting"},{"id":"form-217-4","text":"Memory and thinking are normal","bucket":"protective"},{"id":"form-217-5","text":"Sits alone in a dim room most of the day","bucket":"perpetuating"},{"id":"form-217-6","text":"Sees small children and flowers in the room, vivid and silent","bucket":"presenting"},{"id":"form-217-7","text":"She was a piano teacher","bucket":"distractor"},{"id":"form-217-8","text":"Vision got worse in her better eye this year","bucket":"precipitating"},{"id":"form-217-9","text":"Lives alone in Bandra","bucket":"predisposing"},{"id":"form-217-10","text":"Regular visits from her parish group","bucket":"protective"},{"id":"form-217-11","text":"Believes the children are spirits sent to punish her","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs D''Mello, 81, presents with Charles Bonnet syndrome: vivid, silent visual hallucinations in a person with serious sight loss, who knows they are not real. Macular degeneration (predisposing) is the base, and worsening sight (precipitating) increased the hallucinations. Isolation in dim light and fear of being thought mad (perpetuating) increase the experiences and the distress. Normal cognition and a caring parish group (protective) are reassuring. Explaining that this is a common effect of sight loss and not madness, better lighting, eye care and company are the plan. The card about believing the children are spirits sent to punish her is left out because it does not fit; a fixed false belief like that would point to psychosis, while her insight is kept. Her career is a distractor.","hint":"An 81-year-old with failing eyesight who sees vivid people","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Tell visual hallucinations from eye disease apart from psychosis and dementia","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Charles Bonnet syndrome"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-218', 'Harbhajan: the vision at the gurdwara (religious experience, not psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-218-1","text":"Since then he is calm, works normally and sleeps well","bucket":"presenting"},{"id":"form-218-2","text":"Has stopped eating and believes he must give away the family house","bucket":"distractor"},{"id":"form-218-3","text":"He drives a truck between Amritsar and Delhi","bucket":"distractor"},{"id":"form-218-4","text":"A long prayer retreat after his father''s death","bucket":"precipitating"},{"id":"form-218-5","text":"Insight, judgement and functioning are intact","bucket":"protective"},{"id":"form-218-6","text":"Saw a bright light and felt deep peace during an early morning prayer, once","bucket":"presenting"},{"id":"form-218-7","text":"No psychiatric history","bucket":"predisposing"},{"id":"form-218-8","text":"Devout all his life and from a religious family","bucket":"predisposing"},{"id":"form-218-9","text":"A relative who fears it is ''madness'' took him to a clinic","bucket":"perpetuating"},{"id":"form-218-10","text":"His community sees the experience as a blessing","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Harbhajan, 45, presents after a single religious experience of light and peace during prayer, which his community accepts as meaningful. A devout life and no psychiatric history (predisposing) and a prayer retreat during grief (precipitating) frame the event. There is no impairment, sleep and work are normal, and the experience brings comfort, so this is not a psychotic disorder. Judging an experience must take culture and religion into account. The only problem (perpetuating) is a relative''s worry, which education can ease. His community and intact functioning (protective) support no treatment beyond reassurance and an open door. The card about stopping eating and giving away the house is left out because it does not describe him; such a change would raise concern for a psychotic or manic illness. His route is a distractor.","hint":"A 45-year-old who says he saw a divine light during prayer","tags":{"topic":"culture","difficulty":4,"objective":"Tell a culturally accepted religious experience apart from psychosis","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"psychosis","diagnosis":"No psychotic disorder; a culturally congruent religious experience"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-219', 'Babu: the day centre and the bus pass (rehabilitation in long-standing schizophrenia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-219-1","text":"Smokes heavily and coughs a lot","bucket":"perpetuating"},{"id":"form-219-2","text":"A day centre near his home has a place for him","bucket":"protective"},{"id":"form-219-3","text":"Left school after Class 8","bucket":"predisposing"},{"id":"form-219-4","text":"No daily structure or activity","bucket":"perpetuating"},{"id":"form-219-5","text":"He likes old Mohammed Rafi songs","bucket":"distractor"},{"id":"form-219-6","text":"Schizophrenia for twenty-five years","bucket":"predisposing"},{"id":"form-219-7","text":"Voices are mild and well controlled on medicine","bucket":"presenting"},{"id":"form-219-8","text":"Family do everything for him","bucket":"perpetuating"},{"id":"form-219-9","text":"Takes medicine regularly","bucket":"protective"},{"id":"form-219-10","text":"His elder brother, who took him out each week, moved to another city","bucket":"precipitating"},{"id":"form-219-11","text":"Sits at home most of the day with little speech or drive","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Babu, 52, presents with chronic schizophrenia with negative symptoms: low drive, little speech and inactivity, while voices are well controlled. A long illness and limited schooling (predisposing) shape his needs; his brother''s move away (precipitating) removed his main outing. No structure, family doing everything and heavy smoking (perpetuating) keep him inactive and unhealthy. Regular medicine and a nearby day centre (protective) support a rehabilitation plan of daily activity, skills training and help to stop smoking. His love of Rafi songs is a distractor, though music could be used in activities.","hint":"A 52-year-old who has not left home in years apart from clinic visits","tags":{"topic":"psychosis","difficulty":1,"objective":"Sort a rehabilitation-focused formulation in chronic illness","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"psychosis","diagnosis":"Schizophrenia, chronic, with negative symptoms"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-220', 'Ankita: tremor, odd behaviour and a yellow tinge (Wilson''s disease presenting with psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-220-1","text":"Parents are first cousins","bucket":"predisposing"},{"id":"form-220-2","text":"An astute physician who noticed a ring of colour around her irises","bucket":"protective"},{"id":"form-220-3","text":"Symptoms began in late adolescence without a clear trigger","bucket":"precipitating"},{"id":"form-220-4","text":"Treated as schizophrenia, and the tremor was blamed on the antipsychotic","bucket":"perpetuating"},{"id":"form-220-5","text":"Liver tests were not followed up","bucket":"perpetuating"},{"id":"form-220-6","text":"She is studying for her Class 12 commerce exams","bucket":"distractor"},{"id":"form-220-7","text":"Suspicion, odd laughing and mood swings for four months","bucket":"presenting"},{"id":"form-220-8","text":"Hand tremor, slurred speech and mildly yellow eyes","bucket":"presenting"},{"id":"form-220-9","text":"Elder brother died of ''liver disease'' at 14","bucket":"predisposing"},{"id":"form-220-10","text":"Family believe it is the evil eye","bucket":"perpetuating"},{"id":"form-220-11","text":"She likes Korean dramas","bucket":"distractor"},{"id":"form-220-12","text":"Supportive parents","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ankita, 18, presents with psychiatric symptoms plus tremor, slurred speech and jaundice that point to Wilson''s disease, an inherited disorder of copper build-up in the liver and brain. Related parents and a brother''s early liver death (predisposing) fit an inherited, recessive condition; onset in adolescence without a clear trigger (precipitating) is typical. Labelling it schizophrenia, blaming the tremor on medicine, missed liver tests and a supernatural explanation (perpetuating) have delayed diagnosis. A physician who spotted copper-coloured rings in the eyes and supportive parents (protective) made the difference. Tests of copper and its carrier protein, an eye exam and liver review are needed, and treatment with copper-removing medicine can reverse much of the damage. Siblings should be screened. Her studies and shows are distractors.","hint":"An 18-year-old with new psychosis, shaking hands and abnormal liver tests","tags":{"topic":"psychosis","difficulty":5,"objective":"Recognise a treatable metabolic cause behind a young person''s psychosis","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Psychosis due to suspected Wilson''s disease"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-221', 'Seema: the marriage and the hidden diagnosis (relapse after marriage)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-221-1","text":"Voices and suspicion of her in-laws for a month after marriage","bucket":"presenting"},{"id":"form-221-2","text":"Schizophrenia since 20, stable for three years","bucket":"predisposing"},{"id":"form-221-3","text":"Her family hid the diagnosis before the marriage","bucket":"predisposing"},{"id":"form-221-4","text":"Stopped medicine after marriage so her in-laws would not find out","bucket":"precipitating"},{"id":"form-221-5","text":"Mother-in-law calls her mad and shames her","bucket":"perpetuating"},{"id":"form-221-6","text":"Stopped eating and has locked herself in her room","bucket":"presenting"},{"id":"form-221-7","text":"Good response to medicine in the past","bucket":"protective"},{"id":"form-221-8","text":"Her own parents who want to support her","bucket":"protective"},{"id":"form-221-9","text":"The wedding was held in a hall in Kanpur","bucket":"distractor"},{"id":"form-221-10","text":"No one at her new home knows how to help","bucket":"perpetuating"},{"id":"form-221-11","text":"Husband now talks of ending the marriage","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Seema, 26, presents with a relapse of schizophrenia soon after marriage. A known illness that had been stable and a family decision to hide it (predisposing) set the stage; stopping medicine to keep the secret (precipitating) caused the relapse. Marital conflict, shaming by her mother-in-law and no knowledge of the illness at her new home (perpetuating) keep her unwell. Her parents'' support and good past response (protective) give a route back. Restarting treatment and psychoeducation with both families, with her consent, are key, and the couple may need help to decide their future together. Hiding illness before marriage is a common problem driven by stigma. The wedding hall is a distractor.","hint":"A 26-year-old whose in-laws did not know she had schizophrenia","tags":{"topic":"psychosis","difficulty":2,"objective":"Show how secrecy and stigma can drive relapse","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"psychosis","diagnosis":"Schizophrenia, relapse"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-222', 'Mr Bakshi: the neighbours'' plot (persecutory delusional disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-222-1","text":"A boundary wall dispute with the neighbours","bucket":"precipitating"},{"id":"form-222-2","text":"Suspicious and sensitive to slights all his life","bucket":"predisposing"},{"id":"form-222-3","text":"Lives alone since his wife died","bucket":"predisposing"},{"id":"form-222-4","text":"A nephew he trusts","bucket":"protective"},{"id":"form-222-5","text":"Firmly believes his neighbours are plotting to take his house, for two years","bucket":"presenting"},{"id":"form-222-6","text":"He walks in the park every morning","bucket":"distractor"},{"id":"form-222-7","text":"Has cut off friends who doubt him","bucket":"perpetuating"},{"id":"form-222-8","text":"Files police complaints and has installed four cameras","bucket":"presenting"},{"id":"form-222-9","text":"Looks after himself well and manages money","bucket":"protective"},{"id":"form-222-10","text":"Watches camera footage for hours looking for proof","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Bakshi, 58, presents with persecutory delusional disorder: a fixed belief that his neighbours are plotting against him, with otherwise good functioning. A lifelong suspicious nature and living alone after widowhood (predisposing) raise his vulnerability; a boundary dispute (precipitating) gave the belief a target. Hours of watching footage and cutting off those who doubt him (perpetuating) keep the belief fixed. Good self-care and a trusted nephew (protective) are routes to engagement. Arguing directly with the belief rarely helps; building trust and offering treatment for distress is better. His walks are a distractor.","hint":"A 58-year-old retired clerk who files police complaints every week","tags":{"topic":"psychosis","difficulty":1,"objective":"Sort a persecutory delusional disorder into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"psychosis","diagnosis":"Delusional disorder, persecutory type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-223', 'Mr Gowda: the voices after he stopped drinking (alcoholic hallucinosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-223-1","text":"Fear of the voices makes him want to drink again","bucket":"perpetuating"},{"id":"form-223-2","text":"Poor sleep and anxiety","bucket":"perpetuating"},{"id":"form-223-3","text":"Earlier withdrawal fits once","bucket":"predisposing"},{"id":"form-223-4","text":"Wife who wants him to get treatment","bucket":"protective"},{"id":"form-223-5","text":"He runs a stationery shop near a school","bucket":"distractor"},{"id":"form-223-6","text":"Stopped drinking suddenly after his wife threatened to leave","bucket":"precipitating"},{"id":"form-223-7","text":"Drinks a bottle of whisky a day for fifteen years","bucket":"predisposing"},{"id":"form-223-8","text":"Hears men threatening to kill him, starting two days after he stopped drinking","bucket":"presenting"},{"id":"form-223-9","text":"Fully alert, oriented and with no tremor or confusion","bucket":"presenting"},{"id":"form-223-10","text":"Motivated to stay off alcohol","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Gowda, 48, presents with alcoholic hallucinosis: threatening auditory hallucinations in clear consciousness after stopping heavy drinking. Unlike delirium tremens, he is alert and oriented without confusion. Long heavy use and a past withdrawal fit (predisposing) raise his risk; sudden stopping (precipitating) triggered the episode. The pull to drink to quiet the voices, poor sleep and anxiety (perpetuating) are risks for relapse. A supportive wife and his motivation (protective) help. It usually settles within weeks with abstinence and short-term antipsychotic medicine, alongside thiamine and relapse prevention. His shop is a distractor.","hint":"A 48-year-old who hears threatening voices while fully alert","tags":{"topic":"substance","difficulty":2,"objective":"Recognise alcohol-related hallucinations in clear consciousness","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"substance","diagnosis":"Alcoholic hallucinosis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-224', 'Pandit ji: the minister''s secret adviser (chronic schizophrenia with grandiose delusions)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-224-1","text":"Believes he is the secret adviser to ministers and that his prayers control the weather","bucket":"presenting"},{"id":"form-224-2","text":"Stopped medicine three months ago after a new chemist ran out of stock","bucket":"precipitating"},{"id":"form-224-3","text":"Illness began in his twenties","bucket":"predisposing"},{"id":"form-224-4","text":"He knows many Sanskrit verses by heart","bucket":"distractor"},{"id":"form-224-5","text":"Hears voices that praise him, for many years","bucket":"presenting"},{"id":"form-224-6","text":"Lives alone in a room at the temple","bucket":"perpetuating"},{"id":"form-224-7","text":"Temple trustee who looks out for him","bucket":"protective"},{"id":"form-224-8","text":"Brother with a similar illness","bucket":"predisposing"},{"id":"form-224-9","text":"Temple visitors who humour his claims","bucket":"perpetuating"},{"id":"form-224-10","text":"Calm and kind to others","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pandit ji, 60, presents with chronic schizophrenia with grandiose delusions and voices that praise him, worse after a gap in medicine. Early-onset illness and a brother with the same illness (predisposing) form the base; running out of medicine (precipitating) led to worsening. Visitors humouring his claims and living alone (perpetuating) keep the beliefs unchallenged. His calm, kind nature and a caring trustee (protective) help with regular supply and follow-up. His knowledge of verses is a distractor.","hint":"A 60-year-old temple priest who says he guides the government","tags":{"topic":"psychosis","difficulty":1,"objective":"Sort a long-standing grandiose delusional picture into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"psychosis","diagnosis":"Schizophrenia with grandiose delusions"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-225', 'Soumya: the figure at the foot of the bed (sleep paralysis, not psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-225-1","text":"Wakes unable to move for a minute and sees a dark figure at the foot of her bed","bucket":"presenting"},{"id":"form-225-2","text":"Roommate who is supportive","bucket":"protective"},{"id":"form-225-3","text":"She studies zoology","bucket":"distractor"},{"id":"form-225-4","text":"No daytime voices, odd beliefs or decline","bucket":"protective"},{"id":"form-225-5","text":"Sleeps on her back after late nights","bucket":"perpetuating"},{"id":"form-225-6","text":"Cousin told stories about a ghost that sits on sleepers","bucket":"predisposing"},{"id":"form-225-7","text":"Irregular sleep since joining college","bucket":"predisposing"},{"id":"form-225-8","text":"Happens a few times a month, only on waking","bucket":"presenting"},{"id":"form-225-9","text":"All-night study before semester exams","bucket":"precipitating"},{"id":"form-225-10","text":"Hears voices during the day that comment on her","bucket":"distractor"},{"id":"form-225-11","text":"Fear of the episodes makes her avoid sleep","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Soumya, 20, presents with isolated sleep paralysis with frightening hallucinations on waking: brief inability to move with a vivid sense of a presence. Irregular sleep and cultural stories of a sitting ghost (predisposing) shape both the risk and how she reads the experience; all-night study (precipitating) triggered more episodes. Avoiding sleep and lying on her back after late nights (perpetuating) make episodes more likely. No daytime psychotic symptoms and a supportive roommate (protective) are reassuring. Explaining what sleep paralysis is, regular sleep and less sleep deprivation usually help. The card about daytime voices is left out because she has none; that would point to psychosis. Her subject is a distractor. Frequent episodes with daytime sleepiness would need checking for narcolepsy.","hint":"A 20-year-old hostel student who wakes unable to move","tags":{"topic":"sleep","difficulty":4,"objective":"Tell sleep-related hallucinations apart from psychosis","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"more-disorders","diagnosis":"Isolated sleep paralysis with hallucinations on waking"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-226', 'Ramdas: the fits and the new suspicion (psychosis with neurocysticercosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-226-1","text":"New seizures and suspicion that his wife is poisoning him, for two months","bucket":"presenting"},{"id":"form-226-2","text":"Village believes he is possessed","bucket":"perpetuating"},{"id":"form-226-3","text":"Rural home with pigs nearby and limited clean water","bucket":"predisposing"},{"id":"form-226-4","text":"Government hospital offering free treatment","bucket":"protective"},{"id":"form-226-5","text":"Brother who will bring him for follow-up","bucket":"protective"},{"id":"form-226-6","text":"He grows onions and soybean","bucket":"distractor"},{"id":"form-226-7","text":"No psychiatric history","bucket":"predisposing"},{"id":"form-226-8","text":"Stopped anti-seizure tablets because of cost","bucket":"perpetuating"},{"id":"form-226-9","text":"Infection with pork tapeworm larvae that formed several cysts in his brain","bucket":"precipitating"},{"id":"form-226-10","text":"Headaches and slowed thinking","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ramdas, 35, presents with psychosis due to neurocysticercosis, a brain infection with pork tapeworm larvae that is a common cause of seizures in India. Living conditions that raise exposure and no psychiatric history (predisposing) point towards an organic cause; the cysts in his brain, seen on a scan (precipitating), explain the new seizures and psychosis. Stopping seizure medicine due to cost and a possession explanation (perpetuating) delay care. Free hospital treatment and a supportive brother (protective) make full treatment possible, combining anti-seizure medicine, treatment of the cysts as the neurologist advises and a short course of antipsychotic medicine. His crops are a distractor.","hint":"A 35-year-old farmer with new seizures and paranoid ideas","tags":{"topic":"psychosis","difficulty":3,"objective":"Include a common Indian brain infection in a new psychosis formulation","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Psychotic disorder due to neurocysticercosis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Harsha, 31: the code that stopped compiling in his head', 'lib-cr-001', 'cooperative', '{"case_id":"cr-001","slug":"lib-cr-001","title":"Harsha, 31: the code that stopped compiling in his head","difficulty":"cooperative","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Harsha Gowda","age":31,"gender":"male","occupation":"backend developer at a payments start-up","city":"Bengaluru","family_structure":"lives with his wife Pallavi; parents in Mandya","language_register":"fluent IT English with Kannada asides, apologetic"},"presentation":"Two months of low mood, loss of interest, broken sleep with early waking, poor focus and guilt about letting his team down. Still working, barely.","chief_complaint_in_own_words":"My manager says my pull requests have become sloppy. He is right. I read the same line ten times. I used to love this work and now I just stare at it.","history":{"timeline":"Started after a failed product launch eight weeks ago. Wakes at 4 am, cannot get back to sleep, stopped evening cricket, appetite down, has lost about 4 kg.","prior_episodes":"none","substance_use":"two beers at weekends, unchanged","medical":"fit, no illness","family":"mother had a ''nervous weakness'' after his sister''s birth","treatment_history":"none","help_seeking_delay":"two months","prior_contacts":["a colleague who suggested a meditation app"]},"cognitive_model":{"core_belief":"If I am not productive, I am worthless.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has stopped playing cricket with his old college group, which he did every Sunday for nine years.","gate":"two_or_more_reflective_statements"},{"fact":"He feels he is a burden to Pallavi and has started sleeping on the sofa so his waking does not disturb her.","gate":"validation_given"},{"fact":"He has quietly applied for leave and is ashamed of it.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It is just work pressure, everyone in tech has this."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Passive thoughts that it would not matter if he did not wake up, on bad mornings. No plan, no intent, no past attempts. Strong reason to live: Pallavi and his parents.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored the core symptoms: mood, interest, sleep, appetite, energy, concentration and guilt","Asked about suicide clearly and followed passive thoughts to plan and intent","Used open questions and reflections before advice","Asked about functioning at work and at home","Gave brief psychoeducation that this is a treatable condition, not weakness"],"few_shot":[],"fixture_lines":["I wake at four. Every day, four. The ceiling fan, the auto horns starting up, and my brain already running the stand-up meeting I have not had yet.","Cricket on Sunday was my whole week. Nine years with the same boys. I told them my knee is bad. My knee is fine.","Food tastes like cardboard. Pallavi makes ragi mudde the way I like and I eat three bites and feel full.","The launch failed. Fine, launches fail. But I keep replaying it like it was my fault alone, and it was not, I know that, but knowing does not help.","I am not sad exactly. It is more like the colour has been turned down on everything."],"variation":{"mood_today":["flat","apologetic","tired"],"recent_event":["a manager''s review email","missed the Sunday cricket again","Pallavi cried last night"],"most_defended_topic":["sleeping on the sofa"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["fluent IT English with Kannada asides, apologetic"]},"moves":{},"module_id":"depression","voice_key":"fluent IT English with Kannada asides, apologetic@Bengaluru","protective_factors":["close marriage","employer health cover"],"library":{"level":1,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise the core features of a depressive episode in a working adult","expected_mse":{"appearance":"Neatly dressed, unshaven, dark circles","behaviour":"Slowed, little eye contact, fidgets with phone","speech":"Soft, slow, reduced in amount, answers fully when asked","mood":"''Grey, like the colour is turned down''","affect":"Depressed, reactive only a little, restricted range","thought_form":"Logical and goal-directed","thought_content":"Guilt about the launch, worthlessness, passive death wishes, no plan","perception":"No abnormal perceptions","cognition":"Alert, oriented; poor concentration on serial sevens","insight_judgement":"Partial insight: calls it stress, accepts help"},"diagnosis":"Moderate depressive episode (single episode)","differentials":[{"dx":"Adjustment disorder","why_not":"Symptoms are too many and too pervasive (anhedonia, early waking, weight loss, guilt) and meet full episode criteria"},{"dx":"Hypothyroidism","why_not":"No cold intolerance, constipation or weight gain; thyroid function still worth checking"},{"dx":"Burnout","why_not":"Not a diagnosis that explains the anhedonia spreading beyond work and the guilt"}],"debrief_rubric":["Explored the core symptoms: mood, interest, sleep, appetite, energy, concentration and guilt","Asked about suicide clearly and followed passive thoughts to plan and intent","Used open questions and reflections before advice","Asked about functioning at work and at home","Gave brief psychoeducation that this is a treatable condition, not weakness"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mrs Kulkarni, 49: the teacher who has always been ''like this''', 'lib-cr-002', 'guarded', '{"case_id":"cr-002","slug":"lib-cr-002","title":"Mrs Kulkarni, 49: the teacher who has always been ''like this''","difficulty":"guarded","traps":["under_diagnosis","misattributed_diagnosis"],"traps_authored":["under_diagnosis","misattributed_diagnosis"],"identity":{"name":"Shubhangi Kulkarni","age":49,"gender":"female","occupation":"Marathi teacher at a government school","city":"Nagpur","family_structure":"married, one son at college in Pune","language_register":"precise Marathi-English, dry humour, never complains for long"},"presentation":"Low, joyless mood most days for many years, poor self-esteem, tiredness and pessimism, never free of it for more than a few weeks. Works and copes. Came because her son said she ''never smiles in photos''.","chief_complaint_in_own_words":"I am not ill. I have always been a gloomy person. My son made the appointment. He says I should be happier. I said, show me how.","history":{"timeline":"Says she has felt this way ''since my twenties, after my father''s business failed''. Never a time of feeling well for longer than a month. No period of full collapse; no sustained worsening in the last months.","prior_episodes":"no hospital stays; no high periods","substance_use":"none","medical":"mild hypertension on amlodipine","family":"father was ''serious and silent''","treatment_history":"a tonic from the family doctor ten years ago","help_seeking_delay":"decades","prior_contacts":["family doctor","temple"]},"cognitive_model":{"core_belief":"Joy is for other people; my job is to endure.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She cannot remember a single month in the last twenty-five years when she felt light.","gate":"two_or_more_reflective_statements"},{"fact":"She marks her students'' notebooks until midnight because she believes she is a mediocre teacher, though her results are the best in the school.","gate":"validation_given"},{"fact":"She envies her sister''s ease and feels guilty about the envy.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Everybody my age is tired. It is the menopause, the doctor said."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no thoughts of ending her life now or ever; ''I am too stubborn to give up.'' No self-harm.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Established the time course: years without a clear well period","Checked for a superimposed worsening (double depression)","Asked about mania or highs to rule out a bipolar course","Asked about suicide clearly despite her stoic front","Explained that long-standing low mood is treatable, not just personality"],"few_shot":[],"fixture_lines":["I get up, I teach, I come home, I correct notebooks. Thirty-eight notebooks a night. It is not suffering. It is just life.","My son says I never smile in photos. I tell him photographers make everyone look like that. He does not laugh.","If you are asking whether I am sadder now than before, no. I am exactly as I always was. That is perhaps the problem.","My sister laughs easily. I used to think she was shallow. Now I think she just has a lighter engine.","Holidays are the worst. In school at least there is a timetable to hide behind."],"variation":{"mood_today":["dry","flat","wary"],"recent_event":["her son posted a family photo","a colleague retired","the school inspection"],"most_defended_topic":["her envy of her sister"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["precise Marathi-English, dry humour, never complains for long"]},"moves":{},"module_id":"depression","voice_key":"precise Marathi-English, dry humour, never complains for long@Nagpur","protective_factors":["meaningful work","son who cares"],"library":{"level":4,"topic":"depression","module":"depression","exams":["mcp-entrance","md-psychiatry","ugc-net"],"objective":"Tell persistent low-grade low mood apart from a discrete depressive episode","expected_mse":{"appearance":"Tidy cotton saree, hair tightly tied","behaviour":"Upright, controlled, little gesture","speech":"Normal rate, clipped, sardonic","mood":"''Normal for me, which is grey''","affect":"Mildly depressed, restricted but reactive to humour","thought_form":"Coherent","thought_content":"Long-standing pessimism and low self-worth; no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Partial: sees it as her nature, not a condition"},"diagnosis":"Persistent depressive disorder (dysthymia), early onset","differentials":[{"dx":"Major depressive episode","why_not":"No discrete period of marked worsening with full criteria; the picture is chronic and steady"},{"dx":"Personality style (depressive temperament)","why_not":"The duration and impairment of joy and self-esteem fit a treatable mood disorder; temperament does not explain the distress she describes"},{"dx":"Hypothyroidism","why_not":"Should be checked, but decades of steady course without physical signs argue against"}],"debrief_rubric":["Established the time course: years without a clear well period","Checked for a superimposed worsening (double depression)","Asked about mania or highs to rule out a bipolar course","Asked about suicide clearly despite her stoic front","Explained that long-standing low mood is treatable, not just personality"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Bhattacharya, 67: up at three, worst in the morning', 'lib-cr-003', 'guarded', '{"case_id":"cr-003","slug":"lib-cr-003","title":"Mr Bhattacharya, 67: up at three, worst in the morning","difficulty":"guarded","traps":["late_risk_reveal","under_diagnosis"],"traps_authored":["late_risk_reveal","under_diagnosis"],"identity":{"name":"Debashis Bhattacharya","age":67,"gender":"male","occupation":"retired railway accountant","city":"Kolkata","family_structure":"lives with wife Kalyani in a Salt Lake flat; daughter in Hyderabad","language_register":"formal Bengali-English, slow, long pauses"},"presentation":"Three months of profound loss of pleasure, early morning waking, mood worst in the morning, marked slowing, weight loss of 7 kg, and excessive guilt about a decades-old office matter.","chief_complaint_in_own_words":"Nothing gives me any feeling. Not my grandson''s voice on the phone, not Rabindrasangeet. Mornings are like walking through wet sand.","history":{"timeline":"Insidious onset three months ago without a clear trigger. Wakes at 3 am. Better by evening. Stopped reading the newspaper, his lifelong habit.","prior_episodes":"one similar episode at 52, treated with an antidepressant, full recovery","substance_use":"none","medical":"diabetes on metformin; recent HbA1c fine","family":"brother died by suicide at 60","treatment_history":"the antidepressant at 52; stopped after a year","help_seeking_delay":"three months","prior_contacts":["family physician who checked his sugar"]},"cognitive_model":{"core_belief":"I am a guilty man and this is what I deserve.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He believes a 1987 accounting error he made cost a clerk his promotion, and he has been ''paying for it'' every night since.","gate":"validation_given"},{"fact":"He no longer feels any pleasure when his grandson calls; he pretends for his wife.","gate":"two_or_more_reflective_statements"},{"fact":"His older brother died by suicide at 60 after a similar spell; he has not told the doctor before.","gate":"asked_open_about_family"}],"resistance":{"deflections":["At my age, what do you expect? The body slows."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: thinks his family would be better without him, has thought of ''not taking his tablets and letting it end'' but no active plan yet. High-risk profile: older man, prior episode, family history of suicide, guilt. Needs urgent psychiatric review.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Elicited melancholic features: early waking, diurnal variation, non-reactive mood, slowing, weight loss","Took the family history of suicide and linked it to risk","Asked about suicide clearly and recognised a high-risk profile in an older man","Asked about past response to treatment","Arranged urgent review rather than routine follow-up"],"few_shot":[],"fixture_lines":["I wake at three. The clock in the hall chimes. I lie and count my failures until the milkman comes.","By evening I am slightly human. By morning, nothing again.","Kalyani makes my favourite fish curry. I eat to please her. It tastes of nothing at all.","There was a clerk, Biswas, in 1987. My figures were wrong. He lost his promotion. I think of him every night now.","I have stopped reading Anandabazar. Forty years, every morning. Now the words just lie on the page."],"variation":{"mood_today":["heavy","slowed","guilty"],"recent_event":["his grandson''s birthday call","Kalyani found him sitting in the dark at 4 am","news of an old colleague''s death"],"most_defended_topic":["his brother''s death"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["formal Bengali-English, slow, long pauses"]},"moves":{},"module_id":"depression","voice_key":"formal Bengali-English, slow, long pauses@Kolkata","protective_factors":["devoted wife","past full recovery"],"library":{"level":3,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance"],"objective":"Identify melancholic features and their treatment implications","expected_mse":{"appearance":"Thin, clothes loose, unshaven","behaviour":"Marked psychomotor slowing, long latency before answers","speech":"Slow, soft, monotonous","mood":"''Nothing, no feeling''","affect":"Depressed, non-reactive","thought_form":"Slowed but coherent","thought_content":"Excessive guilt about a past error; hopelessness; thoughts family better off without him","perception":"No hallucinations elicited","cognition":"Oriented; slowed attention, effort poor","insight_judgement":"Partial: accepts he is unwell, believes he deserves it"},"diagnosis":"Severe depressive episode with melancholic features, recurrent","differentials":[{"dx":"Early dementia","why_not":"Onset over weeks with mood change first, morning worsening and guilt point to depression; cognitive slowing is likely part of it, recheck after recovery"},{"dx":"Psychotic depression","why_not":"Guilt is excessive but still within the bounds of an overvalued idea; probe for fixed guilt delusions or nihilism"},{"dx":"Hypothyroidism or other medical cause","why_not":"Needs bloods, but a prior identical episode that responded to antidepressants supports a recurrent mood disorder"}],"debrief_rubric":["Elicited melancholic features: early waking, diurnal variation, non-reactive mood, slowing, weight loss","Took the family history of suicide and linked it to risk","Asked about suicide clearly and recognised a high-risk profile in an older man","Asked about past response to treatment","Arranged urgent review rather than routine follow-up"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
